-- TS - AI Ideas Hub — Core Competency content seed
--
-- Core Competency's actual content: 37 real resources at the Intern (P1)
-- tier (36 from the original import below, plus 1 added by a later
-- reconciliation — see that reconciliation's own comment for why the count
-- moved), the Intern (P1) slice of Skedulo TS's own career-ladder learning
-- plan (imported from "TS_Career_Track__Intern_P1_Learning_Plan.xlsx", one
-- tab per competency — Troubleshooting, Custom vs Core, Process and
-- Procedures, Tools and Systems, SLAs and Deliverables, Incident Management
-- & Escalation, Culture Champion, Growth and Learning, Cross-Functional
-- Collaboration, Performance Excellence, Change Driver & Innovator,
-- Customer First mindset), and its own 8-skill taxonomy (courses.skills).
-- Split out of ai-track-seed.sql into its own file so each track's content
-- can be edited and re-run independently — that file now carries only the
-- AI Track.
--
-- Naming history, since it's touched two names already: this content was
-- first drafted as a brand-new third track, "Career Track" — until the
-- product owner pointed out Core Competency (see 01-course-catalog.md, 2.1)
-- had been sitting empty for exactly this kind of content all along, and
-- asked for the two to become one. So: this file creates the Core
-- Competency track row (moved here from ai-track-seed.sql, since this is
-- now the file that actually populates it) and, as its very first
-- statements, reconciles any database that already ran the old "Career
-- Track" version — reattaching its courses and enrollments to Core
-- Competency, then dropping the now-empty Career Track row. All three
-- reconciliation statements are no-ops on a database that never created
-- "Career Track" in the first place.
--
-- A second, later reconciliation (below the main course INSERT) brings
-- this tier in line with a newer revision of the source spreadsheet — see
-- that block's own comment. Unlike every other reconciliation in this
-- file, it's deliberately UPDATE/INSERT only, never DELETE: this track has
-- real learners with real course_assignments and course_quiz_questions
-- rows now, both on delete cascade (schema.sql), so a DELETE here risks
-- erasing a real learner's progress with no way back.
--
-- Not destructive to run — every insert here is ON CONFLICT DO NOTHING,
-- safe to re-run on a database that already has some or all of this
-- content. The skills UPDATE is re-runnable for a different reason (plain
-- UPDATE, not an insert) — see the comment there; that's the block to edit
-- and re-run on its own if the skill taxonomy needs to change later.
--
-- Run schema.sql first (needs tracks/courses/course_assignments and
-- course_quiz_questions — the quiz insert below the main course list
-- needs that last one).

insert into tracks (name) values ('Core Competency')
on conflict (name) do nothing;

-- Fold an already-seeded "Career Track" into Core Competency, for anyone
-- who ran an earlier version of this file under that name. courses.track_id
-- is ON DELETE SET NULL (schema.sql), not CASCADE — dropping the Career
-- Track row without reattaching its courses first would silently orphan
-- them (no track, invisible everywhere). account_tracks.track_id IS ON
-- DELETE CASCADE, and an enrollment is meant to never be lost once made
-- (03-your-journey.md, 4.5) — so that gets reattached first too, guarded
-- against the rare case where an account is already enrolled in both (that
-- account_tracks primary key is (account_id, track_id); reattaching would
-- collide, so anyone already in both just keeps the Core Competency row and
-- loses the redundant Career Track one when it's dropped below).
update courses set track_id = (select id from tracks where name = 'Core Competency')
where track_id = (select id from tracks where name = 'Career Track');

update account_tracks set track_id = (select id from tracks where name = 'Core Competency')
where track_id = (select id from tracks where name = 'Career Track')
  and account_id not in (
    select account_id from account_tracks where track_id = (select id from tracks where name = 'Core Competency')
  );

delete from tracks where name = 'Career Track';

-- Reconciliation against an earlier version of the source spreadsheet: 7
-- resources were dropped from the plan and 1 was renamed (dropped its
-- "Udemy: " title prefix; every other field is unchanged, confirmed by
-- diffing the two spreadsheet versions). Both statements are no-ops on a
-- database that never ran the earlier version — DELETE matches nothing,
-- UPDATE...WHERE matches nothing — so this is safe to run either way.
-- The DELETE cascades to course_assignments (schema.sql's own
-- "on delete cascade" on course_id) — if a learner had already started one
-- of these 7 under the old plan, that progress goes with it. Given this
-- track hadn't shipped to production learners as of this writing, that's a
-- real but currently theoretical risk, not an active one.
update courses set title = 'Curiosity and Lifelong Learning'
where title = 'Udemy: Curiosity and Lifelong Learning'
  and track_id = (select id from tracks where name = 'Core Competency');

delete from courses
where track_id = (select id from tracks where name = 'Core Competency')
  and title in (
  'Using Claude AI when investigating issues + How Support Can Use Claude (handbook)',
  'Skedulo Web App (Skedulo Pulse Platform)',
  'Admin Console (internal tool)',
  'TED playlist — How to be a good mentor (for being mentored well, then mentoring)',
  'TED — Julian Treasure: How to speak so that people want to listen',
  'TED — Margaret Heffernan: Forget the pecking order at work',
  'Who actually uses Skedulo — support workers, nurses and carers in the field on Skedulo Plus'
);

-- 36 real resources — see file header. Every row below is still typed as
-- 'L0 — Foundations' / 'intern', exactly as the original source file had
-- it; 6 of them (5 to 'junior', 1 to 'middle') get moved to a higher tier
-- by the reconciliation UPDATE below, once this INSERT has (re)established
-- the row on a fresh run — ON CONFLICT DO NOTHING here means the
-- reconciliation's tier change, not this literal 'intern', is what actually
-- sticks after both have run. roadmap_order (migration 030) is
-- set directly here (1-36, the source file's own tab-then-row order) —
-- there's no pre-existing data on a fresh run of this file to reconcile
-- with, unlike the AI Track's own courses, which needed a separate
-- backfill UPDATE when that column was added after the fact.
--
-- Cleanup applied on the way in: focus_area is normalized once ('Incident
-- Mgmt & Escalation' -> 'Incident Management & Escalation' — a spelling
-- inconsistency in the source's own tab, row 1 only, the other rows on
-- that tab already spell it out) and every text field is trimmed. priority
-- is blank on exactly one source row (Linear Basic Training) — defaulted
-- to 'optional', this column's own schema default, rather than guessing
-- 'core'.
insert into courses (track_id, stage, focus_area, title, platform, priority, est_hours, cost, outcome, expected_by_position, link, roadmap_order)
select (select id from tracks where name = 'Core Competency'), v.*
from (values
  ('L0 — Foundations', 'Troubleshooting', 'Trailhead module: Best Practices for Troubleshooting', 'Salesforce Trailhead', 'core', 0.5, 'Free', 'Applies the identify, replicate, hypothesise, implement cycle to isolate a reported fault.', 'intern', 'https://trailhead.salesforce.com/content/learn/modules/troubleshooting-best-practices', 1),
  ('L0 — Foundations', 'Custom vs Core', 'Skedulo Pulse Admin Fundamentals', 'Confluence', 'core', 12.0, 'Free', 'Configures a tenant end to end - settings, data objects, custom fields, regions, availability, jobs, allocation and dispatch', 'intern', 'https://skedulo.atlassian.net/wiki/spaces/EN/pages/3519414283/Skedulo+Admin+Certificate+-+Courses?xpis=eyJicmlkZ2UiOiJzZWFyY2hQYWdlIiwiaWQiOiIxNzg4ODg5NzE1NTUyIiwic291cmNlIjoiY29uZmx1ZW5jZSJ9', 2),
  ('L0 — Foundations', 'Custom vs Core', 'Salesforce Basics', 'Salesforce Trailhead', 'core', 0.75, 'Free (exam fee applies)', 'Distinguishes standard Salesforce platform objects and features from customer customisation.', 'intern', 'https://trailhead.salesforce.com/content/learn/modules/starting_force_com?trailmix_creator_id=brasmussen2&trailmix_slug=salesforce-for-skedulo', 3),
  ('L0 — Foundations', 'Custom vs Core', 'Skedulo release notes — track what''s new each release', 'support.skedulo.com', 'core', 1.0, 'Free', 'Tracks each release and links a customer-reported change to the note that introduced it.', 'intern', 'https://www.skedulo.com/release-notes/', 4),
  ('L0 — Foundations', 'Custom vs Core', 'Skedulo Pulse Platform: Setup Resources → Complete Job as a Resource', 'Internal', 'core', 2.0, 'Free (internal)', 'Completes the full Salesforce hands-on exercise — sets up a resource, region, availability, job, allocation, dispatch, and closes it out from the mobile app.', 'intern', 'https://docs.google.com/presentation/d/1sgK73gahkpO5qMOEsPCC3QDawA1fuKHF2jtfB6rGFqM/edit?slide=id.g2149ccd6c42_0_39#slide=id.g2149ccd6c42_0_39', 5),
  ('L0 — Foundations', 'Custom vs Core', 'Skedulo Pulse Platform: Onboarding, General Settings, Preferences, Navigations, Customize Scheduling Workflow, Create and Manage Data Object, Manage Custom Fields, Using Dynamic Messaging', 'Internal', 'core', 4.0, 'Free (internal)', 'Configures a Pulse Platform tenant''s core settings, preferences, navigation, scheduling workflow, custom data objects and fields, and turns on dynamic messaging.', 'intern', 'https://docs.google.com/presentation/d/1sgK73gahkpO5qMOEsPCC3QDawA1fuKHF2jtfB6rGFqM/edit?slide=id.g2140755c851_0_38#slide=id.g2140755c851_0_38', 6),
  ('L0 — Foundations', 'Custom vs Core', 'Internal Platform Deep Dive', 'Internal', 'core', 8.0, 'Free (internal)', 'Works across Skedulo''s core internal tools — web app internals, GraphQL, Optimization, Skedulo Plus, Datadog, Admin Console, Analytics, MEX, Amplitude dashboards and Twilio — well enough to investigate a ticket that touches any one of them.', 'intern', 'https://docs.google.com/presentation/d/1sgK73gahkpO5qMOEsPCC3QDawA1fuKHF2jtfB6rGFqM/edit?slide=id.g2c802980b9b_0_14#slide=id.g2c802980b9b_0_14', 7),
  ('L0 — Foundations', 'Process and Procedures', 'Shared Ticketing Process – Skedulo & Lumary + Customer Admin Account Recovery procedure', 'Internal', 'core', 0.25, 'Free (internal)', 'Routes a ticket shared with Lumary to the right queue and follows the customer admin account recovery steps.', 'intern', 'https://skedulo.atlassian.net/wiki/spaces/SUP/pages/3405119552/Shared+Ticketing+Process+Skedulo+Lumary', 8),
  ('L0 — Foundations', 'Process and Procedures', 'Skedulo AI Usage Policy + Information Security policies (customer data handling)', 'Internal', 'core', 0.5, 'Free (internal)', 'Follows the AI Usage Policy and information security policies when handling customer data, and knows when to ask before sharing it.', 'intern', 'https://skedulo.atlassian.net/wiki/spaces/IS/pages/3355443246/Artificial+Intelligence+AI+Usage+Policy', 9),
  ('L0 — Foundations', 'Process and Procedures', 'Atlassian ITSM & incident guides', 'Free — Atlassian', 'core', 0.2, 'Free', 'Uses standard ITSM vocabulary - incident, service request, problem, change - when reading and writing tickets.', 'intern', 'https://www.atlassian.com/itsm', 10),
  ('L0 — Foundations', 'Process and Procedures', 'Shared Ticketing Process – Skedulo & Lumary', 'Internal', 'core', 0.25, 'Free', 'Routes a ticket shared with Lumary to the right queue.', 'intern', 'https://skedulo.atlassian.net/wiki/spaces/SUP/pages/3405119552/Shared+Ticketing+Process+Skedulo+Lumary', 11),
  ('L0 — Foundations', 'Process and Procedures', 'How to Create a Linear Issue via DevRev — always via DevRev, never directly in Linear', 'Internal', 'core', 0.25, 'Free (internal)', 'Raises a Linear issue only through the DevRev template, and confirms it was created via the Linear icon or Slack.', 'intern', 'https://skedulo.atlassian.net/wiki/spaces/SUP/pages/4407459846/How+to+Create+a+Linear+Issue+via+DevRev', 12),
  ('L0 — Foundations', 'Tools and Systems', 'Datadog Quick Start', 'Free — Datadog', 'core', 1.0, 'Free', 'Navigates dashboards, filters and inspects logs, and finds a service owner in Catalog.', 'intern', 'https://learn.datadoghq.com/courses/course-quickstart', 13),
  ('L0 — Foundations', 'Tools and Systems', 'Linear Basic Training', 'Internal', 'optional', 1.5, 'Free', 'Navigates the SUP board, subscribes to an issue, and applies the correct repo label.', 'intern', 'https://skedulo.atlassian.net/wiki/spaces/Certinia/pages/4341792769/Linear+Basic+Training', 14),
  ('L0 — Foundations', 'Tools and Systems', 'GraphQL (Skedulo Pulse Platform)', 'Internal', 'core', 3.0, 'Free', 'Runs a filtered GraphiQL query against a tenant and reads back the error a failed query returns.', 'intern', 'https://docs.google.com/presentation/d/1XTDlcja-YqhcQyabBdMu_7ySHmpAQvlSKhhnq5vRqUQ/edit?usp=sharing', 15),
  ('L0 — Foundations', 'SLAs and Deliverables', 'Technical support plans and SLAs', 'support.skedulo.com', 'core', 0.25, 'Free (internal)', 'Identifies a customer''s support plan and the response target that applies to their ticket.', 'intern', 'https://docs.skedulo.com/user-guides/support/technical-support-plans-and-slas/', 16),
  ('L0 — Foundations', 'SLAs and Deliverables', 'Atlassian SLA & service-request management guide', 'Free — Atlassian', 'core', 0.25, 'Free', 'Explains what an SLA, SLO and SLI are, and how a support queue is measured against them.', 'intern', 'https://www.atlassian.com/itsm/service-request-management/slas', 17),
  ('L0 — Foundations', 'Incident Management & Escalation', 'Escalation Workflow — the team''s Lucidchart escalation diagram', 'Internal', 'core', 0.25, 'Free (internal)', 'Traces a ticket through the escalation path and names who to notify at each step.', 'intern', 'https://lucid.app/lucidchart/2949a39e-7740-4ad9-9ff2-7dea83d42406/edit', 18),
  ('L0 — Foundations', 'Incident Management & Escalation', 'Incident Analysis Report (Aug 2025–Aug 2026) — severity mix, detection methods, trends', 'Internal', 'core', 0.5, 'Free (internal)', 'Reads Skedulo''s incident history - severity mix, detection method and contributing factors - and recognises the recurring failure patterns.', 'intern', 'https://skedulo.atlassian.net/wiki/spaces/SUP/pages/4653252611/Incident+Analysis+Report+August+2025+to+August+2026', 19),
  ('L0 — Foundations', 'Incident Management & Escalation', 'Account Map & Service Catalog', 'Internal', 'core', 0.5, 'Free (internal)', 'Looks up which squad owns a product area and which accounts an issue affects before escalating.', 'intern', 'https://skedulo.atlassian.net/wiki/spaces/SUP/pages/4308336655/Account+Map+Service+Catalog', 20),
  ('L0 — Foundations', 'Incident Management & Escalation', 'DevRev To Linear SUP tickets Workflow — how a customer ticket becomes an engineering issue', 'Internal', 'core', 0.25, 'Free (internal)', 'Follows a DevRev ticket into a SUP Linear issue and finds the team Slack channel to chase it.', 'intern', 'https://skedulo.atlassian.net/wiki/spaces/SUP/pages/4377477124/DevRev+To+Linear+SUP+tickets+Workflow', 21),
  ('L0 — Foundations', 'Culture Champion', 'TED — Simon Sinek: Why good leaders make you feel safe', 'TED', 'core', 0.2, 'Free', 'Explains why psychological safety changes how a team reports problems.', 'intern', 'https://www.ted.com/talks/simon_sinek_why_good_leaders_make_you_feel_safe', 22),
  ('L0 — Foundations', 'Culture Champion', 'Embracing a Culture of Feedback', 'Udemy', 'core', 1.0, 'Free', 'Gives and receives feedback in a way that keeps the working relationship intact.', 'intern', 'https://skedulo.udemy.com/course/embracing-feedback/', 23),
  ('L0 — Foundations', 'Culture Champion', 'TED — Vernā Myers: How to overcome our biases? Walk boldly toward them', 'TED', 'core', 0.3, 'Free', 'Recognises own bias in a customer or colleague interaction and names it.', 'intern', 'https://www.ted.com/talks/verna_myers_how_to_overcome_our_biases_walk_boldly_toward_them', 24),
  ('L0 — Foundations', 'Growth and Learning', 'Curiosity and Lifelong Learning', 'Udemy Business', 'optional', 1.5, 'Udemy Business', 'Builds a habit of deliberate learning and reflection alongside daily ticket work.', 'intern', 'https://skedulo.udemy.com/course/curiosity-and-lifelong-learning/', 25),
  ('L0 — Foundations', 'Growth and Learning', 'TED — Carol Dweck: The power of believing that you can improve', 'TED', 'core', 0.2, 'Free', 'Treats a hard ticket as a skill to develop rather than a fixed limit.', 'intern', 'https://www.ted.com/talks/carol_dweck_the_power_of_believing_that_you_can_improve', 26),
  ('L0 — Foundations', 'Growth and Learning', 'The Complete Storytelling Course for Speaking & Presenting', 'Udemy Business', 'optional', 35.5, 'Udemy Business', 'Structures an update or handover so the audience follows the point.', 'intern', 'https://skedulo.udemy.com/course/the-complete-storytelling-course-for-speaking-presenting/', 27),
  ('L0 — Foundations', 'Cross-Functional Collaboration', 'Active Listening — You Can Be a Great Listener', 'Udemy Business', 'core', 2.25, 'Udemy Business', 'Draws out what a customer actually needs before proposing a fix.', 'intern', 'https://skedulo.udemy.com/course/active-listening-you-can-be-a-great-listener/', 28),
  ('L0 — Foundations', 'Cross-Functional Collaboration', 'Mastering Collaboration: Work together for the best results', 'Udemy Business', 'optional', 0.75, 'Udemy Business', 'Works with engineering and CSM counterparts without stalling on handoffs.', 'intern', 'https://skedulo.udemy.com/course/mastering-collaboration-work-together-for-the-best-results/', 29),
  ('L0 — Foundations', 'Performance Excellence', 'Productivity and Time Management for the Overwhelmed', 'Udemy Business', 'core', 1.75, 'Udemy Business', 'Plans a ticket queue day and protects time for investigation work.', 'intern', 'https://skedulo.udemy.com/course/productivity-and-time-management/', 30),
  ('L0 — Foundations', 'Performance Excellence', 'TED — Dan Pink: The puzzle of motivation', 'TED', 'core', 0.3, 'Free', 'Recognises what sustains motivation on repetitive queue work.', 'intern', 'https://www.ted.com/talks/dan_pink_the_puzzle_of_motivation', 31),
  ('L0 — Foundations', 'Performance Excellence', 'TED — Yves Morieux: How too many rules at work keep you from getting things done', 'TED', 'optional', 0.3, 'Free', 'Spots when a process step adds effort without adding value.', 'intern', 'https://www.ted.com/talks/yves_morieux_how_too_many_rules_at_work_keep_you_from_getting_things_done', 32),
  ('L0 — Foundations', 'Change Driver & Innovator', 'Creativity, problem solving and generating alternatives', 'Udemy Business', 'optional', 1.25, 'Free - Udemy', 'Generates more than one option before settling on a workaround.', 'intern', 'https://skedulo.udemy.com/course/creativity-problem-solving-and-generating-alternatives/', 33),
  ('L0 — Foundations', 'Change Driver & Innovator', 'TED — Adam Grant: The surprising habits of original thinkers', 'TED', 'core', 0.25, 'Free', 'Questions a default process and puts forward an alternative.', 'intern', 'https://www.ted.com/talks/adam_grant_the_surprising_habits_of_original_thinkers', 34),
  ('L0 — Foundations', 'Customer First mindset', 'The Customer: How to Understand Their Needs (BITE SIZE)', 'Udemy Business', 'core', 1.0, 'Udemy Business', 'Identifies the need behind a customer''s stated request.', 'intern', 'https://skedulo.udemy.com/course/customer-how-to-understand-customer-needs/', 35),
  ('L0 — Foundations', 'Customer First mindset', 'TED — Joe Gebbia: How Airbnb designs for trust', 'TED', 'core', 0.25, 'Free', 'Explains how small design and communication choices build customer trust.', 'intern', 'https://www.ted.com/talks/joe_gebbia_how_airbnb_designs_for_trust', 36)
) as v(stage, focus_area, title, platform, priority, est_hours, cost, outcome, expected_by_position, link, roadmap_order)
on conflict (track_id, title) do nothing;

-- Reconciliation against a newer revision of the source spreadsheet,
-- "TS Career Track - Learning Plan Master.xlsx" (the same file
-- junior-learning-roadmap-seed.sql and complete-course-track-core-competency-seed.sql
-- import the Junior and Specialist/Senior/Principal tiers from). This later
-- revision also touches Intern-level content: 4 resources it no longer
-- lists at any tier, 6 it moved up to a higher tier, 1 new resource, and
-- small field-level drift (platform/cost relabeling, a few est_hours
-- bumps, one priority flip, one focus_area spelling) on 9 more.
--
-- Deliberately NOT a DELETE this time, unlike the earlier-revision
-- reconciliation above. That one could still call the risk theoretical
-- ("this track hadn't shipped to production learners as of this writing");
-- this track has real learners with real course_assignments rows now, and
-- courses.id cascades on delete (schema.sql) straight through
-- course_assignments and course_quiz_questions — a DELETE here would
-- silently erase any learner's progress on that course with no way back.
-- So the 4 resources the new master no longer lists anywhere — 'Atlassian
-- ITSM & incident guides', 'How to Create a Linear Issue via DevRev...',
-- 'Shared Ticketing Process – Skedulo & Lumary + Customer Admin Account
-- Recovery procedure', and 'Skedulo release notes...' — are left exactly as
-- they are. Retiring them for real is a separate, explicit decision for
-- whoever checks first whether any learner has actually started one.
--
-- Every statement below is a plain, re-runnable UPDATE (or an
-- ON CONFLICT DO NOTHING INSERT for the one new resource) — same result
-- every time, nothing that touches course_assignments or
-- course_quiz_questions rows belonging to any other course. Placed here,
-- after the historical 36-course INSERT above rather than before it (like
-- the earlier reconciliation is), on purpose: these UPDATEs target titles
-- that INSERT creates, so on a brand-new database they'd match nothing if
-- run first — putting them after guarantees the same end state whether
-- this file is running against a fresh database or a live one.

-- 5 resources the new master reclassified from Foundation to Applied
-- (Junior Specialist) — moved, not duplicated. This is why
-- junior-learning-roadmap-seed.sql's own header says it deliberately does
-- NOT re-insert these same 5 titles: the row already exists here, this
-- UPDATE is what actually moves it. roadmap_order is left untouched on
-- purpose — renumbering these into that file's own 37-48 run would mean
-- coordinating two files for a cosmetic sort-order gain; they'll simply
-- sort ahead of that file's 12 courses within the Junior tier.
update courses set stage = 'L1 — Applied', expected_by_position = 'junior'
where track_id = (select id from tracks where name = 'Core Competency')
  and title in (
    'Shared Ticketing Process – Skedulo & Lumary',
    'GraphQL (Skedulo Pulse Platform)',
    'Incident Analysis Report (Aug 2025–Aug 2026) — severity mix, detection methods, trends',
    'TED — Vernā Myers: How to overcome our biases? Walk boldly toward them',
    'TED — Yves Morieux: How too many rules at work keep you from getting things done'
  );

-- 1 resource the new master moved two tiers up, to Intermediate (P3 /
-- 'middle') rather than Applied — same reasoning and same roadmap_order
-- treatment as the block above.
update courses set stage = 'L2 — Intermediate', expected_by_position = 'middle'
where track_id = (select id from tracks where name = 'Core Competency')
  and title = 'TED — Dan Pink: The puzzle of motivation';

-- 9 resources that stayed at Foundation but whose other fields drifted:
-- mostly a platform/cost relabel (most of the "Udemy Business" catalog is
-- now listed as "Free - Udemy" instead — same courses, same links, just a
-- renamed label in the source), a few small est_hours bumps, Linear Basic
-- Training's priority flipping optional -> core, and Escalation Workflow's
-- focus_area reverting to the "Incident Mgmt & Escalation" tab's own short
-- name (this is the same normalization the original import already made
-- once — see the comment above the main INSERT above — undone by this
-- newer revision, so re-applied here to match it).
update courses set platform = v.platform, priority = v.priority, est_hours = v.est_hours, cost = v.cost, focus_area = v.focus_area
from (values
  ('Active Listening — You Can Be a Great Listener', 'Free - Udemy', 'core', 2.5, 'Free - Udemy', 'Cross-Functional Collaboration'),
  ('Creativity, problem solving and generating alternatives', 'Free - Udemy', 'optional', 1.5, 'Free - Udemy', 'Change Driver & Innovator'),
  ('Curiosity and Lifelong Learning', 'Free - Udemy', 'optional', 1.5, 'Free - Udemy', 'Growth and Learning'),
  ('Escalation Workflow — the team''s Lucidchart escalation diagram', 'Internal', 'core', 0.25, 'Free (internal)', 'Incident Mgmt & Escalation'),
  ('Linear Basic Training', 'Internal', 'core', 1.5, 'Free', 'Tools and Systems'),
  ('Mastering Collaboration: Work together for the best results', 'Free - Udemy', 'optional', 1.0, 'Free - Udemy', 'Cross-Functional Collaboration'),
  ('Productivity and Time Management for the Overwhelmed', 'Free - Udemy', 'core', 2.0, 'Free - Udemy', 'Performance Excellence'),
  ('The Complete Storytelling Course for Speaking & Presenting', 'Free - Udemy', 'optional', 35.5, 'Free - Udemy', 'Growth and Learning'),
  ('The Customer: How to Understand Their Needs (BITE SIZE)', 'Free - Udemy', 'core', 1.0, 'Free - Udemy', 'Customer First mindset')
) as v(title, platform, priority, est_hours, cost, focus_area)
where courses.title = v.title
  and courses.track_id = (select id from tracks where name = 'Core Competency');

-- 1 new Foundation-tier resource the new master adds under Process and
-- Procedures: "Support Processes - DevRev". A quiz for it already existed
-- in the quiz workbook (tab PP-02, Foundation level) from before this
-- reconciliation — it just had no matching course to attach to until now.
-- roadmap_order 104 is a fresh number past this file's own 1-36,
-- junior-learning-roadmap-seed.sql's 37-48, and
-- complete-course-track-core-competency-seed.sql's 49-103, since every
-- number below 104 is already in use (nothing above was deleted) — it
-- sorts last within Intern rather than reshuffling Process and Procedures'
-- existing numbers for a cosmetic-only gain.
insert into courses (track_id, stage, focus_area, title, platform, priority, est_hours, cost, outcome, expected_by_position, link, roadmap_order)
select (select id from tracks where name = 'Core Competency'), v.*
from (values
  ('L0 — Foundations', 'Process and Procedures', 'Support Processes - DevRev', 'Internal', 'core', 0.25, 'Free (internal)', 'Classifies a ticket using DevRev''s Parts & Diagnosis taxonomy, applies the correct field conventions, looks up DevRev terminology, and creates a linked Linear issue from a DevRev ticket.', 'intern', 'https://skedulo.atlassian.net/wiki/spaces/SUP/folder/3323068491/Support+Processes+-+DevRev', 104)
) as v(stage, focus_area, title, platform, priority, est_hours, cost, outcome, expected_by_position, link, roadmap_order)
on conflict (track_id, title) do nothing;

update courses set skills = array['Support Process & SLAs']::text[]
where title = 'Support Processes - DevRev'
  and track_id = (select id from tracks where name = 'Core Competency');

insert into course_quiz_questions (course_id, position, question, options, correct_answer, rationale)
select c.id, v.position, v.question, v.options, v.correct_answer, v.rationale
from (values
  ('Support Processes - DevRev', 1, 'What are the two custom fields covered by the new DevRev taxonomy standard?', '[{"label": "A", "text": "Part and Diagnosis"}, {"label": "B", "text": "Impacted Area and Impact Detail"}, {"label": "C", "text": "Severity and Stage"}, {"label": "D", "text": "Product and Capability"}]'::jsonb, 'A', 'The taxonomy doc standardises how the team uses the Part and Diagnosis fields; the old Impacted Area/Impact Detail fields caused ambiguity and inconsistent data.'),
  ('Support Processes - DevRev', 2, 'What two levels make up a "Part" in the new taxonomy?', '[{"label": "A", "text": "Product and Capability"}, {"label": "B", "text": "Impacted Area and Impact Detail"}, {"label": "C", "text": "Diagnosis and Bug"}, {"label": "D", "text": "Ticket Type and Stage"}]'::jsonb, 'A', 'A Part consists of a Product (e.g., Skedulo Web App, Skedulo API) and a Capability underneath it — the main item of interaction for the customer.'),
  ('Support Processes - DevRev', 3, 'At what point in a ticket''s lifecycle should the Part field be set, and can it change later?', '[{"label": "A", "text": "During triage, and the value should not change afterward"}, {"label": "B", "text": "Only after the ticket is resolved"}, {"label": "C", "text": "Whenever the customer requests an update"}, {"label": "D", "text": "It is optional and rarely used"}]'::jsonb, 'A', 'Part identifies which area of the product the user was interacting with, and is meant to be fixed at triage time — it should not change during the ticket''s lifecycle.'),
  ('Support Processes - DevRev', 4, 'When should the Diagnosis field be finalized on a ticket?', '[{"label": "A", "text": "At the end of the ticket lifecycle, once the cause is determined"}, {"label": "B", "text": "At ticket creation, before any investigation"}, {"label": "C", "text": "Only for tickets marked as bugs"}, {"label": "D", "text": "It auto-populates from the Part field"}]'::jsonb, 'A', 'Diagnosis captures the final determination of what caused the issue, so it should be set at the end of the lifecycle or once the root cause has been established.'),
  ('Support Processes - DevRev', 5, 'A support engineer is unsure whether to select "Bug" as the Diagnosis for a ticket. What is the documented rule?', '[{"label": "A", "text": "Only select Bug if the issue is a defect in the code that requires a code change"}, {"label": "B", "text": "Select Bug whenever a customer describes unexpected behavior"}, {"label": "C", "text": "Select Bug only after Engineering has already shipped a fix"}, {"label": "D", "text": "Bug should never be used — select ''Other'' instead"}]'::jsonb, 'A', 'The taxonomy doc is explicit that Bug should only be chosen for genuine code defects requiring a code change — not for configuration, data, or usage issues.'),
  ('Support Processes - DevRev', 6, 'What does the ''OOTB or Customization'' field identify, and when is it required?', '[{"label": "A", "text": "Which part of the code the issue occurred in (standard product vs. customised code) — required for ticket closure"}, {"label": "B", "text": "Whether the customer is on a paid or free plan — required at ticket creation"}, {"label": "C", "text": "Whether the ticket was raised via chat or email — optional"}, {"label": "D", "text": "Which Slack channel owns the ticket — required for escalation"}]'::jsonb, 'A', 'Field Usages defines OOTB or Customization as identifying whether the issue sits in standard product code or customised code, used alongside Part and Diagnosis, and it is a required field before a ticket can be closed.'),
  ('Support Processes - DevRev', 7, 'A support engineer wants to raise an engineering issue quickly and considers creating the Linear issue directly in Linear instead of via DevRev. What is wrong with that approach?', '[{"label": "A", "text": "It breaks the DevRev-Linear integration, so the issue can''t be linked back to the originating DevRev ticket"}, {"label": "B", "text": "Nothing — it''s equally valid and faster"}, {"label": "C", "text": "It''s fine as long as the DevRev ticket number is put in the Linear title"}, {"label": "D", "text": "Only engineering managers are allowed to create Linear issues"}]'::jsonb, 'A', 'The guide states plainly that creating a Linear issue directly in Linear breaks the integration and prevents proper tracking — the DevRev template must always be used.'),
  ('Support Processes - DevRev', 8, 'After submitting a Linear issue via the DevRev template, roughly how long does it take for the Linear issue to appear?', '[{"label": "A", "text": "About 5 minutes"}, {"label": "B", "text": "Instantly"}, {"label": "C", "text": "Up to 24 hours"}, {"label": "D", "text": "About 1 hour"}]'::jsonb, 'A', 'The guide notes this ~5 minute delay is expected behaviour, the same as it previously was with Jira.'),
  ('Support Processes - DevRev', 9, '15 minutes after submitting a Linear issue via the DevRev template, a support engineer still doesn''t see a Linear icon on the ticket. What should they do?', '[{"label": "A", "text": "Reach out in #support-engineering-tickets or contact their team lead"}, {"label": "B", "text": "Immediately resubmit the template a second time"}, {"label": "C", "text": "Manually create the issue in Linear as a backup"}, {"label": "D", "text": "Escalate directly to the customer"}]'::jsonb, 'A', 'The guide says that if the Linear issue hasn''t appeared after 10+ minutes, the engineer should ask in #support-engineering-tickets or contact their team lead — not resubmit or work around the template.'),
  ('Support Processes - DevRev', 10, 'A ticket needs to be escalated from the initial Support Engineering (SE) team to another engineering team. How does this show up back on the original DevRev ticket?', '[{"label": "A", "text": "As a Child Issue, created when the SE team opens a Sub-Issue in Linear"}, {"label": "B", "text": "The original DevRev ticket is closed and a new one opened"}, {"label": "C", "text": "It only appears in Linear — DevRev has no visibility into escalations"}, {"label": "D", "text": "The Diagnosis field is automatically changed to \"Escalated\""}]'::jsonb, 'A', 'When an SE team member escalates an issue, they create a Sub-Issue in Linear, which surfaces as a Child Issue on the original DevRev ticket — giving full visibility of the escalation chain without leaving DevRev.')
) as v(title, position, question, options, correct_answer, rationale)
join courses c on c.title = v.title and c.track_id = (select id from tracks where name = 'Core Competency')
on conflict (course_id, position) do nothing;

-- Core Competency's own skill taxonomy (courses.skills) — same re-runnable
-- UPDATE-by-title pattern as the AI Track's own skills block
-- (ai-track-seed.sql), scoped to this track by title + track_id. Eight
-- skills for 36 courses, consolidated well past the 12 individual
-- competency tabs above (deliberately coarser, same reasoning as the AI
-- Track's own 7-for-20): the small Behavioural/Core tabs (Culture
-- Champion, Growth and Learning, Cross-Functional Collaboration,
-- Performance Excellence, Change Driver & Innovator, Customer First
-- mindset) share real thematic overlap and fold into three skills, not
-- six. "Skedulo Pulse Platform Fundamentals" pulls together every
-- Custom-vs-Core-tab course plus the one Tools-and-Systems course whose
-- own title already says "(Skedulo Pulse Platform)" — the product-specific
-- admin/configuration knowledge, as distinct from "Support Tooling &
-- Systems" (Datadog, Linear — internal SUPPORT tools, not the product
-- itself). "Internal Platform Deep Dive" carries both tags — its own
-- outcome text names both the product internals AND Datadog/Analytics/
-- Amplitude/Twilio, matching the AI Track's "a few courses carry two"
-- pattern. "The Complete Storytelling Course for Speaking & Presenting"
-- moved tabs (Cross-Functional Collaboration -> Growth and Learning) in
-- the source spreadsheet's own reorganization, reflected in its
-- focus_area above; its skill tag stays Customer-Centered Communication
-- regardless — storytelling/presenting is what it's actually about, not
-- whichever tab the source files it under.
update courses set skills = v.skills
from (values
  ('Trailhead module: Best Practices for Troubleshooting', array['Technical Troubleshooting']::text[]),
  ('Skedulo Pulse Admin Fundamentals', array['Skedulo Pulse Platform Fundamentals']::text[]),
  ('Salesforce Basics', array['Skedulo Pulse Platform Fundamentals']::text[]),
  ('Skedulo release notes — track what''s new each release', array['Skedulo Pulse Platform Fundamentals']::text[]),
  ('Skedulo Pulse Platform: Setup Resources → Complete Job as a Resource', array['Skedulo Pulse Platform Fundamentals']::text[]),
  ('Skedulo Pulse Platform: Onboarding, General Settings, Preferences, Navigations, Customize Scheduling Workflow, Create and Manage Data Object, Manage Custom Fields, Using Dynamic Messaging', array['Skedulo Pulse Platform Fundamentals']::text[]),
  ('Internal Platform Deep Dive', array['Skedulo Pulse Platform Fundamentals', 'Support Tooling & Systems']::text[]),
  ('Shared Ticketing Process – Skedulo & Lumary + Customer Admin Account Recovery procedure', array['Support Process & SLAs']::text[]),
  ('Skedulo AI Usage Policy + Information Security policies (customer data handling)', array['Support Process & SLAs']::text[]),
  ('Atlassian ITSM & incident guides', array['Support Process & SLAs']::text[]),
  ('Shared Ticketing Process – Skedulo & Lumary', array['Support Process & SLAs']::text[]),
  ('How to Create a Linear Issue via DevRev — always via DevRev, never directly in Linear', array['Support Process & SLAs']::text[]),
  ('Datadog Quick Start', array['Support Tooling & Systems']::text[]),
  ('Linear Basic Training', array['Support Tooling & Systems']::text[]),
  ('GraphQL (Skedulo Pulse Platform)', array['Skedulo Pulse Platform Fundamentals']::text[]),
  ('Technical support plans and SLAs', array['Support Process & SLAs']::text[]),
  ('Atlassian SLA & service-request management guide', array['Support Process & SLAs']::text[]),
  ('Escalation Workflow — the team''s Lucidchart escalation diagram', array['Incident Management & Escalation']::text[]),
  ('Incident Analysis Report (Aug 2025–Aug 2026) — severity mix, detection methods, trends', array['Incident Management & Escalation']::text[]),
  ('Account Map & Service Catalog', array['Incident Management & Escalation']::text[]),
  ('DevRev To Linear SUP tickets Workflow — how a customer ticket becomes an engineering issue', array['Incident Management & Escalation']::text[]),
  ('TED — Simon Sinek: Why good leaders make you feel safe', array['Growth Mindset & Feedback Culture']::text[]),
  ('Embracing a Culture of Feedback', array['Growth Mindset & Feedback Culture']::text[]),
  ('TED — Vernā Myers: How to overcome our biases? Walk boldly toward them', array['Growth Mindset & Feedback Culture']::text[]),
  ('Curiosity and Lifelong Learning', array['Growth Mindset & Feedback Culture']::text[]),
  ('TED — Carol Dweck: The power of believing that you can improve', array['Growth Mindset & Feedback Culture']::text[]),
  ('The Complete Storytelling Course for Speaking & Presenting', array['Customer-Centered Communication']::text[]),
  ('Active Listening — You Can Be a Great Listener', array['Customer-Centered Communication']::text[]),
  ('Mastering Collaboration: Work together for the best results', array['Customer-Centered Communication']::text[]),
  ('Productivity and Time Management for the Overwhelmed', array['Performance & Innovation']::text[]),
  ('TED — Dan Pink: The puzzle of motivation', array['Performance & Innovation']::text[]),
  ('TED — Yves Morieux: How too many rules at work keep you from getting things done', array['Performance & Innovation']::text[]),
  ('Creativity, problem solving and generating alternatives', array['Performance & Innovation']::text[]),
  ('TED — Adam Grant: The surprising habits of original thinkers', array['Performance & Innovation']::text[]),
  ('The Customer: How to Understand Their Needs (BITE SIZE)', array['Customer-Centered Communication']::text[]),
  ('TED — Joe Gebbia: How Airbnb designs for trust', array['Customer-Centered Communication']::text[])
) as v(title, skills)
where courses.title = v.title
  and courses.track_id = (select id from tracks where name = 'Core Competency');

-- Wrap-up quiz content — 342 questions across all 36 courses, imported
-- from two spreadsheets: "Behavioral Competency - Quizzes.xlsx" (the 6
-- Behavioural/Core competencies, one tab per course, 8-16 questions each)
-- and "Functional Competency - Quizzes.xlsx" (the 6 Technical/Functional
-- competencies, 10 questions each). Unlike the AI Track (15 of 20 courses
-- have a quiz), every current Core Competency course has one — the source
-- spreadsheets covered a 37th course too ("Skedulo Web App (Skedulo Pulse
-- Platform)"), but that course was one of the 7 dropped from this track's
-- own catalog (see the reconciliation DELETE above); its 10 questions were
-- excluded on the way in rather than imported with nothing to attach to.
-- Matched to courses by title, same as the AI Track's own quiz insert
-- (below) — cross-checked against each question sheet's own "Source: URL"
-- line against courses.link, not just sheet naming, since sheet titles
-- don't always read as exact course-title matches (e.g. this file's
-- "Skedulo Pulse Admin Fundamentals" sheet is titled "CC-01 Pulse Admin
-- Fundamentals"). Two sheets shared one course's own URL outright (the
-- Confluence "Shared Ticketing Process" page, referenced by both the plain
-- course and the "+ Customer Admin Account Recovery" one) — resolved by
-- each sheet's own title text instead, since the URL alone couldn't tell
-- them apart. `options` is a jsonb array (`[{"label":"A","text":"..."}, ...]`,
-- always 4 options, A-D), same shape course_quiz_questions already uses.
-- Scoped to this track by title AND track_id — the AI Track's own quiz
-- insert only needs a title match (titles are unique enough there), but
-- this one is explicit about it since nothing stops a future course in a
-- different track from reusing a title by coincidence.
insert into course_quiz_questions (course_id, position, question, options, correct_answer, rationale)
select c.id, v.position, v.question, v.options, v.correct_answer, v.rationale
from (values
  ('TED — Simon Sinek: Why good leaders make you feel safe', 1, 'What did Captain William Swenson do that earned him the Congressional Medal of Honor, as described in the talk?', '[{"label": "A", "text": "Was the first officer to accept a promotion after the ambush"}, {"label": "B", "text": "Led a diplomatic negotiation with village elders that ended the conflict"}, {"label": "C", "text": "Ran into live fire during an ambush to rescue wounded soldiers, then went back to rescue more"}, {"label": "D", "text": "Won the battle single-handedly against a numerically superior force"}]'::jsonb, 'C', 'The talk opens with this account, captured partly on a medic''s helmet camera, as the entry point into the talk''s theme of self-sacrifice for others.'),
  ('TED — Simon Sinek: Why good leaders make you feel safe', 2, 'According to Sinek, what is the key difference in how the military and how business typically reward people?', '[{"label": "A", "text": "Business rewards long tenure, while the military rewards only rank and seniority"}, {"label": "B", "text": "The military rewards individual heroics, while business rewards only team performance"}, {"label": "C", "text": "Both systems reward identical behavior, just using different currencies"}, {"label": "D", "text": "The military gives medals to people willing to sacrifice themselves so others may gain, while business often gives bonuses to people willing to sacrifice others so the company may gain"}]'::jsonb, 'D', 'Sinek states plainly that we "have it backwards" between these two reward systems, setting up his argument for what leadership should actually protect.'),
  ('TED — Simon Sinek: Why good leaders make you feel safe', 3, 'In Sinek''s framework, what does the "circle of safety" refer to?', '[{"label": "A", "text": "A formal HR policy that protects employees from being fired without cause"}, {"label": "B", "text": "A sense of belonging and trust within a group that lets people feel protected from external threats and naturally cooperate"}, {"label": "C", "text": "A performance-review process designed to reduce workplace conflict"}, {"label": "D", "text": "A perimeter security protocol used to protect VIPs"}]'::jsonb, 'B', 'Sinek traces this back to early human tribes: feeling safe among your own group is what produces natural trust and cooperation.'),
  ('TED — Simon Sinek: Why good leaders make you feel safe', 4, 'Why does Sinek argue that leaders cannot simply instruct people to "trust" or "cooperate"?', '[{"label": "A", "text": "Trust only develops after a fixed number of years of tenure"}, {"label": "B", "text": "Employees are inherently uncooperative unless paid more"}, {"label": "C", "text": "Trust and cooperation are feelings that emerge from the right conditions, not behaviors that can be directly commanded"}, {"label": "D", "text": "Trust and cooperation are illegal to mandate under most employment law"}]'::jsonb, 'C', 'Sinek explicitly frames trust and cooperation as feelings, not instructions — you cannot just tell two people to cooperate and expect it to happen.'),
  ('TED — Simon Sinek: Why good leaders make you feel safe', 5, 'Why does Sinek say the airline gate agent''s harsh treatment of a passenger reflects her own working conditions rather than her personal character?', '[{"label": "A", "text": "Airline customer service policies are stricter than in other industries, which fully explains it"}, {"label": "B", "text": "She said she''d get in trouble or lose her job if she didn''t strictly follow the rules, meaning she doesn''t feel safe or trusted by her own leaders"}, {"label": "C", "text": "She was simply having a bad day, unrelated to her workplace"}, {"label": "D", "text": "She lacked proper customer service training, which is a skills issue, not a leadership one"}]'::jsonb, 'B', 'Sinek uses her own explanation — fear of getting in trouble — as evidence that her behavior stems from not feeling safe within her own organization.'),
  ('TED — Simon Sinek: Why good leaders make you feel safe', 6, 'What point is Sinek making by contrasting a hypothetical large bonus for Gandhi or Mother Teresa with the anger directed at real banking-CEO bonuses?', '[{"label": "A", "text": "The public actually supports any large bonus paid to a well-known public figure"}, {"label": "B", "text": "The comparison shows all large bonuses are equally acceptable regardless of recipient"}, {"label": "C", "text": "The public outrage isn''t really about the size of the numbers — it''s that those CEOs seemed to protect their own interests at their people''s expense, violating the social contract of leadership"}, {"label": "D", "text": "People are only upset because banking CEOs did not donate their bonuses to charity"}]'::jsonb, 'C', 'Sinek uses this contrast to argue the issue is not the dollar amount but a broken expectation that leaders sacrifice for their people, not the reverse.'),
  ('TED — Simon Sinek: Why good leaders make you feel safe', 7, 'A department head is under pressure to hit quarterly numbers and is considering layoffs. Following Bob Chapman''s approach at Barry-Wehmiller described in the talk, what alternative could they explore first?', '[{"label": "A", "text": "Immediately lay off the lowest performers first, without exploring other options"}, {"label": "B", "text": "Freeze all spending and internal communication until the crisis passes"}, {"label": "C", "text": "Ask only entry-level staff to reduce their hours while leadership continues as normal"}, {"label": "D", "text": "Introduce a shared-sacrifice measure everyone participates in, such as unpaid furlough days across all levels including leadership, instead of eliminating positions"}]'::jsonb, 'D', 'This mirrors Chapman''s actual response to a 2008 revenue drop: a shared furlough program across every level rather than layoffs, framed as protecting "heart count" over head count.'),
  ('TED — Simon Sinek: Why good leaders make you feel safe', 8, 'A newly promoted manager has formal authority over a team, but people don''t really follow or respect them. Using Sinek''s distinction between authority and leadership, what''s most likely happening?', '[{"label": "A", "text": "This is normal and will resolve automatically once the manager has more tenure"}, {"label": "B", "text": "The manager has rank but hasn''t yet earned leadership, which Sinek describes as a choice demonstrated by looking after others, not something conferred by title"}, {"label": "C", "text": "The manager needs more formal authority, such as the power to fire people"}, {"label": "D", "text": "The team is simply resistant to any form of management, regardless of behavior"}]'::jsonb, 'B', 'Sinek is explicit that leadership is a choice, not a rank — people at the top can be mere authorities, while people with no rank at all can be genuine leaders.'),
  ('TED — Simon Sinek: Why good leaders make you feel safe', 9, 'A support team lead notices their reps seem guarded and reluctant to admit mistakes to each other or to leadership. Which idea from the talk most directly explains a possible root cause?', '[{"label": "A", "text": "The reps probably need more technical training to feel confident"}, {"label": "B", "text": "This is unrelated to leadership and is purely an individual personality issue"}, {"label": "C", "text": "If people don''t feel safe within the team''s \"circle,\" they''ll spend energy protecting themselves from each other instead of naturally cooperating and being open"}, {"label": "D", "text": "The team simply needs stricter deadlines to increase focus"}]'::jsonb, 'C', 'Sinek argues that when conditions inside a group are wrong, people are forced to protect themselves from one another, which weakens openness and cooperation.'),
  ('TED — Simon Sinek: Why good leaders make you feel safe', 10, 'Based on this talk, what is one concrete way a team leader could apply Sinek''s message about building a "circle of safety" day-to-day?', '[{"label": "A", "text": "Focus primarily on setting more aggressive KPIs to drive urgency"}, {"label": "B", "text": "Reward only the single top performer each month to create healthy competition"}, {"label": "C", "text": "Limit communication to formal channels only, to reduce noise"}, {"label": "D", "text": "Model vulnerability and support — such as owning their own mistakes and backing the team when things go wrong — so people feel safe enough to be honest and help each other, rather than just enforcing rules"}]'::jsonb, 'D', 'This applies the talk''s central claim directly to a workplace habit: leaders create safety through their own choices and behavior, not through more control or competition.'),
  ('Embracing a Culture of Feedback', 1, 'In the course''s DISC-based "Your Feedback Style" activity, what are the four styles used to describe how people tend to approach feedback?', '[{"label": "A", "text": "Type A, Type B, Type C, and Type D personality types"}, {"label": "B", "text": "Dominant, Influential, Steady, and Conscientious"}, {"label": "C", "text": "Assertive, Passive, Aggressive, and Passive-Aggressive"}, {"label": "D", "text": "Visual, Auditory, Reading/Writing, and Kinesthetic"}]'::jsonb, 'B', 'The course introduces the DISC framework by name in Section 1 to help participants recognize their own and others'' feedback tendencies.'),
  ('Embracing a Culture of Feedback', 2, 'What are the four steps in the course''s structured process for delivering feedback effectively?', '[{"label": "A", "text": "Observe, Judge, Warn, and Reprimand"}, {"label": "B", "text": "Introduce, Criticize, Praise, and Conclude"}, {"label": "C", "text": "Prepare, Deliver, Document, and Escalate"}, {"label": "D", "text": "Ask for Permission, State Observations, Share Impact, and Make Suggestions for Improvement"}]'::jsonb, 'D', 'This 4-step process is the core framework taught in the "How to Give Feedback Effectively" section, then practiced in its role play.'),
  ('Embracing a Culture of Feedback', 3, 'What does the "AIM" part of the course''s AIM SMART Plan for receiving feedback stand for?', '[{"label": "A", "text": "Ask, Investigate, Mediate"}, {"label": "B", "text": "Analyze, Implement, Measure"}, {"label": "C", "text": "Acknowledge, Inquire, Modify"}, {"label": "D", "text": "Accept, Ignore, Move on"}]'::jsonb, 'C', 'AIM is the three-step response sequence taught for receiving feedback: acknowledge it, inquire to understand it, then modify behavior based on it.'),
  ('Embracing a Culture of Feedback', 4, 'What does the "SMART" part of the course''s AIM SMART Plan stand for?', '[{"label": "A", "text": "Structured, Motivating, Actionable, Realistic, Transparent"}, {"label": "B", "text": "Simple, Manageable, Approved, Recorded, Timely"}, {"label": "C", "text": "Specific, Measurable, Achievable, Relevant, Time-bound"}, {"label": "D", "text": "Straightforward, Meaningful, Agile, Repeatable, Tracked"}]'::jsonb, 'C', 'SMART supplies the goal-setting criteria used to turn received feedback into a concrete, trackable action plan.'),
  ('Embracing a Culture of Feedback', 5, 'In the course''s lecture on the neuroscience of feedback, whose "growth mindset" concept is used to connect the brain science back to how people should relate to feedback?', '[{"label": "A", "text": "Maslow''s hierarchy of needs"}, {"label": "B", "text": "Daniel Goleman''s model of emotional intelligence"}, {"label": "C", "text": "The Kübler-Ross stages of grief"}, {"label": "D", "text": "Carol Dweck''s"}]'::jsonb, 'D', 'The lecture links feedback''s effect on the brain''s reward and stress pathways to Dweck''s growth mindset as the productive way to interpret that response.'),
  ('Embracing a Culture of Feedback', 6, 'Why does the course describe feedback as fundamentally different from both praise and criticism?', '[{"label": "A", "text": "Praise is one-sided and lacks detail to guide continued behavior, while criticism focuses on faults without a constructive path forward — feedback is framed as a specific, two-way, actionable dialogue"}, {"label": "B", "text": "Praise and criticism are both described as more effective than feedback in every situation"}, {"label": "C", "text": "Feedback is presented as simply a more formal, scheduled version of praise"}, {"label": "D", "text": "Criticism and feedback are described as functionally identical in the course"}]'::jsonb, 'A', 'Lecture 4, "Defining Feedback," draws this three-way distinction explicitly to establish what makes feedback uniquely useful.'),
  ('Embracing a Culture of Feedback', 7, 'What is the "paradox of feedback" described in the course?', '[{"label": "A", "text": "Feedback is meant to help people improve, yet it commonly triggers anxiety and defensiveness instead of the open engagement it''s intended to produce"}, {"label": "B", "text": "The paradox is that no two people ever interpret the same feedback identically"}, {"label": "C", "text": "Feedback works well for junior employees but never works for senior leaders"}, {"label": "D", "text": "Positive feedback is described as more stressful to receive than negative feedback"}]'::jsonb, 'A', 'This lecture names the tension between feedback''s improvement-oriented intent and the defensive reaction it often provokes in practice.'),
  ('Embracing a Culture of Feedback', 8, 'Why does the course recommend using an understanding of DISC-based feedback styles when giving feedback to a colleague?', '[{"label": "A", "text": "Because DISC style is fixed, so feedback should always be delivered identically regardless of the recipient"}, {"label": "B", "text": "Because people''s preferences for how feedback is delivered differ (for example, a direct, task-focused style versus a more people-oriented or harmony-seeking style), adapting the approach makes feedback more likely to land well"}, {"label": "C", "text": "Because DISC assessments determine who is allowed to give feedback in an organization"}, {"label": "D", "text": "Because only the \"Dominant\" style is capable of giving useful feedback"}]'::jsonb, 'B', 'Section 4''s lecture on feedback styles and adaptation ties DISC awareness directly to tailoring delivery for the recipient, not standardizing it.'),
  ('Embracing a Culture of Feedback', 9, 'In "Setting the Stage for Feedback," why does the course emphasize choosing the right time and a private, comfortable environment before delivering feedback?', '[{"label": "A", "text": "Environment is described as having no real effect on how feedback is received"}, {"label": "B", "text": "The right timing and setting help create emotional safety, making the recipient more receptive and open rather than defensive"}, {"label": "C", "text": "A private setting is only needed for negative feedback, never for positive feedback"}, {"label": "D", "text": "It is mainly a formality required for HR documentation purposes"}]'::jsonb, 'B', 'Section 3 links environment and timing directly to emotional safety, which it treats as a precondition for a constructive feedback conversation.'),
  ('Embracing a Culture of Feedback', 10, 'Why does the course pair the 4-step feedback process with a recommendation to also give specific positive feedback?', '[{"label": "A", "text": "Positive feedback is described as unnecessary once the 4-step process is mastered"}, {"label": "B", "text": "Positive feedback is presented as a replacement for the 4-step process, to be used instead of it"}, {"label": "C", "text": "The course states positive feedback should only be given once a year, separate from other feedback"}, {"label": "D", "text": "Balancing constructive feedback with specific, genuine positive reinforcement helps sustain a supportive atmosphere and motivates continued good behavior, rather than every conversation feeling purely corrective"}]'::jsonb, 'D', 'The final lecture of Section 4, "The Power of Positive Feedback," explicitly frames specific positives as a complement to the 4-step process, not a substitute.'),
  ('Embracing a Culture of Feedback', 11, 'A manager wants to give a direct report feedback about missed deadlines, but the report tends to shut down defensively. Applying the course''s 4-step process, what should the manager do first?', '[{"label": "A", "text": "Ask for permission — check whether the person is in a receptive place to hear feedback right now, before sharing observations"}, {"label": "B", "text": "Share the impact on the team first, before saying anything else"}, {"label": "C", "text": "Skip straight to suggestions for improvement to save time"}, {"label": "D", "text": "Wait for the person''s annual review to bring it up formally"}]'::jsonb, 'A', 'The 4-step process opens with asking permission specifically because it respects the recipient''s readiness and increases receptiveness, per Section 4.'),
  ('Embracing a Culture of Feedback', 12, 'An employee just received critical feedback and wants to respond constructively using the AIM SMART Plan. What should they do right after acknowledging the feedback?', '[{"label": "A", "text": "Immediately promise a specific outcome without asking any follow-up questions"}, {"label": "B", "text": "Inquire — ask clarifying questions to make sure they fully understand what''s being asked before trying to act on it"}, {"label": "C", "text": "Escalate the feedback to a more senior manager for a second opinion"}, {"label": "D", "text": "Change the subject to something unrelated to ease the tension"}]'::jsonb, 'B', 'AIM''s second step is Inquire, which the course places between acknowledging feedback and modifying behavior, specifically to build understanding first.'),
  ('Embracing a Culture of Feedback', 13, 'A team lead wants to help normalize feedback so it doesn''t feel like a rare, high-stakes event. Based on Section 6 of the course, what practice could they introduce?', '[{"label": "A", "text": "Requiring all feedback to be routed through HR before being delivered"}, {"label": "B", "text": "Restricting feedback strictly to formal annual performance reviews"}, {"label": "C", "text": "Only allowing feedback to be given anonymously through a suggestion box"}, {"label": "D", "text": "A regular routine like a recurring \"feedback day\" and/or pairing teammates as \"feedback buddies\" to build comfort with giving and receiving feedback over time"}]'::jsonb, 'D', 'Section 6 specifically recommends feedback buddies and a recurring feedback routine as ways to build an everyday culture of feedback rather than an occasional event.'),
  ('Embracing a Culture of Feedback', 14, 'An employee wants to turn a piece of harsh criticism they once received into something constructive, applying the idea behind the course''s Role Play 1. What is the core move they should practice?', '[{"label": "A", "text": "Ignore the criticism entirely, since it was not constructive to begin with"}, {"label": "B", "text": "Reframe the language of the criticism into specific, growth-oriented feedback — naming the feeling it evoked and restating it in a more constructive, forward-looking way"}, {"label": "C", "text": "Escalate the original criticism to a higher authority for review"}, {"label": "D", "text": "Repeat the original criticism back to the person who gave it, unchanged"}]'::jsonb, 'B', 'Role Play 1, "Transforming Criticism into Constructive Feedback," has participants practice exactly this reframing exercise.'),
  ('Embracing a Culture of Feedback', 15, 'A manager wants to check whether feedback they gave last month actually led to improvement, using the SMART portion of the AIM SMART framework. What should they build into their follow-up?', '[{"label": "A", "text": "A one-time verbal confirmation from the employee that \"it''s handled\""}, {"label": "B", "text": "Clear, specific, measurable criteria and a defined timeline, so progress toward the agreed change can actually be assessed rather than judged vaguely"}, {"label": "C", "text": "A general, open-ended check-in with no specific criteria or timeframe"}, {"label": "D", "text": "No follow-up at all, since SMART goals are treated as self-executing once stated"}]'::jsonb, 'B', 'SMART''s Measurable and Time-bound elements exist precisely so progress on feedback can be tracked concretely rather than assumed.'),
  ('Embracing a Culture of Feedback', 16, 'Based on the course as a whole, what is one concrete habit a support team could adopt to move from occasional, high-stakes feedback toward an everyday "culture of feedback"?', '[{"label": "A", "text": "Have only senior leadership give feedback, to maintain consistency across the team"}, {"label": "B", "text": "Centralize all feedback exclusively through annual performance reviews to keep it consistent"}, {"label": "C", "text": "Limit feedback to only positive comments to keep morale high"}, {"label": "D", "text": "Build regular, low-stakes feedback touchpoints — such as a feedback-buddy system or a recurring feedback day — using the 4-step process to give feedback and the AIM SMART plan to receive it, rather than saving feedback for formal reviews"}]'::jsonb, 'D', 'This combines the course''s giving framework (4-step process), receiving framework (AIM SMART), and Section 6''s culture-building habits into a single practical takeaway.'),
  ('TED — Vernā Myers: How to overcome our biases? Walk boldly toward them', 1, 'What tool does Myers describe that measures unconscious/automatic bias, and what has it revealed about most people''s preferences?', '[{"label": "A", "text": "The Implicit Association Test — it shows most people, across races, more easily associate positive words with white faces than with black faces"}, {"label": "B", "text": "A standardized workplace diversity survey, which shows most people report no bias at all"}, {"label": "C", "text": "A blind resume-screening test, which shows hiring bias is entirely eliminated once names are removed"}, {"label": "D", "text": "A facial recognition algorithm, which shows equal bias across all racial groups"}]'::jsonb, 'A', 'Myers cites the Implicit Association Test by name and its finding that a majority of both white and black test-takers show a preference for white.'),
  ('TED — Vernā Myers: How to overcome our biases? Walk boldly toward them', 2, 'What personal example does Myers give to illustrate that she has biases despite doing diversity work professionally?', '[{"label": "A", "text": "She felt reassured hearing a woman pilot''s voice, but grew anxious about the pilot''s competence specifically once the flight got turbulent — a doubt she says she never felt about a male pilot"}, {"label": "B", "text": "She admits she never learned to trust any pilots, male or female"}, {"label": "C", "text": "She describes refusing to fly with any pilot under a certain age"}, {"label": "D", "text": "She explains that she avoids air travel altogether due to a fear of flying"}]'::jsonb, 'A', 'Myers uses this story about her own reaction to a turbulent flight to show that even her explicitly stated views can diverge from her automatic, implicit reactions.'),
  ('TED — Vernā Myers: How to overcome our biases? Walk boldly toward them', 3, 'What three actions does Myers call on the audience to take to help stop tragedies like the Ferguson shooting from recurring?', '[{"label": "A", "text": "Avoid discussing race in mixed company, focus only on individual merit, and let institutions self-correct over time"}, {"label": "B", "text": "Support new legislation, hire more diverse police officers, and increase funding for community centers"}, {"label": "C", "text": "Take an anger-management course, apologize publicly for past bias, and donate to relevant charities"}, {"label": "D", "text": "Get out of denial about having biases, move toward (not away from) young black men, and speak up when you hear biased comments, even from people you love"}]'::jsonb, 'D', 'These are the three numbered calls to action Myers builds the talk around, each addressed in turn.'),
  ('TED — Vernā Myers: How to overcome our biases? Walk boldly toward them', 4, 'Why does Myers argue against "color blindness" (claiming not to see race) as a solution to bias?', '[{"label": "A", "text": "Because color blindness is a literal medical condition most people don''t actually have"}, {"label": "B", "text": "The problem was never noticing color — it''s what people do because of it; pretending not to see color prevents recognizing how racial difference is actually shaping others'' outcomes and opportunities"}, {"label": "C", "text": "Because it is technically impossible for the brain to avoid noticing race under any circumstances"}, {"label": "D", "text": "Because color blindness was already banned as a workplace policy"}]'::jsonb, 'B', 'Myers explicitly rejects color blindness as a "false ideal," arguing awareness of impact matters more than claiming not to notice difference.'),
  ('TED — Vernā Myers: How to overcome our biases? Walk boldly toward them', 5, 'What is the purpose of Myers''s recommendation to deliberately "stare at" and remember accomplished Black individuals?', '[{"label": "A", "text": "It works by permanently erasing the brain''s capacity to form any future associations"}, {"label": "B", "text": "It is meant purely as a form of celebration with no cognitive benefit"}, {"label": "C", "text": "It is designed to make people feel guilty about their existing biases"}, {"label": "D", "text": "Repeated exposure to counter-examples helps disrupt the brain''s automatic negative associations, since those associations form from repeated cultural patterns, not fixed truths"}]'::jsonb, 'D', 'Myers frames this as a concrete, evidence-based counter-measure to reset automatic associations, not simply a gesture of respect.'),
  ('TED — Vernā Myers: How to overcome our biases? Walk boldly toward them', 6, 'In the street anecdote with her Korean colleague, why does Myers describe their opposite reactions to the same man as meaningful?', '[{"label": "A", "text": "It shows two people with good intentions and diversity awareness can still have very different automatic, bias-driven reactions to the identical person and situation — proving implicit bias operates below conscious intention"}, {"label": "B", "text": "It shows the man they encountered was, in fact, dangerous, which validated caution"}, {"label": "C", "text": "It shows her colleague was more racially biased than she was, and should be blamed"}, {"label": "D", "text": "It demonstrates that only people of color can have subconscious racial bias"}]'::jsonb, 'A', 'Myers uses the anecdote precisely because both women considered themselves diversity-aware, yet reacted oppositely — illustrating how automatic bias can override conscious values.'),
  ('TED — Vernā Myers: How to overcome our biases? Walk boldly toward them', 7, 'A manager overhears a relative make a biased joke at a work holiday gathering, with a junior employee''s child present. Applying Myers''s third call to action, what should the manager do?', '[{"label": "A", "text": "Change the subject quickly so as not to embarrass anyone at the gathering"}, {"label": "B", "text": "Wait and address it privately with HR only if a formal complaint is filed later"}, {"label": "C", "text": "Say something in the moment, even though it''s uncomfortable and the person is someone they care about, rather than staying silent — especially because children absorb what goes unaddressed"}, {"label": "D", "text": "Say nothing, since it was intended as a joke and not meant seriously"}]'::jsonb, 'C', 'Myers specifically calls out staying silent around loved ones'' biased comments, especially in front of children, as the pattern that lets bias pass to the next generation.'),
  ('TED — Vernā Myers: How to overcome our biases? Walk boldly toward them', 8, 'A team lead realizes their default assumption is to pair "high-stakes" client accounts with a specific type of employee, without ever examining why. Which of Myers''s recommendations most directly applies?', '[{"label": "A", "text": "Immediately and publicly announce they are not biased, to reassure the team"}, {"label": "B", "text": "Ask HR to handle all account assignments instead, without addressing the underlying pattern"}, {"label": "C", "text": "Get out of denial — actively look for their own bias rather than assuming they have none, since implicit bias can operate even in people who consider themselves fair"}, {"label": "D", "text": "Assign accounts completely at random going forward with no further reflection"}]'::jsonb, 'C', 'Myers''s first call to action is explicitly to stop assuming you have "no biased bone" in your body and instead actively look for where bias shows up in your own decisions.'),
  ('TED — Vernā Myers: How to overcome our biases? Walk boldly toward them', 9, 'Someone wants to genuinely reduce their own implicit bias toward a group they rarely interact with. Based on Myers''s second call to action, what would be a productive step?', '[{"label": "A", "text": "Avoid the topic of difference altogether to prevent saying the wrong thing"}, {"label": "B", "text": "Rely only on formal diversity training modules and no direct relationships"}, {"label": "C", "text": "Deliberately build closer, authentic relationships with people from that group, rather than staying at a polite distance or avoiding the discomfort"}, {"label": "D", "text": "Wait for the discomfort to pass naturally over time without taking action"}]'::jsonb, 'C', 'Myers''s second call to action — move toward, not away — centers on forming genuine relationships across difference as the mechanism for change, not passive waiting.'),
  ('TED — Vernā Myers: How to overcome our biases? Walk boldly toward them', 10, 'Based on this talk, what is a reasonable workplace takeaway for someone who wants to help reduce bias on their own team?', '[{"label": "A", "text": "Conclude that since bias is unconscious, individuals cannot meaningfully change it and should not try"}, {"label": "B", "text": "Assume that avoiding the topic entirely is the safest and most respectful approach"}, {"label": "C", "text": "Acknowledge that everyone, including well-intentioned people, carries some implicit bias, then take active steps like building genuine relationships across difference and speaking up when bias shows up, rather than assuming good intentions alone are enough"}, {"label": "D", "text": "Focus solely on hiring metrics as the only meaningful lever for change"}]'::jsonb, 'C', 'This draws together Myers''s three calls to action — acknowledge, move toward, and speak up — into a single practical takeaway for a team setting.'),
  ('Curiosity and Lifelong Learning', 1, 'What neurochemical does the course identify as central to fueling curiosity and motivation?', '[{"label": "A", "text": "Dopamine"}, {"label": "B", "text": "Cortisol"}, {"label": "C", "text": "Serotonin"}, {"label": "D", "text": "Oxytocin"}]'::jsonb, 'A', 'The course''s "Dopamine Effect" section ties dopamine directly to the brain''s reward system and its role in driving curiosity-based motivation.'),
  ('Curiosity and Lifelong Learning', 2, 'According to the course, what are the two main categories of benefits it covers from pursuing lifelong learning?', '[{"label": "A", "text": "Benefits for public speaking and benefits for networking"}, {"label": "B", "text": "Benefits for physical health and benefits for financial literacy"}, {"label": "C", "text": "Benefits for test-taking and benefits for memorization"}, {"label": "D", "text": "Benefits for personal growth and benefits for career advancement"}]'::jsonb, 'D', 'The course''s "Lifelong Learning Benefits" section splits its coverage explicitly between personal life and professional/career impact.'),
  ('Curiosity and Lifelong Learning', 3, 'Who is the instructor of this course?', '[{"label": "A", "text": "Alex Genadinik"}, {"label": "B", "text": "Josh Paulsen"}, {"label": "C", "text": "TJ Walker"}, {"label": "D", "text": "Lauren Powers"}]'::jsonb, 'A', 'Alex Genadinik is named as the course instructor, distinguishing this course from the other Culture Champion track resources.'),
  ('Curiosity and Lifelong Learning', 4, 'Why does the instructor share his own case study of pursuing curiosities rather than money in his career?', '[{"label": "A", "text": "To illustrate that following genuine curiosity, rather than chasing income directly, can still lead to career and business success"}, {"label": "B", "text": "To recommend that students never consider income when making career choices"}, {"label": "C", "text": "To prove that only entrepreneurs can benefit from curiosity"}, {"label": "D", "text": "To argue that career success has nothing to do with financial outcomes at all"}]'::jsonb, 'A', 'The instructor frames his personal journey as evidence that curiosity-driven exploration, not a focus on money, led to his industry entries and business outcomes.'),
  ('Curiosity and Lifelong Learning', 5, 'Why might the course pair "the neuroscience of curiosity" with "the dopamine effect" as two connected sections?', '[{"label": "A", "text": "Because the course first explains why curiosity drives exploration and learning, then digs into the specific reward-system mechanism (dopamine) that makes that drive work"}, {"label": "B", "text": "Because dopamine is presented as something separate from curiosity and learning"}, {"label": "C", "text": "Because the two sections cover entirely unrelated topics with no connection"}, {"label": "D", "text": "Because the course structure has no particular reasoning behind section order"}]'::jsonb, 'A', 'The two sections build on each other — curiosity as the behavioral drive, dopamine as the underlying neurochemical mechanism.'),
  ('Curiosity and Lifelong Learning', 6, 'A support associate feels bored doing repetitive ticket work and has stopped learning new things on the job. Applying this course''s framing, what would help re-engage them?', '[{"label": "A", "text": "Focus solely on completing more tickets faster, regardless of interest"}, {"label": "B", "text": "Avoid learning anything new until they feel naturally motivated again"}, {"label": "C", "text": "Deliberately pursue small curiosities within their work, such as exploring why a fix works or an adjacent tool, to re-engage the brain''s reward-driven learning drive"}, {"label": "D", "text": "Wait passively until a manager assigns more interesting tasks"}]'::jsonb, 'C', 'The course frames curiosity as something to be actively grown and applied, not passively waited for, in order to reconnect with the reward/motivation system.'),
  ('Curiosity and Lifelong Learning', 7, 'A team lead wants to build a "culture of lifelong learning" on their team, as the course frames it. Which approach best matches this idea?', '[{"label": "A", "text": "Discourage exploring ideas outside an employee''s exact job description"}, {"label": "B", "text": "Limit learning opportunities to only the most senior team members"}, {"label": "C", "text": "Normalize ongoing curiosity and learning as an everyday habit across the team, not just a one-time training event"}, {"label": "D", "text": "Require a single mandatory training course per year and consider the goal met"}]'::jsonb, 'C', 'The course explicitly frames one of its goals as helping learners "create a culture of lifelong learning" in their organization, implying an ongoing habit, not a one-off event.'),
  ('Curiosity and Lifelong Learning', 8, 'Based on the course, what''s a reasonable habit a support intern could adopt to build their own lifelong-learning mindset day-to-day?', '[{"label": "A", "text": "Only pursue learning opportunities that are formally assigned by a manager"}, {"label": "B", "text": "Focus exclusively on speed metrics and treat learning as a distraction"}, {"label": "C", "text": "Treat unfamiliar tickets or tools as opportunities for curiosity-driven exploration rather than only obstacles to clear quickly"}, {"label": "D", "text": "Avoid any tasks outside their current skill set to minimize risk of mistakes"}]'::jsonb, 'C', 'This applies the course''s core message — that curiosity and continuous learning benefit both personal growth and career — to a concrete daily habit.'),
  ('TED — Carol Dweck: The power of believing that you can improve', 1, 'What alternative grade did the Chicago high school give instead of "Fail," and what did Dweck say it communicated?', '[{"label": "A", "text": "\"Not Yet\" — it communicated that the student is on a learning curve with a path into the future, rather than being fundamentally lacking"}, {"label": "B", "text": "\"Provisional Pass\" — it communicated that the student would automatically pass next term"}, {"label": "C", "text": "\"Needs Improvement\" — it communicated a permanent judgment on ability"}, {"label": "D", "text": "\"Incomplete\" — it communicated that the coursework was simply late"}]'::jsonb, 'A', 'Dweck opens the talk with this exact grading example to introduce the concept of "the power of yet."'),
  ('TED — Carol Dweck: The power of believing that you can improve', 2, 'What did brain-activity measurements show about growth-mindset students when they made an error, compared to fixed-mindset students?', '[{"label": "A", "text": "Growth-mindset students showed less brain activity, since they didn''t worry about mistakes"}, {"label": "B", "text": "Both groups showed identical brain activity regardless of mindset"}, {"label": "C", "text": "Fixed-mindset students engaged more deeply because they wanted to fix the mistake immediately"}, {"label": "D", "text": "Growth-mindset students showed much more brain activity, engaging deeply with the error, processing it, and correcting it"}]'::jsonb, 'D', 'Dweck describes the growth-mindset group''s brains as being "on fire" with engagement, in contrast to the fixed-mindset group''s minimal response.'),
  ('TED — Carol Dweck: The power of believing that you can improve', 3, 'What kind of praise does Dweck recommend to build resilient, hardy kids, based on her research?', '[{"label": "A", "text": "Praising the process — effort, strategy, focus, perseverance, and improvement"}, {"label": "B", "text": "Praising innate intelligence and natural talent"}, {"label": "C", "text": "Praising students equally regardless of what they did"}, {"label": "D", "text": "Praising only the final grade or score achieved"}]'::jsonb, 'A', 'Dweck explicitly says praising intelligence or talent "has failed," and recommends praising the process instead.'),
  ('TED — Carol Dweck: The power of believing that you can improve', 4, 'Why did the fixed-mindset students in Dweck''s studies tend to cheat or seek out worse performers after a failure?', '[{"label": "A", "text": "Because cheating was a random behavior unrelated to mindset"}, {"label": "B", "text": "Because their fixed mindset framed failure as a permanent judgment on their intelligence, so they sought ways to protect their sense of self-worth rather than actually improve"}, {"label": "C", "text": "Because they had less access to educational resources"}, {"label": "D", "text": "Because they were simply less intelligent than the growth-mindset students"}]'::jsonb, 'B', 'Dweck ties these behaviors directly to the fixed mindset''s interpretation of failure as catastrophic judgment, prompting self-protective rather than improvement-oriented responses.'),
  ('TED — Carol Dweck: The power of believing that you can improve', 5, 'Why does Dweck highlight examples like the Harlem kindergarten class and the South Bronx fourth-graders achieving top scores?', '[{"label": "A", "text": "To show that creating growth-mindset classrooms can produce dramatic equality in outcomes, even for groups that chronically underperform under traditional assumptions"}, {"label": "B", "text": "To prove that only exceptionally gifted students can succeed regardless of mindset"}, {"label": "C", "text": "To argue that standardized testing itself is fundamentally flawed"}, {"label": "D", "text": "To suggest that geographic location determines a student''s ceiling regardless of teaching approach"}]'::jsonb, 'A', 'Dweck presents these as concrete proof that growth-mindset teaching can close achievement gaps previously assumed to be inevitable.'),
  ('TED — Carol Dweck: The power of believing that you can improve', 6, 'A support team lead notices new hires shut down and avoid tricky tickets after getting something wrong once. Applying Dweck''s framework, what would help build their resilience?', '[{"label": "A", "text": "Praise their effort, troubleshooting strategy, and improvement on tough tickets, rather than praising only whether they got it right immediately"}, {"label": "B", "text": "Tell them they''re naturally talented at troubleshooting to boost confidence"}, {"label": "C", "text": "Avoid giving them any difficult tickets until they gain more experience"}, {"label": "D", "text": "Focus feedback only on the final resolution time, not on their approach"}]'::jsonb, 'A', 'This applies Dweck''s process-praise recommendation directly to a workplace coaching scenario, in place of praising fixed ability.'),
  ('TED — Carol Dweck: The power of believing that you can improve', 7, 'An employee says, "I''m just not a technical person," after struggling with a new tool. Using Dweck''s "Not Yet" framing, how might a manager reframe this?', '[{"label": "A", "text": "Suggest they compare themselves to a coworker who struggles even more"}, {"label": "B", "text": "Tell them not to worry about the tool since it''s not important"}, {"label": "C", "text": "Agree that some people are simply not technical and reassign their work"}, {"label": "D", "text": "\"You haven''t mastered this tool yet\" — treating the current gap as a stage in a learning curve rather than a fixed trait"}]'::jsonb, 'D', 'This directly mirrors Dweck''s "Not Yet" reframe, which treats current struggle as part of an ongoing growth curve, not a permanent identity label.'),
  ('TED — Carol Dweck: The power of believing that you can improve', 8, 'Based on this talk, what''s one concrete habit a support team could adopt to build a growth-mindset culture around difficult tickets?', '[{"label": "A", "text": "Only recognize the fastest resolutions on a leaderboard, regardless of ticket difficulty"}, {"label": "B", "text": "Avoid discussing tickets that weren''t solved successfully"}, {"label": "C", "text": "Treat repeated attempts at a hard ticket as a sign the person isn''t suited for the role"}, {"label": "D", "text": "Recognize and praise the troubleshooting effort, strategies tried, and progress made on hard tickets, not just whether the ticket was solved quickly or on the first attempt"}]'::jsonb, 'D', 'This translates Dweck''s process-praise and "power of yet" principles into a concrete team habit for handling difficult, effortful work.'),
  ('The Complete Storytelling Course for Speaking & Presenting', 1, 'Who is the instructor of "The Complete Storytelling Course for Speaking & Presenting"?', '[{"label": "A", "text": "Lauren Powers"}, {"label": "B", "text": "TJ Walker"}, {"label": "C", "text": "Alex Genadinik"}, {"label": "D", "text": "Josh Paulsen"}]'::jsonb, 'B', 'TJ Walker, a media and presentation training veteran, is named as the course''s instructor.'),
  ('The Complete Storytelling Course for Speaking & Presenting', 2, 'What distinctive way does the course have students practice and get feedback on their storytelling?', '[{"label": "A", "text": "Students submit essays analyzing famous speeches"}, {"label": "B", "text": "Students are graded solely by an anonymous peer-review pool"}, {"label": "C", "text": "Students only complete written multiple-choice quizzes"}, {"label": "D", "text": "Students post videos of themselves telling stories for the instructor''s personal critique"}]'::jsonb, 'D', 'The course description highlights that students post videos for TJ Walker''s personal critique as "the most meaningful and helpful part" of the course.'),
  ('The Complete Storytelling Course for Speaking & Presenting', 3, 'What does an early lecture in the course promise to teach about opening a presentation?', '[{"label": "A", "text": "\"Why You Should Never Start With a Story\""}, {"label": "B", "text": "\"The Only Acceptable Way to Use Slides\""}, {"label": "C", "text": "\"How to Skip Introductions Entirely\""}, {"label": "D", "text": "\"The Perfect Way to Start Every Presentation\""}]'::jsonb, 'D', 'This is one of the course''s early lecture titles, focused specifically on how to open a presentation.'),
  ('The Complete Storytelling Course for Speaking & Presenting', 4, 'Why does the course include a lecture titled "Trick for Getting Your Audience to Ignore All Your Mistakes and Flaws"?', '[{"label": "A", "text": "Because it recommends editing out all mistakes using video software"}, {"label": "B", "text": "Because it''s unrelated to the course''s storytelling focus"}, {"label": "C", "text": "Because the course argues mistakes should never happen if properly rehearsed"}, {"label": "D", "text": "Because it teaches a delivery technique to keep an audience engaged and forgiving of small errors, rather than promising flawless delivery is required"}]'::jsonb, 'D', 'The lecture title itself frames this as a technique for managing audience attention around imperfect delivery, consistent with the course''s practical, confidence-building approach.'),
  ('The Complete Storytelling Course for Speaking & Presenting', 5, 'Based on the "What you''ll learn" list, why does this storytelling course also cover topics like "Selling with Stories" and "Communicating to Drive Change"?', '[{"label": "A", "text": "Because these topics are unrelated bonus content with no connection to storytelling"}, {"label": "B", "text": "Because the course is actually a sales training course mislabeled as storytelling"}, {"label": "C", "text": "Because only executives are expected to use these particular skills"}, {"label": "D", "text": "Because the course treats storytelling as a broadly applicable communication skill, useful beyond formal presentations — including sales, leadership, and organizational change conversations"}]'::jsonb, 'D', 'The course explicitly lists these as applications of the same core storytelling skill set, showing its intended breadth.'),
  ('The Complete Storytelling Course for Speaking & Presenting', 6, 'A support associate needs to explain a complex technical fix to a non-technical customer in a way that''s memorable and easy to follow. Which course technique is most directly relevant?', '[{"label": "A", "text": "Structuring the explanation as a story with a clear beginning, using the course''s guidance on capturing attention from the very start"}, {"label": "B", "text": "Using as much technical jargon as possible to demonstrate expertise"}, {"label": "C", "text": "Avoiding any structure and answering only if directly asked"}, {"label": "D", "text": "Reciting the exact technical steps in the order the system logs them"}]'::jsonb, 'A', 'This applies the course''s storytelling-for-clarity approach to a customer-facing support scenario, rather than a purely technical explanation.'),
  ('The Complete Storytelling Course for Speaking & Presenting', 7, 'A team member is nervous about presenting a project update because they''re worried about stumbling over their words. Which piece of course guidance applies most directly?', '[{"label": "A", "text": "Use techniques for keeping the audience engaged and forgiving of small mistakes, rather than aiming for flawless, error-free delivery"}, {"label": "B", "text": "Cancel the presentation until they can guarantee no mistakes"}, {"label": "C", "text": "Apologize repeatedly throughout the presentation for any stumble"}, {"label": "D", "text": "Read the entire update word-for-word from a script without pausing"}]'::jsonb, 'A', 'This reflects the course''s specific lecture on managing audience perception around mistakes and flaws during a presentation.'),
  ('The Complete Storytelling Course for Speaking & Presenting', 8, 'Based on the course as a whole, what''s a reasonable takeaway for someone giving regular status updates or handovers at work?', '[{"label": "A", "text": "Avoid any structure or narrative, since only facts matter in a professional setting"}, {"label": "B", "text": "Make updates as long and detailed as possible to appear thorough"}, {"label": "C", "text": "Frame updates as a brief, structured story with a clear opening and takeaway, rather than a flat list of facts, to make them more memorable and engaging"}, {"label": "D", "text": "Skip any planning and speak entirely off the cuff every time"}]'::jsonb, 'C', 'This connects the course''s storytelling-for-presentations focus to a common workplace communication task.'),
  ('Active Listening — You Can Be a Great Listener', 1, 'Who is the instructor of "Active Listening: You Can Be a Great Listener," and what is her professional background?', '[{"label": "A", "text": "Lauren Powers, a Master Certified Coach"}, {"label": "B", "text": "TJ Walker, a media trainer"}, {"label": "C", "text": "Lauren Powers, a licensed therapist"}, {"label": "D", "text": "Josh Paulsen, a productivity coach"}]'::jsonb, 'A', 'Lauren Powers is named as the instructor and described as a Master Certified Coach, a credential held by only 4% of accredited coaches.'),
  ('Active Listening — You Can Be a Great Listener', 2, 'What key distinction does the course draw between "Level One" and "Level Two" listening?', '[{"label": "A", "text": "Level One is used with strangers and Level Two only with close friends"}, {"label": "B", "text": "The course distinguishes between a more surface-level, self-focused way of listening and a deeper, more attentive level of listening"}, {"label": "C", "text": "Level One is for phone conversations and Level Two is only for video calls"}, {"label": "D", "text": "There is no meaningful distinction — the terms are used interchangeably"}]'::jsonb, 'B', '"Level Two Listening" is one of the course''s named sections, explicitly building on and going beyond a more basic first level of listening.'),
  ('Active Listening — You Can Be a Great Listener', 3, 'According to the course''s learning objectives, how many "Powerful Questions" does it teach for deeper listening?', '[{"label": "A", "text": "7"}, {"label": "B", "text": "10"}, {"label": "C", "text": "5"}, {"label": "D", "text": "3"}]'::jsonb, 'C', 'The course''s stated learning objectives explicitly list identifying "5 Powerful Questions for deeper listening" as a goal.'),
  ('Active Listening — You Can Be a Great Listener', 4, 'Why does the course emphasize using simple "starter phrases" to reflect back what a speaker said?', '[{"label": "A", "text": "Because it''s a way to politely disagree with the speaker without confrontation"}, {"label": "B", "text": "Because reflecting back what was heard helps the speaker trust that they are actually being listened to, not just heard passively"}, {"label": "C", "text": "Because starter phrases are required to legally document a conversation"}, {"label": "D", "text": "Because reflecting back is mainly used to fill silence during a call"}]'::jsonb, 'B', 'The course''s "What you''ll learn" section ties reflecting back directly to building the speaker''s trust that they''re truly being listened to.'),
  ('Active Listening — You Can Be a Great Listener', 5, 'Why does the course treat "Automatic Listening Habits" as its own section, separate from teaching active listening skills directly?', '[{"label": "A", "text": "Because this section is unrelated filler content with no connection to the main topic"}, {"label": "B", "text": "Because automatic habits are presented as more effective than active listening"}, {"label": "C", "text": "Because the course argues habits cannot be changed, only worked around"}, {"label": "D", "text": "Because the course first helps learners recognize existing reactive habits that get in the way of listening, before replacing them with active listening skills"}]'::jsonb, 'D', 'The course''s own learning objectives open with identifying and overcoming "common habits of reacting (that are not really listening!)" before building active listening skills.'),
  ('Active Listening — You Can Be a Great Listener', 6, 'A support agent tends to start formulating their response while the customer is still explaining the issue. Which course concept most directly addresses this habit?', '[{"label": "A", "text": "Asking the customer to submit their issue in writing instead"}, {"label": "B", "text": "Shifting attention fully away from one''s own thoughts and onto the speaker — one of the course''s core \"what you''ll learn\" goals"}, {"label": "C", "text": "Interrupting immediately once a possible solution comes to mind"}, {"label": "D", "text": "Speaking faster so the customer finishes explaining sooner"}]'::jsonb, 'B', 'The course explicitly targets this exact reactive pattern — attention drifting to one''s own thoughts instead of the speaker — as a habit to overcome.'),
  ('Active Listening — You Can Be a Great Listener', 7, 'A customer describes their issue in a flat, controlled tone, but the agent senses underlying frustration. Which course skill applies here?', '[{"label": "A", "text": "Ignoring tone entirely and responding only to the literal words used"}, {"label": "B", "text": "Improving the ability to notice a speaker''s emotions, even when not explicitly stated, so the customer feels understood"}, {"label": "C", "text": "Ending the call quickly to avoid an emotional conversation"}, {"label": "D", "text": "Assuming the customer is not actually frustrated since their tone is flat"}]'::jsonb, 'B', 'The course''s learning objectives specifically include noticing a speaker''s emotions so they feel understood, which applies directly to this scenario.'),
  ('Active Listening — You Can Be a Great Listener', 8, 'Based on the course, what''s one concrete habit a support team could build to practice active listening on customer calls?', '[{"label": "A", "text": "Practice reflecting back a summary of what the customer said, using simple starter phrases, before jumping to a proposed solution"}, {"label": "B", "text": "Skip any summarizing and move straight to troubleshooting steps to save time"}, {"label": "C", "text": "Ask the customer to repeat their issue exactly as stated, word for word"}, {"label": "D", "text": "Only take notes silently without responding until the customer finishes entirely"}]'::jsonb, 'A', 'This applies the course''s "reflecting back" technique — one of its core taught skills — to a concrete customer support habit.'),
  ('Mastering Collaboration: Work together for the best results', 1, 'According to statistics cited in the course, what percentage of employers rate teamwork and collaboration as one of their most important activities?', '[{"label": "A", "text": "Nearly 50%"}, {"label": "B", "text": "Nearly 75%"}, {"label": "C", "text": "Nearly 100%"}, {"label": "D", "text": "Nearly 25%"}]'::jsonb, 'B', 'The course opens with this statistic to establish the importance employers place on collaboration.'),
  ('Mastering Collaboration: Work together for the best results', 2, 'What percentage of employees, per the course''s cited statistics, cite lack of collaboration and ineffective communication as a cause of most workplace failures?', '[{"label": "A", "text": "39%"}, {"label": "B", "text": "86%"}, {"label": "C", "text": "73%"}, {"label": "D", "text": "18%"}]'::jsonb, 'B', 'The course cites this figure specifically for employees and executives attributing workplace failures to poor collaboration and communication.'),
  ('Mastering Collaboration: Work together for the best results', 3, 'Which of the following is listed among the course''s stated topics for creating effective collaboration?', '[{"label": "A", "text": "How to negotiate vendor contracts"}, {"label": "B", "text": "How to design a company''s org chart"}, {"label": "C", "text": "How to organize and get the most out of collaborative meetings"}, {"label": "D", "text": "How to conduct formal performance reviews"}]'::jsonb, 'C', 'Organizing effective collaborative meetings is one of the specific topics the course states it will cover.'),
  ('Mastering Collaboration: Work together for the best results', 4, 'Why does the course pair individual-level benefits of collaboration (like developing interpersonal skills) with organizational-level benefits (like lowering costs)?', '[{"label": "A", "text": "To suggest individual and organizational benefits always conflict with each other"}, {"label": "B", "text": "Because the course only covers organizational benefits, not individual ones"}, {"label": "C", "text": "To show that effective collaboration creates value at both the personal skill-building level and the broader business-outcomes level, not just one or the other"}, {"label": "D", "text": "To argue that only organizational benefits actually matter, and individual benefits are incidental"}]'::jsonb, 'C', 'The course explicitly lists benefits at both levels, showing collaboration''s value operates on two connected levels.'),
  ('Mastering Collaboration: Work together for the best results', 5, 'Why does the course highlight that only 18% of employees get communication evaluations during performance reviews, right after noting 75% of employers value teamwork highly?', '[{"label": "A", "text": "To argue that performance reviews should be eliminated entirely"}, {"label": "B", "text": "To highlight a gap between how much employers claim to value collaboration and how little they actually measure or reinforce it in practice"}, {"label": "C", "text": "To prove that 18% of employees are bad at communication"}, {"label": "D", "text": "To show that communication skills are not actually important to employers"}]'::jsonb, 'B', 'The course juxtaposes these two statistics specifically to expose a mismatch between stated values and actual practice around collaboration.'),
  ('Mastering Collaboration: Work together for the best results', 6, 'A manager wants to help their team collaborate better across different functions (e.g., support and engineering). Based on the course''s topic list, which area should they specifically look into?', '[{"label": "A", "text": "How to negotiate a personal salary increase"}, {"label": "B", "text": "How to design a personal daily to-do list"}, {"label": "C", "text": "How to write individual performance reviews"}, {"label": "D", "text": "Online collaboration and how to effectively collaborate across different teams"}]'::jsonb, 'D', 'This is one of the course''s explicitly stated topics, directly relevant to cross-functional collaboration challenges.'),
  ('Mastering Collaboration: Work together for the best results', 7, 'A team frequently holds meetings that run long without clear outcomes. Which of the course''s stated topics directly addresses this?', '[{"label": "A", "text": "What you need to create a thriving culture of collaboration"}, {"label": "B", "text": "The fundamentals of forming and leading a collaborative team"}, {"label": "C", "text": "How to organize and get the most out of collaborative meetings"}, {"label": "D", "text": "Collaboration lessons from different industries"}]'::jsonb, 'C', 'This is the specific topic the course lists for improving meeting effectiveness, as opposed to the more general team-formation or culture-building topics.'),
  ('Mastering Collaboration: Work together for the best results', 8, 'Based on the course''s framing, what''s a reasonable first step for a support team wanting to build a stronger collaboration culture with other departments?', '[{"label": "A", "text": "Identify specific, practical changes to how meetings and cross-team touchpoints are run, since the course frames concrete practices as what closes the collaboration gap"}, {"label": "B", "text": "Assume collaboration will improve naturally over time without specific changes"}, {"label": "C", "text": "Limit cross-team contact to reduce the chance of miscommunication"}, {"label": "D", "text": "Address collaboration only during annual performance reviews"}]'::jsonb, 'A', 'This reflects the course''s core argument that organizations must actively build practical collaboration structures, not just value collaboration in the abstract.'),
  ('Productivity and Time Management for the Overwhelmed', 1, 'Who is the instructor of "Productivity and Time Management for the Overwhelmed"?', '[{"label": "A", "text": "TJ Walker"}, {"label": "B", "text": "Lauren Powers"}, {"label": "C", "text": "Josh Paulsen"}, {"label": "D", "text": "Alex Genadinik"}]'::jsonb, 'C', 'Josh Paulsen, described as a productivity and goals coach, is named as the course''s instructor.'),
  ('Productivity and Time Management for the Overwhelmed', 2, 'What are the three sections the course builds its structure around?', '[{"label": "A", "text": "Time zones, calendar tools, and email management"}, {"label": "B", "text": "Goal-setting, delegation, and financial planning"}, {"label": "C", "text": "Team building, hiring, and onboarding"}, {"label": "D", "text": "What causes overwhelm and procrastination; foundational productivity concepts; and proven productivity/time-management tactics and strategies"}]'::jsonb, 'D', 'The course description explicitly lays out these three sections, each building on the one before it.'),
  ('Productivity and Time Management for the Overwhelmed', 3, 'What core belief does the instructor state about talent versus habits?', '[{"label": "A", "text": "Only naturally organized people can become highly productive"}, {"label": "B", "text": "\"Talent is overrated\" — results come from habits, thought patterns, and daily behaviors, which can be changed"}, {"label": "C", "text": "Productivity is mostly determined by having the right tools and apps"}, {"label": "D", "text": "Talent is the primary factor in productivity, and habits matter far less"}]'::jsonb, 'B', 'The instructor states this directly, framing productivity as a product of changeable habits rather than fixed talent.'),
  ('Productivity and Time Management for the Overwhelmed', 4, 'Why does the course address "what causes overwhelm and procrastination" before teaching productivity tactics?', '[{"label": "A", "text": "Because the course considers tactics more important and only briefly mentions causes as an afterthought"}, {"label": "B", "text": "Because understanding the underlying causes of overwhelm is presented as the necessary foundation before tactics can be applied effectively"}, {"label": "C", "text": "Because overwhelm and procrastination are treated as unrelated to productivity"}, {"label": "D", "text": "Because the sections have no particular intended order"}]'::jsonb, 'B', 'The course explicitly describes each section as building on the previous one, starting with causes before moving to fundamentals and then tactics.'),
  ('Productivity and Time Management for the Overwhelmed', 5, 'Why might the course caution that tactics and tricks won''t be "fully utilized" without the right fundamentals in place first?', '[{"label": "A", "text": "Because without foundational mindset and conceptual understanding, specific productivity tactics lack the underlying structure needed to be effective long-term"}, {"label": "B", "text": "Because tactics are described as more important than any fundamentals"}, {"label": "C", "text": "Because fundamentals and tactics are presented as unrelated topics"}, {"label": "D", "text": "Because the course argues tactics should be learned before fundamentals"}]'::jsonb, 'A', 'The course explicitly states that without the right fundamentals, "even the best tricks and hacks won''t be fully utilized," justifying its section order.'),
  ('Productivity and Time Management for the Overwhelmed', 6, 'A support intern feels overwhelmed by a growing ticket backlog and has started procrastinating on the hardest tickets. Per the course''s structure, what should they address first?', '[{"label": "A", "text": "Immediately adopt as many productivity apps and tools as possible"}, {"label": "B", "text": "Ask to have their ticket load reduced permanently"}, {"label": "C", "text": "Ignore the backlog until it becomes urgent enough to force action"}, {"label": "D", "text": "Understand what''s actually causing their overwhelm and procrastination, before jumping straight to new productivity tactics"}]'::jsonb, 'D', 'This mirrors the course''s own sequencing — diagnosing the cause of overwhelm before applying tactics — applied to a support work scenario.'),
  ('Productivity and Time Management for the Overwhelmed', 7, 'Someone wants to build a sustainable, personalized productivity system rather than copying someone else''s routine exactly. Which course goal supports this?', '[{"label": "A", "text": "Following one universal productivity method regardless of personal working style"}, {"label": "B", "text": "Creating a personal plan that fits their own personality and style, one of the course''s explicit learning outcomes"}, {"label": "C", "text": "Adopting the instructor''s exact daily schedule without modification"}, {"label": "D", "text": "Avoiding any planning and working reactively as tasks arrive"}]'::jsonb, 'B', 'The course''s stated learning outcomes explicitly include creating a plan that "fits your personality and style," rather than a one-size-fits-all method.'),
  ('Productivity and Time Management for the Overwhelmed', 8, 'Based on the course''s overall framing, what''s a reasonable takeaway for a support team member wanting to improve their productivity sustainably?', '[{"label": "A", "text": "Assume that productivity issues are fixed traits that can''t be changed"}, {"label": "B", "text": "Adopt as many productivity hacks as possible immediately, regardless of underlying habits"}, {"label": "C", "text": "Start by identifying their own specific sources of overwhelm and procrastination, then build foundational habits before layering on specific tactics, rather than jumping straight to tricks"}, {"label": "D", "text": "Focus only on working longer hours to compensate for inefficiency"}]'::jsonb, 'C', 'This reflects the course''s core sequencing philosophy — causes and mindset first, then fundamentals, then tactics — applied to a concrete workplace takeaway.'),
  ('TED — Dan Pink: The puzzle of motivation', 1, 'What is the "candle problem," and what mental barrier does it illustrate?', '[{"label": "A", "text": "A negotiation exercise about splitting a scarce resource, illustrating conflict resolution"}, {"label": "B", "text": "A puzzle about lighting a candle in windy conditions, illustrating problem-solving under pressure"}, {"label": "C", "text": "A puzzle where participants must attach a candle to a wall using only a box of tacks; it illustrates \"functional fixedness,\" seeing the box only as a tack container rather than also as a platform"}, {"label": "D", "text": "A memory test involving candles, illustrating short-term memory limits"}]'::jsonb, 'C', 'Pink introduces the candle problem specifically to demonstrate functional fixedness — failing to see an object''s alternative use.'),
  ('TED — Dan Pink: The puzzle of motivation', 2, 'In Glucksberg''s original candle-problem experiment, what happened to the group offered cash rewards for speed, compared to the unincentivized group?', '[{"label": "A", "text": "Both groups performed identically regardless of incentive"}, {"label": "B", "text": "The incentivized group took, on average, 3.5 minutes longer to solve the problem"}, {"label": "C", "text": "The incentivized group solved it 3.5 minutes faster"}, {"label": "D", "text": "The incentivized group refused to attempt the problem at all"}]'::jsonb, 'B', 'This counterintuitive result — rewards slowing performance on a creative task — is the central piece of evidence Pink opens his argument with.'),
  ('TED — Dan Pink: The puzzle of motivation', 3, 'What three elements does Pink propose as the building blocks of a new, intrinsic-motivation-based approach to work?', '[{"label": "A", "text": "Competition, ranking, and recognition"}, {"label": "B", "text": "Rules, metrics, and accountability"}, {"label": "C", "text": "Autonomy, mastery, and purpose"}, {"label": "D", "text": "Salary, bonus, and promotion"}]'::jsonb, 'C', 'Pink names autonomy, mastery, and purpose explicitly as the three elements of his proposed "new operating system" for businesses.'),
  ('TED — Dan Pink: The puzzle of motivation', 4, 'Why did the incentivized group perform better in Glucksberg''s second version of the candle problem (with tacks outside the box)?', '[{"label": "A", "text": "Because participants in the second version were more experienced"}, {"label": "B", "text": "Because the reward amount was larger in the second version"}, {"label": "C", "text": "Because creativity was still required, and rewards always improve creative performance"}, {"label": "D", "text": "Because that version removed the need for creative insight — it became a simple, mechanical task with a clear path to the goal, and rewards work well for that kind of task"}]'::jsonb, 'D', 'Pink explains that if-then rewards work well for tasks with a clear, narrow path, which is exactly what removing the tacks-in-the-box twist created.'),
  ('TED — Dan Pink: The puzzle of motivation', 5, 'Why does Pink argue that traditional "carrot and stick" rewards are increasingly mismatched with 21st-century work?', '[{"label": "A", "text": "Because routine, rule-based tasks are increasingly automated or outsourced, while remaining work is more creative and conceptual — a type of task where narrow, reward-driven focus actually hurts performance"}, {"label": "B", "text": "Because carrot-and-stick approaches were never effective for any type of task, even in the past"}, {"label": "C", "text": "Because employees today are fundamentally less motivated by money than in the past"}, {"label": "D", "text": "Because rewards have become too expensive for most companies to offer"}]'::jsonb, 'A', 'Pink explicitly connects the shift toward creative, non-routine work to the growing mismatch with reward-driven management approaches.'),
  ('TED — Dan Pink: The puzzle of motivation', 6, 'A manager wants to boost a support team''s performance on complex, judgment-heavy troubleshooting. Based on Pink''s talk, what approach is more likely to help than a bigger bonus?', '[{"label": "A", "text": "Offer a larger cash bonus tied strictly to ticket-closure speed"}, {"label": "B", "text": "Increase supervision and check-ins to ensure compliance with procedure"}, {"label": "C", "text": "Increase the team''s autonomy over how they approach problems, and connect the work to a sense of mastery and purpose"}, {"label": "D", "text": "Add stricter, more detailed step-by-step scripts to follow exactly"}]'::jsonb, 'C', 'Pink''s argument is that reward-driven, narrow-focus approaches hurt performance specifically on complex, creative tasks — autonomy, mastery, and purpose are what he proposes instead.'),
  ('TED — Dan Pink: The puzzle of motivation', 7, 'A company wants to encourage innovative problem-solving among engineers. Which idea from the talk most directly supports this goal?', '[{"label": "A", "text": "Introducing a strict ranked leaderboard tied to weekly bonuses"}, {"label": "B", "text": "Requiring detailed daily time-tracking reports for every task"}, {"label": "C", "text": "Reducing the number of self-directed project options to increase focus"}, {"label": "D", "text": "Something like Atlassian''s \"FedEx Days\" or Google''s \"20% time,\" giving engineers autonomy to work on self-directed projects"}]'::jsonb, 'D', 'Pink cites these two real examples specifically as ways companies used autonomy to boost innovation and engagement.'),
  ('TED — Dan Pink: The puzzle of motivation', 8, 'Based on this talk, what''s a reasonable takeaway for a team lead managing knowledge work rather than routine, mechanical tasks?', '[{"label": "A", "text": "Add more rigid rules and metrics to increase predictability"}, {"label": "B", "text": "Rely less on narrow, reward-driven incentives and more on giving people autonomy, opportunities to build mastery, and a clear sense of purpose in their work"}, {"label": "C", "text": "Assume motivation is fixed and cannot be influenced by management approach"}, {"label": "D", "text": "Increase the size of performance bonuses to further sharpen focus on speed"}]'::jsonb, 'B', 'This reflects Pink''s central thesis — that autonomy, mastery, and purpose outperform carrot-and-stick incentives for complex, non-routine work.'),
  ('TED — Yves Morieux: How too many rules at work keep you from getting things done', 1, 'What real-world example does Morieux use to illustrate how individual talent alone doesn''t guarantee team success?', '[{"label": "A", "text": "A sales contest where the top individual performer had the lowest team ranking"}, {"label": "B", "text": "A cooking competition judged only on individual dish scores"}, {"label": "C", "text": "A women''s relay race, where the US team (with the individually fastest runners) lost to a team with slower individual runners but better baton-passing"}, {"label": "D", "text": "A chess tournament where the highest-rated player lost to a lower-rated opponent"}]'::jsonb, 'C', 'Morieux uses this specific relay race example as his central illustration of how cooperation, not just individual speed, determines outcomes.'),
  ('TED — Yves Morieux: How too many rules at work keep you from getting things done', 2, 'What does Morieux call the "holy trinity" of traditional efficiency thinking that he argues has become counterproductive?', '[{"label": "A", "text": "Leadership, structure, and process"}, {"label": "B", "text": "Clarity, measurement, and accountability"}, {"label": "C", "text": "Innovation, agility, and scale"}, {"label": "D", "text": "Speed, cost, and quality"}]'::jsonb, 'B', 'Morieux names these three specifically as the traditional efficiency principles that, in his argument, actively undermine cooperation.'),
  ('TED — Yves Morieux: How too many rules at work keep you from getting things done', 3, 'According to Morieux, what has happened to productivity growth rates in major economies since the mid-20th century?', '[{"label": "A", "text": "Productivity growth has steadily declined — from around 5% per year in the 1950s-60s to less than 1% per year since 1995"}, {"label": "B", "text": "Productivity growth spiked sharply upward after 1995 due to the internet"}, {"label": "C", "text": "Productivity growth has steadily increased every decade since the 1950s"}, {"label": "D", "text": "Productivity growth has remained essentially flat and unchanged since the 1950s"}]'::jsonb, 'A', 'Morieux opens his talk with this specific declining trend to establish the scale of the "productivity crisis" he''s addressing.'),
  ('TED — Yves Morieux: How too many rules at work keep you from getting things done', 4, 'Why does Morieux argue that adding a dedicated "accountability" role, like a baton hand-off coordinator, wouldn''t actually help the relay team win?', '[{"label": "A", "text": "Because accountability structures are illegal in professional sports"}, {"label": "B", "text": "Because the coordinator role would replace a runner, reducing team size"}, {"label": "C", "text": "Because it addresses who to blame if something goes wrong, not the actual cooperative behavior — how well the baton is passed — that determines whether the team wins"}, {"label": "D", "text": "Because adding more roles always slows down any process, regardless of purpose"}]'::jsonb, 'C', 'Morieux''s point is that accountability structures optimize for assigning blame after failure, not for creating the conditions that produce success.'),
  ('TED — Yves Morieux: How too many rules at work keep you from getting things done', 5, 'Why does Morieux say that measuring individual performance, like a runner''s leg speed, can actually work against cooperation?', '[{"label": "A", "text": "Because when people are rewarded for what''s individually measurable, they focus their effort there rather than on cooperative behaviors that don''t show up in that individual metric"}, {"label": "B", "text": "Because measurement is inherently inaccurate and unreliable in any team setting"}, {"label": "C", "text": "Because individual performance and team performance are always perfectly aligned"}, {"label": "D", "text": "Because Morieux argues no aspect of performance should ever be measured"}]'::jsonb, 'A', 'Morieux explicitly ties over-reliance on individually measurable metrics to reduced investment in the harder-to-measure work of cooperating.'),
  ('TED — Yves Morieux: How too many rules at work keep you from getting things done', 6, 'A support team''s individual ticket-closure-speed metric is being emphasized heavily, and cross-team handoffs to engineering have started to suffer. Applying Morieux''s argument, what''s likely happening?', '[{"label": "A", "text": "Measuring individual speed always improves both individual and team outcomes together"}, {"label": "B", "text": "People are focusing effort on what''s individually measured, their own speed, at the expense of the harder-to-measure cooperative work of handing off issues well"}, {"label": "C", "text": "The handoff problem is unrelated to how performance is measured"}, {"label": "D", "text": "The team simply needs faster individual ticket-closure training"}]'::jsonb, 'B', 'This mirrors Morieux''s relay-race argument directly: measuring only individually visible performance can undermine the cooperative behaviors that don''t show up in that metric.'),
  ('TED — Yves Morieux: How too many rules at work keep you from getting things done', 7, 'A leader wants to improve cross-functional cooperation between support and engineering. Based on Morieux''s recommendations, what should they consider doing?', '[{"label": "A", "text": "Introduce stricter, more detailed individual performance metrics for both teams"}, {"label": "B", "text": "Increase the number of formal accountability sign-offs required between teams"}, {"label": "C", "text": "Add more clearly defined middle-office coordinator roles between the two teams"}, {"label": "D", "text": "Reduce rigid interfaces, overly narrow role definitions, and excessive individual metrics that discourage people from investing effort in cooperation"}]'::jsonb, 'D', 'Morieux specifically recommends removing interfaces and reducing narrow metrics, arguing that more structure and clarity of this kind tends to backfire on cooperation.'),
  ('TED — Yves Morieux: How too many rules at work keep you from getting things done', 8, 'Based on this talk, what''s a reasonable takeaway for a team lead trying to improve real cooperation, not just clarity of roles, on their team?', '[{"label": "A", "text": "Add more detailed process documentation and role boundaries to reduce ambiguity"}, {"label": "B", "text": "Rely solely on individual performance dashboards to manage the team"}, {"label": "C", "text": "Assume any cooperation problems must be a personality or attitude issue among team members"}, {"label": "D", "text": "Consider whether current metrics and role boundaries are making it individually costly for people to help each other, and look for ways to reward cooperative behavior, not just individually measurable output"}]'::jsonb, 'D', 'This reflects Morieux''s central argument that structural incentives, not personalities, are usually what''s discouraging cooperation.'),
  ('Creativity, problem solving and generating alternatives', 1, 'Who is the instructor of "Creativity, Problem Solving and Generating Alternatives"?', '[{"label": "A", "text": "Alex Genadinik"}, {"label": "B", "text": "Mihai Alexandru Gafar"}, {"label": "C", "text": "Josh Paulsen"}, {"label": "D", "text": "Learoy Tonight"}]'::jsonb, 'B', 'Mihai Alexandru Gafar, a project manager and trainer, is named as the course''s instructor.'),
  ('Creativity, problem solving and generating alternatives', 2, 'What are the two broad categories of techniques the course teaches for generating solutions?', '[{"label": "A", "text": "Manual techniques and software-based techniques"}, {"label": "B", "text": "Individual techniques and group-only techniques"}, {"label": "C", "text": "Financial techniques and legal techniques"}, {"label": "D", "text": "Rational techniques and creative techniques"}]'::jsonb, 'D', 'The course''s "what you''ll learn" list and section structure both explicitly split its techniques into rational approaches and creative approaches.'),
  ('Creativity, problem solving and generating alternatives', 3, 'What is the title of the course''s final section, focused on breaking through when ideas stop coming?', '[{"label": "A", "text": "\"Closing the deal\""}, {"label": "B", "text": "\"Presenting your ideas\""}, {"label": "C", "text": "\"Final review and certification\""}, {"label": "D", "text": "\"Getting out of a rut\""}]'::jsonb, 'D', 'This is the course''s fifth and final section title, following the introduction, flow, rational, and creative-approach sections.'),
  ('Creativity, problem solving and generating alternatives', 4, 'Why does the course argue that skills like creativity and out-of-the-box thinking are becoming more valuable in an age of automation and AI?', '[{"label": "A", "text": "Because AI has already fully replaced the need for rational problem-solving"}, {"label": "B", "text": "Because creativity is described as irrelevant to modern business needs"}, {"label": "C", "text": "Because these soft skills can''t easily be transferred to machines, unlike many routine or rule-based tasks"}, {"label": "D", "text": "Because automation has made creativity completely obsolete in the workplace"}]'::jsonb, 'C', 'The course description explicitly frames creativity and similar soft skills as valuable specifically because they resist automation.'),
  ('Creativity, problem solving and generating alternatives', 5, 'Why might the course place "Taking rational approaches" and "Using creative approaches" in separate sections rather than teaching them as one blended technique from the start?', '[{"label": "A", "text": "Because the course considers only creative approaches to be useful in practice"}, {"label": "B", "text": "Because rational and creative approaches are described as mutually exclusive and never used together"}, {"label": "C", "text": "Because section order in the course has no particular reasoning behind it"}, {"label": "D", "text": "To let learners first master each type of technique on its own, before the course shows how rational and creative methods can be combined for the best results"}]'::jsonb, 'D', 'The course description explicitly says it covers rational and creative methods separately, then shows how these can be combined to obtain the best result.'),
  ('Creativity, problem solving and generating alternatives', 6, 'A support associate hits a mental block trying to find a workaround for a tricky customer issue and feels stuck. Which course section would most directly help with this specific moment?', '[{"label": "A", "text": "\"Course structure\""}, {"label": "B", "text": "\"Introduction\""}, {"label": "C", "text": "Only \"Taking rational approaches,\" without any creative input"}, {"label": "D", "text": "\"Getting out of a rut\""}]'::jsonb, 'D', 'This section is specifically positioned to address being stuck or out of ideas, matching this scenario directly.'),
  ('Creativity, problem solving and generating alternatives', 7, 'A team wants to generate more than one possible fix for a recurring issue instead of settling on the first workaround. Which course goal does this most directly reflect?', '[{"label": "A", "text": "Increasing self-esteem and confidence, unrelated to generating multiple options"}, {"label": "B", "text": "Learning how to generate alternatives, one of the course''s core stated learning outcomes"}, {"label": "C", "text": "Waiting for a manager to supply the single correct fix"}, {"label": "D", "text": "Only using rational techniques and ignoring creative ones entirely"}]'::jsonb, 'B', '"How to generate alternatives" is listed as the course''s first explicit learning outcome, matching this exact workplace need.'),
  ('Creativity, problem solving and generating alternatives', 8, 'Based on the course, what''s a reasonable habit a support team could build to get better at generating multiple solution options for tricky tickets?', '[{"label": "A", "text": "Deliberately practice both rational, structured techniques and more creative, divergent techniques when a ticket doesn''t have an obvious fix, rather than stopping at the first workaround found"}, {"label": "B", "text": "Avoid generating alternatives, since only rational thinking is useful in a technical context"}, {"label": "C", "text": "Always default to the very first idea proposed, to save time on tickets"}, {"label": "D", "text": "Rely exclusively on one fixed method, regardless of the type of problem"}]'::jsonb, 'A', 'This reflects the course''s core premise of combining rational and creative techniques to generate more, better alternatives, rather than stopping at one first idea.'),
  ('TED — Adam Grant: The surprising habits of original thinkers', 1, 'What company did Grant famously decline to invest in, that later became a billion-dollar business?', '[{"label": "A", "text": "Warby Parker"}, {"label": "B", "text": "Facebook"}, {"label": "C", "text": "Tesla"}, {"label": "D", "text": "Airbnb"}]'::jsonb, 'A', 'Grant opens the talk describing how he passed on investing in Warby Parker, the company''s founders having moved slowly and hedged with backup jobs.'),
  ('TED — Adam Grant: The surprising habits of original thinkers', 2, 'According to Grant''s research with his student Jihae, how did moderate procrastinators compare to precrastinators (people who rush to finish early) in creativity ratings?', '[{"label": "A", "text": "Both groups were rated identically for creativity"}, {"label": "B", "text": "Moderate procrastinators were rated as more creative than precrastinators"}, {"label": "C", "text": "Chronic procrastinators were rated as the most creative of all groups"}, {"label": "D", "text": "Precrastinators were rated as far more creative than any procrastinators"}]'::jsonb, 'B', 'Grant''s research found a "sweet spot" of moderate procrastination associated with higher creativity, while both extremes (rushing and constant procrastination) scored lower.'),
  ('TED — Adam Grant: The surprising habits of original thinkers', 3, 'What two types of doubt does Grant distinguish, and which one does he say is actually productive?', '[{"label": "A", "text": "Financial doubt and creative doubt — financial doubt is productive"}, {"label": "B", "text": "Public doubt and private doubt — public doubt is productive"}, {"label": "C", "text": "Self-doubt (paralyzing) and idea doubt (energizing) — idea doubt is the productive one, motivating testing and refinement"}, {"label": "D", "text": "Rational doubt and emotional doubt — emotional doubt is productive"}]'::jsonb, 'C', 'Grant explicitly separates paralyzing self-doubt from energizing idea doubt, framing the latter as what drives originals to refine their ideas rather than give up.'),
  ('TED — Adam Grant: The surprising habits of original thinkers', 4, 'Why does Grant argue that being a "first mover" is often not actually an advantage, using Facebook and Google as examples?', '[{"label": "A", "text": "Because being first is illegal in most competitive industries"}, {"label": "B", "text": "Because first movers had a much higher failure rate (47%) than \"improvers\" who entered later with something better (8%), showing it''s easier to improve on an existing idea than invent from scratch"}, {"label": "C", "text": "Because Facebook and Google were both technically the very first companies in their categories"}, {"label": "D", "text": "Because first-mover advantage applies only to industries outside of technology"}]'::jsonb, 'B', 'Grant cites this specific statistic and these two companies to argue that originality doesn''t require being first, just different and better.'),
  ('TED — Adam Grant: The surprising habits of original thinkers', 5, 'Why does Grant say that 85% of people in his cross-industry research stayed silent about their biggest idea or suggestion?', '[{"label": "A", "text": "Because company policy explicitly forbade sharing new ideas"}, {"label": "B", "text": "Because they were afraid of embarrassing themselves or looking stupid if the idea turned out to be bad"}, {"label": "C", "text": "Because they believed their managers would immediately implement any idea shared"}, {"label": "D", "text": "Because they didn''t actually have any ideas worth sharing"}]'::jsonb, 'B', 'Grant frames this fear of looking foolish as the reason so many withhold their ideas, contrasting it with originals who share ideas despite the same fear.'),
  ('TED — Adam Grant: The surprising habits of original thinkers', 6, 'A team member has a promising but unconventional idea for improving a support process, but hesitates to bring it up in a team meeting. Applying Grant''s talk, what''s a reasonable way to think about this hesitation?', '[{"label": "A", "text": "The fear of the idea being bad is normal — even originals feel it — and speaking up despite that fear is what separates originals from those who stay silent"}, {"label": "B", "text": "They should abandon ideas that cause any hesitation whatsoever"}, {"label": "C", "text": "They should assume the idea is bad since they feel uncertain about it"}, {"label": "D", "text": "They should wait until they are completely certain the idea is perfect before mentioning it"}]'::jsonb, 'A', 'Grant''s research shows that idea doubt is normal and productive, and that a large share of people stay silent out of fear rather than because their ideas lack merit.'),
  ('TED — Adam Grant: The surprising habits of original thinkers', 7, 'A manager wants their team to generate more original process improvements. Based on Grant''s findings about output and originality, what approach would help?', '[{"label": "A", "text": "Discourage revisiting or generating additional ideas once one has been proposed"}, {"label": "B", "text": "Ask the team to submit only their single best idea per quarter to maintain quality"}, {"label": "C", "text": "Reward only the very first idea suggested in any brainstorming session"}, {"label": "D", "text": "Encourage generating a larger volume of ideas overall, since even history''s most original people, like Bach, Beethoven, and Mozart, needed hundreds of works to produce a smaller number of true standouts"}]'::jsonb, 'D', 'Grant explicitly ties higher idea volume to a better chance of landing on something truly original, using classical composers as his example.'),
  ('TED — Adam Grant: The surprising habits of original thinkers', 8, 'Based on this talk, what''s a reasonable takeaway for a support team wanting to become more comfortable proposing process changes or new ideas?', '[{"label": "A", "text": "Avoid proposing ideas that could turn out to be wrong"}, {"label": "B", "text": "Normalize sharing imperfect, in-progress ideas and treating early doubt as a sign to refine rather than a reason to stay silent, since most withheld ideas are lost to fear rather than lack of merit"}, {"label": "C", "text": "Assume that hesitation about an idea means it should be dropped entirely"}, {"label": "D", "text": "Only share ideas once they are fully polished and certain to succeed"}]'::jsonb, 'B', 'This applies Grant''s core distinction between paralyzing self-doubt and productive idea-doubt to a concrete team communication habit.'),
  ('The Customer: How to Understand Their Needs (BITE SIZE)', 1, 'Who is the instructor/company behind "The Customer: How to Understand Their Needs (BITE SIZE)"?', '[{"label": "A", "text": "Mihai Alexandru Gafar"}, {"label": "B", "text": "PracticalGrowth Learning"}, {"label": "C", "text": "Learoy Tonight"}, {"label": "D", "text": "Lauren Powers"}]'::jsonb, 'C', 'Learoy Tonight, described as a "bite size learning" education company, is named as the course''s creator.'),
  ('The Customer: How to Understand Their Needs (BITE SIZE)', 2, 'What distinction does the course teach between two types of customers within an organization?', '[{"label": "A", "text": "Returning customers and new customers"}, {"label": "B", "text": "Internal customers and external customers"}, {"label": "C", "text": "Premium customers and standard customers"}, {"label": "D", "text": "Digital customers and in-person customers"}]'::jsonb, 'B', '"Internal and External Customers" is one of the course''s named sections, teaching this specific distinction and how it affects service outcomes.'),
  ('The Customer: How to Understand Their Needs (BITE SIZE)', 3, 'Besides the general modern customer, what specific customer segment does the course say it addresses strategies for?', '[{"label": "A", "text": "The government customer"}, {"label": "B", "text": "The wholesale customer"}, {"label": "C", "text": "The \"millennial\" customer"}, {"label": "D", "text": "The retiree customer"}]'::jsonb, 'C', 'The course''s learning objectives specifically call out developing strategies to support the modern day customer, "inclusive of the ''millennial'' customer."'),
  ('The Customer: How to Understand Their Needs (BITE SIZE)', 4, 'Why does the course emphasize that internal service impacts external service?', '[{"label": "A", "text": "Because how employees treat and support each other inside an organization directly shapes the quality of service that reaches external, paying customers"}, {"label": "B", "text": "Because internal service has no real connection to how customers experience a business"}, {"label": "C", "text": "Because internal and external customers are actually the same audience with different names"}, {"label": "D", "text": "Because external service is the only thing organizations should focus on measuring"}]'::jsonb, 'A', 'This is one of the course''s explicit learning objectives — recognizing how internal service impacts external service — establishing that the two are directly connected, not separate concerns.'),
  ('The Customer: How to Understand Their Needs (BITE SIZE)', 5, 'Why might the course pair "customer satisfaction" content with a separate section specifically on "the modern day customer"?', '[{"label": "A", "text": "Because general principles of customer satisfaction are foundational, but customer expectations and behavior have also evolved over time and need their own dedicated treatment"}, {"label": "B", "text": "Because modern customers are described as no longer caring about satisfaction at all"}, {"label": "C", "text": "Because the course argues older customer service principles are now completely irrelevant"}, {"label": "D", "text": "Because customer satisfaction and the modern customer are identical topics repeated for emphasis"}]'::jsonb, 'A', 'The course''s structure and its explicit goal of covering "how their needs have changed over time" suggest foundational satisfaction concepts are built on, then updated for modern customer expectations.'),
  ('The Customer: How to Understand Their Needs (BITE SIZE)', 6, 'A support agent resolves a customer''s technical issue quickly but the customer still leaves an unhappy review, mentioning they felt unheard. Which course concept applies most directly?', '[{"label": "A", "text": "Escalating every future ticket from this customer regardless of complexity"}, {"label": "B", "text": "Focusing exclusively on reducing average handling time for future tickets"}, {"label": "C", "text": "Assuming the customer is simply impossible to satisfy and moving on"}, {"label": "D", "text": "Developing strategies to gain an emotional connection with the customer, since a fast technical fix alone doesn''t guarantee the customer feels valued or understood"}]'::jsonb, 'D', 'The course explicitly lists developing an emotional connection with the customer as a learning objective, distinct from simply resolving the technical issue.'),
  ('The Customer: How to Understand Their Needs (BITE SIZE)', 7, 'A team wants to improve how a poor internal handoff between departments is affecting the customer''s experience. Which course concept is most relevant?', '[{"label": "A", "text": "Focusing solely on external marketing to offset internal service issues"}, {"label": "B", "text": "Assuming customer experience is determined only by the final point of contact"}, {"label": "C", "text": "Treating internal handoffs as irrelevant to the customer''s actual experience"}, {"label": "D", "text": "Recognizing how internal service impacts external service, and treating internal colleagues as \"internal customers\" whose needs also matter"}]'::jsonb, 'D', 'This directly reflects the course''s core theme connecting internal customer treatment to the external customer experience.'),
  ('The Customer: How to Understand Their Needs (BITE SIZE)', 8, 'Based on the course, what''s a reasonable takeaway for a support team that wants to build a more "customer centric" culture, as the course frames it?', '[{"label": "A", "text": "Focus exclusively on external customer-facing metrics and ignore internal team dynamics"}, {"label": "B", "text": "Pay attention to both how customers are treated directly and how internal teams treat each other, since the course frames both as shaping the overall customer experience"}, {"label": "C", "text": "Assume customer centricity is only relevant to sales and marketing roles"}, {"label": "D", "text": "Treat customer strategy as a one-time initiative rather than an ongoing practice"}]'::jsonb, 'B', 'This reflects the course''s core argument that a genuinely customer-centric culture requires attention to internal service quality, not just external interactions.'),
  ('TED — Joe Gebbia: How Airbnb designs for trust', 1, 'What personal experience does Gebbia describe as his "first hosting experience," which shaped his perspective on strangers?', '[{"label": "A", "text": "Letting a stranger he''d just met at his yard sale sleep on an airbed in his living room"}, {"label": "B", "text": "Hosting an exchange student for a full school year"}, {"label": "C", "text": "Renting out his childhood bedroom to a college student"}, {"label": "D", "text": "Sharing his car with a coworker during a business trip"}]'::jsonb, 'A', 'Gebbia opens the talk with this yard-sale story as the experience that reshaped how he thought about "strangers."'),
  ('TED — Joe Gebbia: How Airbnb designs for trust', 2, 'What was the original name of the business that later became Airbnb?', '[{"label": "A", "text": "Couch and Coffee"}, {"label": "B", "text": "Stay and Share"}, {"label": "C", "text": "Bed and Beyond"}, {"label": "D", "text": "Airbed and Breakfast"}]'::jsonb, 'D', 'Gebbia describes renting out airbeds with breakfast to designers visiting a conference, under the name "Airbed and Breakfast," before it became Airbnb.'),
  ('TED — Joe Gebbia: How Airbnb designs for trust', 3, 'What live audience demonstration does Gebbia use to illustrate the level of trust hosts extend to guests?', '[{"label": "A", "text": "Asking audience members to exchange wallets with a stranger"}, {"label": "B", "text": "Asking audience members to share their home address out loud"}, {"label": "C", "text": "Asking audience members to write down a personal secret and read it aloud"}, {"label": "D", "text": "Asking audience members to unlock their phones and hand them to the person next to them"}]'::jsonb, 'D', 'Gebbia uses this phone-handover exercise specifically to simulate the vulnerability a host feels when welcoming a stranger into their home.'),
  ('TED — Joe Gebbia: How Airbnb designs for trust', 4, 'Why does Gebbia say a well-designed reputation system (like reviews) was key to building trust between strangers on Airbnb?', '[{"label": "A", "text": "Because reviews are mainly used to determine pricing, not trust"}, {"label": "B", "text": "Because reviews are only useful for hosts, not guests"}, {"label": "C", "text": "Because seeing evidence like reviews from other users makes people more willing to trust someone they''ve never met, overcoming the natural \"stranger-danger\" bias"}, {"label": "D", "text": "Because reputation systems eliminate the need for any other trust-building design"}]'::jsonb, 'C', 'Gebbia explicitly connects reputation systems, like reviews, to overcoming deep-seated biases against trusting unfamiliar people.'),
  ('TED — Joe Gebbia: How Airbnb designs for trust', 5, 'Why does Gebbia describe the "right amount of disclosure" as important when a guest first messages a host?', '[{"label": "A", "text": "Because disclosure has no measurable effect on whether a host accepts a booking"}, {"label": "B", "text": "Because guests are required by policy to disclose a fixed set of personal details"}, {"label": "C", "text": "Because sharing too little (e.g., a one-word message) or too much overly personal information both lowered acceptance rates, while a specific, friendly middle ground worked best"}, {"label": "D", "text": "Because more disclosure always leads to a higher acceptance rate, without exception"}]'::jsonb, 'C', 'Gebbia specifically describes testing different levels of message disclosure and finding that a middle "zone" of sharing performed best.'),
  ('TED — Joe Gebbia: How Airbnb designs for trust', 6, 'A company wants to help two people who have never met collaborate confidently on a shared project. Applying Gebbia''s design principles, what would help build trust between them?', '[{"label": "A", "text": "Avoid any structured introduction and let them figure out trust entirely on their own"}, {"label": "B", "text": "Give them a way to see each other''s track record or reputation (e.g., past work, references) and provide easy prompts for appropriate self-introduction"}, {"label": "C", "text": "Have them work entirely anonymously with no information shared about either party"}, {"label": "D", "text": "Require a lengthy legal agreement before any interaction can occur"}]'::jsonb, 'B', 'This mirrors Gebbia''s two key design levers — reputation systems and guided, appropriately-scoped disclosure — applied to a different context requiring trust between strangers.'),
  ('TED — Joe Gebbia: How Airbnb designs for trust', 7, 'A platform wants to reduce hesitation from new users who are nervous about a first-time interaction with an unfamiliar party. Based on Gebbia''s Stanford study finding, what specific factor besides similarity could help overcome hesitation?', '[{"label": "A", "text": "A strong reputation, such as many positive reviews, can outweigh a lack of similarity in age, location, or background between two people"}, {"label": "B", "text": "Only matching people with highly similar backgrounds can ever build trust"}, {"label": "C", "text": "Reputation has no measurable effect once basic similarity is accounted for"}, {"label": "D", "text": "Trust between dissimilar people is described as impossible to design for"}]'::jsonb, 'A', 'Gebbia''s cited Stanford study found that high reputation (10+ reviews) could outweigh the natural bias toward trusting similar people.'),
  ('TED — Joe Gebbia: How Airbnb designs for trust', 8, 'Based on this talk, what''s a reasonable takeaway for a team designing a process where colleagues or customers need to build trust quickly with someone unfamiliar?', '[{"label": "A", "text": "Minimize all information exchange to avoid any risk of oversharing"}, {"label": "B", "text": "Require full transparency of all personal information regardless of context"}, {"label": "C", "text": "Assume trust cannot be influenced by design and will form purely by chance"}, {"label": "D", "text": "Intentionally design for trust — for example, surfacing relevant track record or reputation and guiding the right amount of personal disclosure — rather than assuming trust will develop naturally on its own"}]'::jsonb, 'D', 'This reflects Gebbia''s central argument that trust between strangers can be deliberately designed for, using specific, tested techniques rather than being left to chance.'),
  ('Trailhead module: Best Practices for Troubleshooting', 1, 'What are the four stages of the troubleshooting cycle taught in this module, in order?', '[{"label": "A", "text": "Research → Identify → Test → Share"}, {"label": "B", "text": "Replicate → Identify → Implement → Hypothesize"}, {"label": "C", "text": "Identify → Replicate & Research → Hypothesize & Test → Implement & Share"}, {"label": "D", "text": "Identify → Hypothesize → Replicate → Implement"}]'::jsonb, 'C', 'The module''s four units run in exactly this sequence, each building on the previous stage''s output.'),
  ('Trailhead module: Best Practices for Troubleshooting', 2, 'Why does the module recommend logging every reported issue through one official channel instead of email, Slack DMs, and hallway conversations?', '[{"label": "A", "text": "It reduces the total number of issues reported"}, {"label": "B", "text": "It stops non-admins from ever seeing reported issues"}, {"label": "C", "text": "It guarantees every issue is fixed within 24 hours"}, {"label": "D", "text": "A single channel keeps documentation consistent and makes it possible to spot recurring patterns across reports"}]'::jsonb, 'D', 'Unit 1 ties a centralized channel to consistent documentation and pattern recognition, not to reducing volume or guaranteeing speed.'),
  ('Trailhead module: Best Practices for Troubleshooting', 3, 'Before attempting any fix, what should you gather from the reporting user, per Unit 1?', '[{"label": "A", "text": "Only the user''s name and job title"}, {"label": "B", "text": "Expected vs. actual outcome, the triggering actions, how to reproduce it, and details like browser/device and error messages"}, {"label": "C", "text": "Only whether they''ve restarted their computer"}, {"label": "D", "text": "Only a screenshot, nothing else"}]'::jsonb, 'B', 'Unit 1 lists these specific follow-up questions as necessary to avoid solving the wrong problem.'),
  ('Trailhead module: Best Practices for Troubleshooting', 4, 'Why should a candidate fix be tested in a sandbox rather than production, according to Unit 2?', '[{"label": "A", "text": "Sandboxes automatically undo any mistake"}, {"label": "B", "text": "Production doesn''t allow admin logins"}, {"label": "C", "text": "A sandbox is a safe copy of production, so testing there avoids risking real user data or workflows"}, {"label": "D", "text": "Sandboxes run faster than production"}]'::jsonb, 'C', 'Unit 2 frames the sandbox as a safe testing copy specifically to protect production from untested changes.'),
  ('Trailhead module: Best Practices for Troubleshooting', 5, 'What key limitation of Event Log Files must you account for when investigating a reported issue?', '[{"label": "A", "text": "They require a separate paid license to access"}, {"label": "B", "text": "They''re only available 24+ hours after the events occurred"}, {"label": "C", "text": "They only cover the last 10 minutes of activity"}, {"label": "D", "text": "They can''t record API activity, only logins"}]'::jsonb, 'B', 'Unit 2 explicitly notes Event Log Files are ''available 24+ hours after events,'' which limits how recently you can investigate.'),
  ('Trailhead module: Best Practices for Troubleshooting', 6, 'When your first attempted fix doesn''t resolve the issue, what does the module say that failed attempt is actually useful for?', '[{"label": "A", "text": "It means you should restart the identification phase from scratch"}, {"label": "B", "text": "It should be discarded immediately and never referenced again"}, {"label": "C", "text": "It narrows down the possibilities and informs which fix to try next"}, {"label": "D", "text": "It proves the issue can''t be fixed"}]'::jsonb, 'C', 'Unit 3 treats early failures as expected and informative, feeding into the next most likely guess rather than being a dead end.'),
  ('Trailhead module: Best Practices for Troubleshooting', 7, 'A customer says ''some of our schedulers can''t see the new Job list view, but others can.'' You''ve confirmed everyone shares the same profile. What should you do immediately, before proposing any fix?', '[{"label": "A", "text": "Deploy a permission-set fix to all schedulers right away"}, {"label": "B", "text": "Escalate to engineering without any internal investigation"}, {"label": "C", "text": "Tell the customer it''s expected behavior without checking further"}, {"label": "D", "text": "Replicate the issue yourself, ideally logged in as one of the affected schedulers, to confirm scope and pin down the exact trigger conditions"}]'::jsonb, 'D', 'This mirrors Unit 2''s guidance to replicate as the affected user before hypothesizing a cause — jumping straight to a fix risks solving the wrong problem for the wrong people.'),
  ('Trailhead module: Best Practices for Troubleshooting', 8, 'You applied what you believed was the fix for a customer''s broken automation, and the customer says it now ''seems to work.'' What should you do before closing the ticket?', '[{"label": "A", "text": "Assume it''s fixed because your own sandbox test passed once"}, {"label": "B", "text": "Re-test using the same variables as the original report (trigger, timing, record type) and confirm success across more than one account or job"}, {"label": "C", "text": "Ask the customer to test again in a week and close the ticket now"}, {"label": "D", "text": "Close the ticket immediately since the customer confirmed it works"}]'::jsonb, 'B', 'Unit 3 requires replicating the original variables and testing across accounts before treating a fix as verified — a single anecdotal ''seems to work'' isn''t sufficient proof.'),
  ('Trailhead module: Best Practices for Troubleshooting', 9, 'You''re about to deploy a fix that will briefly disable job dispatch for a customer''s whole team. What must happen before you deploy, per Unit 4?', '[{"label": "A", "text": "Nothing — as long as the fix works, no advance communication is required"}, {"label": "B", "text": "Only the account manager needs to know, not the affected users"}, {"label": "C", "text": "Share an implementation plan covering timing, specific actions, expected user impact, and downtime, so stakeholders have visibility and a chance to raise concerns"}, {"label": "D", "text": "Deploy first, then document what happened if someone asks"}]'::jsonb, 'C', 'Unit 4 requires sharing the implementation plan before deployment specifically to build transparency and allow for feedback or approval.'),
  ('Trailhead module: Best Practices for Troubleshooting', 10, 'A ticket lands: ''Job Allocations for one resource keep disappearing from their mobile app, but only sometimes.'' Applying the full four-stage cycle this course builds, what is the correct sequence of what you should do?', '[{"label": "A", "text": "Implement a fix immediately, then ask the user what happened afterward"}, {"label": "B", "text": "Ask the user to identify the fix themselves, then hypothesize whether it will work"}, {"label": "C", "text": "Replicate the issue in production so the customer can watch"}, {"label": "D", "text": "Identify exactly what''s happening from the user; replicate it yourself and research if it''s known; form and test a hypothesis for the cause; implement the fix and share the outcome"}]'::jsonb, 'D', 'This exercises the exact competency this course is meant to build — applying the identify, replicate, hypothesise, implement cycle end-to-end to isolate a reported fault, not just naming the stages.'),
  ('Skedulo Pulse Admin Fundamentals', 1, 'Which learning domain covers completing the onboarding wizard and configuring general settings/preferences for a new tenant?', '[{"label": "A", "text": "Mobility"}, {"label": "B", "text": "Environment setup"}, {"label": "C", "text": "User management"}, {"label": "D", "text": "Data modeling"}]'::jsonb, 'B', 'The curriculum''s ''Environment setup'' domain opens with the onboarding wizard and general settings/preferences, before any other configuration.'),
  ('Skedulo Pulse Admin Fundamentals', 2, 'What''s the difference between ''functional permissions'' and ''record access policies'' in the Security domain?', '[{"label": "A", "text": "Record access policies only affect mobile app users"}, {"label": "B", "text": "Functional permissions control data, and record access policies control the UI"}, {"label": "C", "text": "They are interchangeable settings with the same effect"}, {"label": "D", "text": "Functional permissions control what actions/features a role can use, while record access policies control which specific records a role can see or edit"}]'::jsonb, 'D', 'The curriculum separates these deliberately: functional permissions gate features/actions, while record access policies gate visibility of specific data.'),
  ('Skedulo Pulse Admin Fundamentals', 3, 'What does adding a custom field (with the custom suffix) let a tenant capture that a standard field cannot?', '[{"label": "A", "text": "A webhook trigger with no automation setup required"}, {"label": "B", "text": "A bypass of all permission sets"}, {"label": "C", "text": "Information specific to that tenant''s business needs that isn''t part of Skedulo''s out-of-the-box data model"}, {"label": "D", "text": "Automatic syncing to Salesforce reports with no configuration"}]'::jsonb, 'C', 'Custom fields exist precisely to extend the standard data model with tenant-specific information.'),
  ('Skedulo Pulse Admin Fundamentals', 4, 'Which domain would you use to bulk-load a customer''s existing spreadsheet of records into a brand-new tenant?', '[{"label": "A", "text": "Data modeling"}, {"label": "B", "text": "Automation"}, {"label": "C", "text": "Data Management"}, {"label": "D", "text": "User Interface"}]'::jsonb, 'C', 'Data Management covers import/update data, bulk import users, and migrating data to Skedulo — the resources for loading existing records.'),
  ('Skedulo Pulse Admin Fundamentals', 5, 'What is the relationship between ''Manage resource requirements'' and ''Allocate work'' under Scheduling & Optimization?', '[{"label": "A", "text": "They are unrelated features in different parts of the platform"}, {"label": "B", "text": "Resource requirements only apply to mobile-created jobs"}, {"label": "C", "text": "Allocation happens automatically with no relation to requirements"}, {"label": "D", "text": "Resource requirements define what a job needs to be properly staffed, and allocation is the act of assigning a specific resource to fulfill that need"}]'::jsonb, 'D', 'Requirements define the staffing need first; allocation is the subsequent step of fulfilling it with a specific resource.'),
  ('Skedulo Pulse Admin Fundamentals', 6, 'Why does the curriculum separate ''Create and Manage Data Object'' (Data modeling) from ''Manage Custom Fields'' as different learning items?', '[{"label": "A", "text": "Creating a data object adds a brand-new record type, while managing custom fields adds new attributes to a record type that already exists"}, {"label": "B", "text": "They cover the exact same task with different names"}, {"label": "C", "text": "Custom fields can only exist on Salesforce objects, never Pulse Platform objects"}, {"label": "D", "text": "Data objects are mobile-only and custom fields are web-only"}]'::jsonb, 'A', 'These are genuinely different actions — building a new object type versus extending an existing one with fields — which is why they''re taught separately.'),
  ('Skedulo Pulse Admin Fundamentals', 7, 'A new customer needs dispatchers in different states to only see jobs and resources for their own state, and each state''s schedulers work slightly different hours. Which two domains do you need together to configure this?', '[{"label": "A", "text": "Security (record access policies to scope visibility) together with Scheduling & Optimization/Environment setup (for region-based availability and settings)"}, {"label": "B", "text": "Only Data Management, since this is a data-loading task"}, {"label": "C", "text": "Only Automation, since this is a workflow problem"}, {"label": "D", "text": "Only Mobility, since dispatchers use the mobile app"}]'::jsonb, 'A', 'This requires combining record-level access control with region/availability configuration — neither domain alone solves both the visibility and the scheduling-hours requirement.'),
  ('Skedulo Pulse Admin Fundamentals', 8, 'A customer reports that some staff can now see jobs from other departments they shouldn''t, even though nobody''s permission set changed. Where should you look first, given the curriculum''s functional-permissions vs. record-access-policy distinction?', '[{"label": "A", "text": "The mobile app version, since it may be out of date"}, {"label": "B", "text": "A record access policy or its rules/template, since that governs which specific records a role can see, independent of functional permission sets"}, {"label": "C", "text": "The onboarding wizard, since it was probably re-run by accident"}, {"label": "D", "text": "A custom field, since one may have been deleted"}]'::jsonb, 'B', 'Since the symptom is about record visibility (not feature access) and permission sets are confirmed unchanged, record access policies are the more likely area to investigate, not functional permissions.'),
  ('Skedulo Pulse Admin Fundamentals', 9, 'A tenant wants to track ''Equipment Inspection'' results tied to each Job, with a few tenant-specific fields, and wants inspectors to only edit their own inspection records. Which domains does this span, and in what relationship?', '[{"label": "A", "text": "Low-code only, since no new object is actually needed"}, {"label": "B", "text": "Data modeling (to build the new object and its custom fields) plus Security (a record access policy so inspectors only edit their own records)"}, {"label": "C", "text": "Mobility only, since inspectors likely use the mobile app"}, {"label": "D", "text": "Data Management only, since this is about loading a new record type"}]'::jsonb, 'B', 'Creating a new object with fields is Data modeling; restricting who can edit which specific records is Security''s record access policies — this genuinely requires both, not either alone.'),
  ('Skedulo Pulse Admin Fundamentals', 10, 'You''re setting up a brand-new tenant end-to-end: general settings, a couple of custom objects and fields, two regions with different availability patterns, and the first batch of jobs staffed and dispatched. Which step, if skipped, would most directly block allocation and dispatch at the end?', '[{"label": "A", "text": "Skipping optional low-code list view styling"}, {"label": "B", "text": "Skipping custom field display labels, which are cosmetic only"}, {"label": "C", "text": "Skipping the onboarding wizard''s welcome screen"}, {"label": "D", "text": "Skipping availability setup for resources in each region, since jobs can''t be reliably allocated to resources whose availability hasn''t been defined"}]'::jsonb, 'D', 'This exercises the full ''end to end'' expectation directly: of all the pieces (settings, objects/fields, regions, availability), missing availability is the one that actually blocks staffing and dispatch.'),
  ('Salesforce Basics', 1, 'What does the ''__c'' suffix on a Salesforce field or object name indicate?', '[{"label": "A", "text": "It means the field is only visible to admins"}, {"label": "B", "text": "It means the field is required"}, {"label": "C", "text": "It means the field is deprecated"}, {"label": "D", "text": "It''s a custom field/object added for that specific org, not a standard platform feature"}]'::jsonb, 'D', '''__c'' is Salesforce''s naming convention marking custom fields and objects, distinguishing them from standard platform elements.'),
  ('Salesforce Basics', 2, 'Which unit specifically covers where an admin goes to add or change configuration like fields, security settings, and objects?', '[{"label": "A", "text": "Navigate Setup"}, {"label": "B", "text": "Power Up with AppExchange"}, {"label": "C", "text": "Discover Use Cases"}, {"label": "D", "text": "Understand the Salesforce Architecture"}]'::jsonb, 'A', '''Navigate Setup'' is the dedicated unit for finding and using the admin configuration area.'),
  ('Salesforce Basics', 3, 'What does the AppExchange marketplace let a customer do?', '[{"label": "A", "text": "Automatically migrate data between two unrelated orgs"}, {"label": "B", "text": "Directly edit Salesforce''s core source code"}, {"label": "C", "text": "Install pre-built third-party solutions instead of building equivalent functionality from scratch"}, {"label": "D", "text": "Bypass all permission set restrictions"}]'::jsonb, 'C', 'AppExchange is the platform''s marketplace for extending functionality through pre-built, installable packages.'),
  ('Salesforce Basics', 4, 'Is the standard ''Account'' object a Salesforce platform feature or a Skedulo-specific customization?', '[{"label": "A", "text": "A Skedulo-managed custom object"}, {"label": "B", "text": "A deprecated legacy object"}, {"label": "C", "text": "A standard Salesforce object, part of the base platform, independent of Skedulo''s managed package"}, {"label": "D", "text": "A field only available after Skedulo Plus is enabled"}]'::jsonb, 'C', 'Account is a core standard object that exists on the platform regardless of any managed package or customer customisation.'),
  ('Salesforce Basics', 5, 'What does the ''Understand the Salesforce Architecture'' unit help you grasp?', '[{"label": "A", "text": "How to write Apex classes from scratch"}, {"label": "B", "text": "How Salesforce licensing and billing is calculated"}, {"label": "C", "text": "How standard platform capabilities and org-specific customizations coexist within the same Salesforce org"}, {"label": "D", "text": "How to migrate an org between data centers"}]'::jsonb, 'C', 'This unit builds the conceptual foundation for how standard and custom elements fit together within one org.'),
  ('Salesforce Basics', 6, 'What''s the practical reason this module treats ''standard vs. custom'' as foundational for support, rather than just Salesforce trivia?', '[{"label": "A", "text": "It''s only relevant for passing a certification exam"}, {"label": "B", "text": "It has no real effect on how a ticket gets investigated"}, {"label": "C", "text": "It''s the first judgment call in triage — whether a reported issue is a platform-wide matter or specific to that customer''s own configuration"}, {"label": "D", "text": "It only matters for objects created before 2020"}]'::jsonb, 'C', 'This distinction directly shapes the investigation path from the very start of a ticket.'),
  ('Salesforce Basics', 7, 'A ticket describes odd behavior on a field called ''Shift_Notes__c'' that exists in only one customer''s org. How should this change your triage compared to a report about the standard Account object misbehaving across many customers?', '[{"label": "A", "text": "Treat it as likely tied to that customer''s own configuration or a custom automation/validation rule, rather than assuming a Skedulo-wide platform bug"}, {"label": "B", "text": "Assume it''s a Salesforce outage affecting all customers"}, {"label": "C", "text": "Treat it exactly the same as a standard-object bug and escalate to engineering immediately"}, {"label": "D", "text": "Assume the field name is a typo and ignore the report"}]'::jsonb, 'A', 'Applying the standard/custom distinction correctly scopes the investigation toward customer-specific configuration rather than a shared platform defect.'),
  ('Salesforce Basics', 8, 'Two customers report ''the same'' Job list view issue, but one customer''s list view has clearly been customized with extra columns and filters, while the other uses Skedulo''s default. How should this shape your investigation of each?', '[{"label": "A", "text": "The customized org''s issue is definitely a Skedulo bug, since customization always breaks features"}, {"label": "B", "text": "Both should be investigated identically since ''list view'' is a standard feature either way"}, {"label": "C", "text": "Neither is worth investigating since list views aren''t configurable"}, {"label": "D", "text": "The customized org''s issue may stem from its own configuration and needs org-specific investigation, while the default-view issue is more likely a genuine platform-wide bug worth checking against other customers"}]'::jsonb, 'D', 'This requires reasoning about how customization changes the likely root cause and investigation path, not simply labeling one org as ''customized.'''),
  ('Salesforce Basics', 9, 'A customer''s admin insists a bug is ''in Skedulo'' because it started ''right after your last release,'' but the affected object is one they built and customized years ago. How does understanding standard-vs-custom shape your response?', '[{"label": "A", "text": "Check whether the release actually touched anything the custom object depends on; if not, the timing is likely coincidental and the cause more likely sits in their own configuration or another change on their side"}, {"label": "B", "text": "Agree it''s a Skedulo bug purely based on the timing the customer describes"}, {"label": "C", "text": "Tell them customizations can never break, so it must be unrelated to anything they did"}, {"label": "D", "text": "Refuse to investigate since it''s a custom object"}]'::jsonb, 'A', 'This applies the distinction to a common real-world trap — timing coincidence versus actual causation — rather than just labeling the object as custom.'),
  ('Salesforce Basics', 10, 'You''re handed a ticket where a customer says a ''field'' behaves unexpectedly, but doesn''t say whether it''s something Skedulo ships or something their own admin added. What''s the very first thing you should determine, and how?', '[{"label": "A", "text": "Whether the field carries a custom suffix (like ''__c'') or otherwise appears in the org''s custom configuration, versus being one of Skedulo''s standard/packaged fields — since that determines whether you''re investigating a platform issue or the customer''s own setup"}, {"label": "B", "text": "The customer''s subscription tier, since that determines who''s at fault"}, {"label": "C", "text": "The number of users affected, since severity always matters more than origin"}, {"label": "D", "text": "The field''s data type, since that matters more than its origin"}]'::jsonb, 'A', 'This directly exercises ''distinguishes standard Salesforce platform objects and features from customer customisation'' as the first triage step on an ambiguous report.'),
  ('Skedulo release notes — track what''s new each release', 1, 'How are entries organized on the Skedulo release notes page?', '[{"label": "A", "text": "Chronologically, newest first, with a publication date on each entry"}, {"label": "B", "text": "Randomly, requiring a search every time"}, {"label": "C", "text": "Alphabetically by feature name"}, {"label": "D", "text": "Grouped only by customer account"}]'::jsonb, 'A', 'Release notes run newest-first with a visible date, which is what lets you pin down exactly when a change shipped.'),
  ('Skedulo release notes — track what''s new each release', 2, 'What does a typical release note entry contain?', '[{"label": "A", "text": "A customer testimonial and a pricing note"}, {"label": "B", "text": "A video walkthrough and a support ticket number"}, {"label": "C", "text": "A headline, a short summary, a screenshot/diagram, and metadata tags (feature area, audience, platform)"}, {"label": "D", "text": "Only a headline and a date, nothing else"}]'::jsonb, 'C', 'Each entry has these standard components, giving both a quick summary and enough detail to confirm it matches a reported change.'),
  ('Skedulo release notes — track what''s new each release', 3, 'Which sidebar options let you narrow release notes to a specific audience, feature area, or platform?', '[{"label": "A", "text": "A comments section on each entry"}, {"label": "B", "text": "Sorting by number of views"}, {"label": "C", "text": "Filters for Roles, Categories, and Platforms, plus date range"}, {"label": "D", "text": "A single search box with no other filters"}]'::jsonb, 'C', 'These filters are what let you scope 30+ pages of history down to a relevant subset.'),
  ('Skedulo release notes — track what''s new each release', 4, 'What does an entry''s ''Platform'' tag tell you?', '[{"label": "A", "text": "The internal Jira ticket number"}, {"label": "B", "text": "The engineer who built the feature"}, {"label": "C", "text": "Whether the change applies to the Skedulo Pulse Platform, the Salesforce-based version, or both"}, {"label": "D", "text": "Which country the feature launched in first"}]'::jsonb, 'C', 'The Platform tag scopes a release to the relevant product version, which matters when the customer''s tenant might only be on one of them.'),
  ('Skedulo release notes — track what''s new each release', 5, 'Roughly how deep is the release notes archive, and what does that imply about finding an older entry?', '[{"label": "A", "text": "30+ pages of history, so filtering or search is far more efficient than manually paging through"}, {"label": "B", "text": "There is no historical archive, only the current month"}, {"label": "C", "text": "It resets every year, deleting old entries"}, {"label": "D", "text": "Only 2-3 pages, so scrolling is always fastest"}]'::jsonb, 'A', 'Given the archive''s depth, using the filters/search is the practical way to locate a specific past entry.'),
  ('Skedulo release notes — track what''s new each release', 6, 'If a release note and a customer-reported issue share the same feature-area tag and a plausible date, what does that suggest?', '[{"label": "A", "text": "It proves the release note is inaccurate"}, {"label": "B", "text": "They are definitely unrelated, since tags are cosmetic only"}, {"label": "C", "text": "It means the customer must be on an outdated version"}, {"label": "D", "text": "The reported ''issue'' may actually be an intentional change described in that note, worth checking before assuming it''s a bug"}]'::jsonb, 'D', 'Matching tag and timing is a strong signal to check the note itself before treating a described change as a defect.'),
  ('Skedulo release notes — track what''s new each release', 7, 'A customer says ''Optimization Recipes looks totally different since last month and now it''s broken.'' What''s the fastest way to confirm this is a shipped UI change rather than a bug?', '[{"label": "A", "text": "Filter or search the release notes by feature area (e.g., ''Optimization'') around the relevant date to find the entry describing the redesign, then compare it to what the customer sees"}, {"label": "B", "text": "Ask the customer for a video of the ''bug'' and file a Jira ticket without checking anything else first"}, {"label": "C", "text": "Tell the customer no changes were made, without checking any records"}, {"label": "D", "text": "Assume it''s a bug since the customer says so"}]'::jsonb, 'A', 'This requires actually using the filter/search system to test a specific hypothesis, not just knowing that release notes exist.'),
  ('Skedulo release notes — track what''s new each release', 8, 'You''re drafting a client response explaining why a scheduling behavior changed, and want the customer to trust the explanation rather than take your word for it. What should you include, and why?', '[{"label": "A", "text": "Nothing — a verbal explanation from support is always sufficient"}, {"label": "B", "text": "A link to the specific release note entry describing the change, since it''s Skedulo''s own dated, published record — more authoritative than a verbal explanation"}, {"label": "C", "text": "A generic link to the release notes homepage with no specific entry"}, {"label": "D", "text": "A screenshot of your own internal Slack conversation about the change"}]'::jsonb, 'B', 'This applies the ''link a reported change to the note that introduced it'' skill directly to client communication — the specific entry, not a vague pointer.'),
  ('Skedulo release notes — track what''s new each release', 9, 'A customer reports a change but gives a vague timeframe (''sometime in the last couple months'') and no feature name. How would you use the release notes'' structure to track this down efficiently?', '[{"label": "A", "text": "Use the date-range filter to narrow to that window, then scan headlines/summaries or matching categories, rather than reading every entry from the start"}, {"label": "B", "text": "Read every single entry from the beginning of the archive in order"}, {"label": "C", "text": "Ask the customer to find the release note themselves"}, {"label": "D", "text": "Conclude it''s untraceable since no exact date or feature name was given"}]'::jsonb, 'A', 'This is a genuine multi-step search strategy — combining the date filter with category/headline scanning — rather than a single fact lookup.'),
  ('Skedulo release notes — track what''s new each release', 10, 'A customer opens a ticket: ''Something changed in how our job dispatch screen looks, and we didn''t get any warning.'' Demonstrating this course''s core skill, how would you confirm this was a genuine release and identify exactly which note introduced it?', '[{"label": "A", "text": "Search/filter the release notes by relevant feature area and approximate timeframe, locate the specific dated entry describing a matching dispatch-screen change, and use it to confirm and explain the change to the customer"}, {"label": "B", "text": "Escalate to engineering before checking any public documentation"}, {"label": "C", "text": "Tell the customer no release notes exist for UI changes"}, {"label": "D", "text": "Assume it''s unrelated to any release since the customer wasn''t personally notified"}]'::jsonb, 'A', 'This walks through the entire expected workflow — ''tracks each release and links a customer-reported change to the note that introduced it'' — from report to specific note.'),
  ('Skedulo Pulse Platform: Setup Resources → Complete Job as a Resource', 1, 'What is the first step in this hands-on exercise, before anything else can be configured?', '[{"label": "A", "text": "Allocate Resource to Job"}, {"label": "B", "text": "Install Skedulo Mobile App"}, {"label": "C", "text": "Create Job"}, {"label": "D", "text": "Setup Resources"}]'::jsonb, 'D', 'The exercise begins with setting up the Resource, before any Job, allocation, or dispatch steps.'),
  ('Skedulo Pulse Platform: Setup Resources → Complete Job as a Resource', 2, 'Which step in the exercise is explicitly optional, and what does it let you test?', '[{"label": "A", "text": "Creating the Job — optional since jobs aren''t required"}, {"label": "B", "text": "Completing the Job as a Resource — optional since completion doesn''t matter"}, {"label": "C", "text": "Installing the Mobile App — optional since the web app is sufficient"}, {"label": "D", "text": "Setting up an Additional Region — it lets you test scheduling across more than one geographic area"}]'::jsonb, 'D', '''Set up Additional Region (optional)'' is the one explicitly optional step, distinct from the required core sequence.'),
  ('Skedulo Pulse Platform: Setup Resources → Complete Job as a Resource', 3, 'What must be set up before a resource can be considered available to be offered a job during specific hours?', '[{"label": "A", "text": "A Region"}, {"label": "B", "text": "An Availability Template"}, {"label": "C", "text": "The Mobile App installation"}, {"label": "D", "text": "A Job Allocation"}]'::jsonb, 'B', 'Availability Templates define when a resource can be offered work, ahead of any job creation or allocation.'),
  ('Skedulo Pulse Platform: Setup Resources → Complete Job as a Resource', 4, 'What two actions does the exercise walk through to get a created Job into a resource''s hands?', '[{"label": "A", "text": "Install the app, then create the Job"}, {"label": "B", "text": "Set the Region, then delete the Job"}, {"label": "C", "text": "Complete the Job, then create it"}, {"label": "D", "text": "Allocate the Resource to the Job, then Dispatch the Job"}]'::jsonb, 'D', 'Allocation and dispatch are the two actions that move a created Job from unstaffed to being with the resource.'),
  ('Skedulo Pulse Platform: Setup Resources → Complete Job as a Resource', 5, 'What are the final two steps of the exercise once a job has been dispatched?', '[{"label": "A", "text": "Reassign the Job and archive the Region"}, {"label": "B", "text": "Create a second Job and delete the first"}, {"label": "C", "text": "Change the Availability Template and repeat allocation"}, {"label": "D", "text": "Log in to the Mobile App as that Resource, and Complete the Job as a Resource"}]'::jsonb, 'D', 'The exercise closes with the mobile-side steps: logging in as the Resource and completing the Job.'),
  ('Skedulo Pulse Platform: Setup Resources → Complete Job as a Resource', 6, 'Why does the exercise have you personally install the mobile app and log in as the Resource, rather than only checking Job status from the admin web app?', '[{"label": "A", "text": "Because a Resource cannot exist without the mobile app being installed first"}, {"label": "B", "text": "Because mobile installation is required before any Job can be created"}, {"label": "C", "text": "Because the admin web app cannot show Job status at all"}, {"label": "D", "text": "To directly experience the resource-facing side of the workflow, including how dispatch and completion actually appear and behave on the device"}]'::jsonb, 'D', 'The point of the mobile step is firsthand experience of the field-worker workflow, not a technical prerequisite for earlier steps.'),
  ('Skedulo Pulse Platform: Setup Resources → Complete Job as a Resource', 7, 'Partway through this exercise, after dispatching the job you don''t see it appear when you log in to the mobile app as the Resource. What should you double-check first, based on the exercise''s sequence?', '[{"label": "A", "text": "Whether a second Region was created, since that''s unrelated to this resource''s dispatch"}, {"label": "B", "text": "Whether the tenant''s release notes mention a recent bug"}, {"label": "C", "text": "Whether the Job''s custom fields are filled in, since those don''t affect dispatch visibility"}, {"label": "D", "text": "Whether the Availability Template was actually set up and covers the time you''re testing, since a resource without matching availability may not receive the dispatch as expected"}]'::jsonb, 'D', 'This requires reasoning about which earlier step (availability) would explain a downstream symptom (job not appearing after dispatch), not just recalling the step list.'),
  ('Skedulo Pulse Platform: Setup Resources → Complete Job as a Resource', 8, 'A new hire completes this exercise but skips ''Complete Job as a Resource,'' closing the browser once the job appears on mobile. What''s actually missing from their verification that the full cycle works?', '[{"label": "A", "text": "They haven''t confirmed resource-side completion works — only that dispatch and visibility work, not the final step of the workflow"}, {"label": "B", "text": "They need to reinstall the mobile app, since that''s the actual gap"}, {"label": "C", "text": "They need to redo the Region setup, since that''s the missing piece"}, {"label": "D", "text": "Nothing — seeing the job appear is sufficient proof the whole cycle works"}]'::jsonb, 'A', 'Each stage of the exercise verifies a distinct part of the pipeline; skipping the last step leaves a real, not cosmetic, gap in verification.'),
  ('Skedulo Pulse Platform: Setup Resources → Complete Job as a Resource', 9, 'A trainee asks why they can''t just create the Job first and set up the Resource and Availability Template afterward, since ''it should all end up configured either way.'' What''s the practical answer?', '[{"label": "A", "text": "Allocation depends on a Resource with defined availability already existing, so doing it out of order can make allocation fail or behave unpredictably during the exercise, even though the end configuration looks the same"}, {"label": "B", "text": "There''s no practical difference — order never matters in Skedulo"}, {"label": "C", "text": "Availability Templates can only be created after a Job exists"}, {"label": "D", "text": "Creating the Job first is actually required and enforced automatically by the system"}]'::jsonb, 'A', 'This requires explaining the underlying dependency between allocation and an already-configured resource/availability, not just reciting the listed step order.'),
  ('Skedulo Pulse Platform: Setup Resources → Complete Job as a Resource', 10, 'You''re asked to confirm a new team member has genuinely completed this exercise, not just read through the steps. Which single piece of evidence best demonstrates they''ve done the full exercise, setup through mobile completion?', '[{"label": "A", "text": "A screenshot of the Job Allocation showing ''Dispatched'' status only, with nothing further"}, {"label": "B", "text": "A Resource record created with no Job ever allocated"}, {"label": "C", "text": "A completed Job, marked Completed by the Resource from the mobile app, with an underlying Resource, Availability Template, and dispatched Job Allocation all correctly configured beforehand"}, {"label": "D", "text": "A Region created with no Job, Resource, or Availability Template involved"}]'::jsonb, 'C', 'This verifies the full expectation end to end — resource, region, availability, job, allocation, dispatch, and mobile completion — rather than one isolated piece.'),
  ('Skedulo Pulse Platform: Onboarding, General Settings, Preferences, Navigations, Customize Scheduling Workflow, Create and Manage Data Object, Manage Custom Fields, Using Dynamic Messaging', 1, 'What''s the difference between ''General Settings'' and ''Preferences'' in the Pulse Platform?', '[{"label": "A", "text": "General Settings apply tenant-wide, while Preferences are scoped to an individual user"}, {"label": "B", "text": "Preferences apply tenant-wide, and General Settings are per-user"}, {"label": "C", "text": "They are the same thing under two names"}, {"label": "D", "text": "General Settings only affect the mobile app"}]'::jsonb, 'A', 'This scope distinction — tenant-wide vs. per-user — is exactly how the two topics are separated in the curriculum.'),
  ('Skedulo Pulse Platform: Onboarding, General Settings, Preferences, Navigations, Customize Scheduling Workflow, Create and Manage Data Object, Manage Custom Fields, Using Dynamic Messaging', 2, 'Which topic covers reorganizing menu items so users can find features with fewer clicks?', '[{"label": "A", "text": "Using Dynamic Messaging"}, {"label": "B", "text": "Navigations"}, {"label": "C", "text": "Manage Custom Fields"}, {"label": "D", "text": "Create and Manage Data Object"}]'::jsonb, 'B', 'Navigations is the topic for configuring and reorganizing menu structure.'),
  ('Skedulo Pulse Platform: Onboarding, General Settings, Preferences, Navigations, Customize Scheduling Workflow, Create and Manage Data Object, Manage Custom Fields, Using Dynamic Messaging', 3, 'What''s the distinction between ''Create and Manage Data Object'' and ''Manage Custom Fields''?', '[{"label": "A", "text": "Custom Fields can only be added to standard Salesforce objects, never Pulse Platform objects"}, {"label": "B", "text": "Data Objects are mobile-only, and Custom Fields are web-only"}, {"label": "C", "text": "Creating a Data Object adds a brand-new record type, while Managing Custom Fields adds new fields to an object that already exists"}, {"label": "D", "text": "They''re interchangeable terms for the same task"}]'::jsonb, 'C', 'These are two distinct actions taught separately: building a new object type versus extending an existing one.'),
  ('Skedulo Pulse Platform: Onboarding, General Settings, Preferences, Navigations, Customize Scheduling Workflow, Create and Manage Data Object, Manage Custom Fields, Using Dynamic Messaging', 4, 'What does ''Customize Scheduling Workflow'' let an admin change?', '[{"label": "A", "text": "How release notes are filtered"}, {"label": "B", "text": "How a job moves through its statuses/steps during scheduling"}, {"label": "C", "text": "Which fonts appear in the mobile app"}, {"label": "D", "text": "How resources log in via SSO"}]'::jsonb, 'B', 'This topic governs the job''s status/step flow through the scheduling process.'),
  ('Skedulo Pulse Platform: Onboarding, General Settings, Preferences, Navigations, Customize Scheduling Workflow, Create and Manage Data Object, Manage Custom Fields, Using Dynamic Messaging', 5, 'What kind of functionality does ''Using Dynamic Messaging'' configure?', '[{"label": "A", "text": "Static text shown on the login screen"}, {"label": "B", "text": "Manual one-off emails sent by an admin"}, {"label": "C", "text": "Read-only announcements visible only to admins"}, {"label": "D", "text": "Automated, condition-based messages sent to resources, such as an SMS when a job''s start time changes"}]'::jsonb, 'D', 'Dynamic Messaging is specifically about automated, triggered communications to resources.'),
  ('Skedulo Pulse Platform: Onboarding, General Settings, Preferences, Navigations, Customize Scheduling Workflow, Create and Manage Data Object, Manage Custom Fields, Using Dynamic Messaging', 6, 'In this course''s own sequence, which topic comes first: Onboarding or Customize Scheduling Workflow?', '[{"label": "A", "text": "Preferences comes before both"}, {"label": "B", "text": "Onboarding"}, {"label": "C", "text": "They''re taught simultaneously"}, {"label": "D", "text": "Customize Scheduling Workflow"}]'::jsonb, 'B', 'Onboarding is the first topic in the Setup & Configuration sequence, before the more advanced customization topics.'),
  ('Skedulo Pulse Platform: Onboarding, General Settings, Preferences, Navigations, Customize Scheduling Workflow, Create and Manage Data Object, Manage Custom Fields, Using Dynamic Messaging', 7, 'Two admins on the same tenant keep ''fixing'' each other''s configuration because one keeps changing a setting they believe is personal, but it''s actually resetting the display for the whole team. What''s going wrong, and how would you resolve it?', '[{"label": "A", "text": "This is a Navigations vs. Manage Custom Fields issue, unrelated to scope"}, {"label": "B", "text": "The admin is likely editing a tenant-wide General Setting believing it''s a personal Preference; point them to the correct scope so only their own view changes"}, {"label": "C", "text": "This can''t be explained by any setting — it must be a permissions bug"}, {"label": "D", "text": "This is an Onboarding vs. Dynamic Messaging issue, unrelated to scope"}]'::jsonb, 'B', 'Diagnosing this requires correctly applying the General Settings vs. Preferences scope distinction to a real symptom, not just defining the two terms.'),
  ('Skedulo Pulse Platform: Onboarding, General Settings, Preferences, Navigations, Customize Scheduling Workflow, Create and Manage Data Object, Manage Custom Fields, Using Dynamic Messaging', 8, 'A customer wants resources notified automatically the moment their next job''s start time shifts by more than 15 minutes, with no admin sending anything manually. Which topic covers this, and what would you check first if it isn''t working?', '[{"label": "A", "text": "Using Dynamic Messaging — check whether the messaging rule/condition is enabled and correctly configured for that trigger"}, {"label": "B", "text": "Customize Scheduling Workflow — this only affects job status steps, not messaging"}, {"label": "C", "text": "General Settings — too broad, not specific to messaging rules"}, {"label": "D", "text": "Navigations — this only affects menu layout"}]'::jsonb, 'A', 'This requires connecting a described automated-notification requirement to the correct topic and reasoning about what to check first, not just naming the topic.'),
  ('Skedulo Pulse Platform: Onboarding, General Settings, Preferences, Navigations, Customize Scheduling Workflow, Create and Manage Data Object, Manage Custom Fields, Using Dynamic Messaging', 9, 'You''re building a new ''Site Visit'' object with three custom fields, and the customer then wants schedulers to see a shortcut to it in their main menu. Which topics does this span, and in what order should you tackle them?', '[{"label": "A", "text": "Only Manage Custom Fields is needed, since objects and fields are the same thing"}, {"label": "B", "text": "Create and Manage Data Object and Manage Custom Fields first (to build the object and fields), then Navigations (to add the menu shortcut)"}, {"label": "C", "text": "Only Dynamic Messaging is needed, since menu items are a messaging feature"}, {"label": "D", "text": "Navigations first, then Create and Manage Data Object, since the menu item must exist before the object"}]'::jsonb, 'B', 'This requires sequencing multiple topics correctly based on technical dependency — the object must exist before it can be added to navigation.'),
  ('Skedulo Pulse Platform: Onboarding, General Settings, Preferences, Navigations, Customize Scheduling Workflow, Create and Manage Data Object, Manage Custom Fields, Using Dynamic Messaging', 10, 'You''re configuring a brand-new tenant end-to-end per this course''s scope: initial setup, org-wide settings, user-level preferences, menu structure, a customized job status flow, a new custom object with fields, and automatic SMS updates. Which single step, if skipped, would most directly break the automatic SMS updates specifically?', '[{"label": "A", "text": "Skipping Navigations, since menu placement affects whether messages send"}, {"label": "B", "text": "Skipping Dynamic Messaging configuration — without it enabled and configured, no automated messages, including SMS, will be sent regardless of everything else"}, {"label": "C", "text": "Skipping Create and Manage Data Object, since messaging depends on having a custom object first"}, {"label": "D", "text": "Skipping Preferences, since personal settings control SMS delivery"}]'::jsonb, 'B', 'This exercises the full expectation-bullet scope by asking which specific piece (Dynamic Messaging) governs the one described outcome (automatic SMS), rather than listing all topics generically.'),
  ('Internal Platform Deep Dive', 1, 'Which tool would you use to query Skedulo data programmatically in a single flexible request instead of multiple REST calls?', '[{"label": "A", "text": "Amplitude dashboards"}, {"label": "B", "text": "Admin Console"}, {"label": "C", "text": "GraphQL"}, {"label": "D", "text": "Datadog"}]'::jsonb, 'C', 'GraphQL is named as the core internal tool for flexible, single-request data queries.'),
  ('Internal Platform Deep Dive', 2, 'Which tool would you check for backend error logs and performance traces when diagnosing an intermittent error?', '[{"label": "A", "text": "MEX"}, {"label": "B", "text": "Twilio"}, {"label": "C", "text": "Datadog"}, {"label": "D", "text": "Analytics"}]'::jsonb, 'C', 'Datadog is the Deep Dive''s named tool for backend observability — logs, traces, and performance data.'),
  ('Internal Platform Deep Dive', 3, 'What''s the difference between ''Analytics'' and ''Amplitude dashboards'' as covered in this deep dive?', '[{"label": "A", "text": "They are the exact same tool with two names"}, {"label": "B", "text": "Analytics covers customer-facing usage reporting, while Amplitude dashboards track Skedulo''s own internal product-adoption metrics"}, {"label": "C", "text": "Analytics only covers mobile, and Amplitude only covers web"}, {"label": "D", "text": "Amplitude is customer-facing, and Analytics is internal-only"}]'::jsonb, 'B', 'These are distinct tools serving different audiences: customer-facing reporting versus internal product metrics.'),
  ('Internal Platform Deep Dive', 4, 'Which tool would you check for a tenant''s configuration, feature flags, or account-level settings from Skedulo''s internal side?', '[{"label": "A", "text": "Twilio"}, {"label": "B", "text": "Optimization"}, {"label": "C", "text": "GraphQL"}, {"label": "D", "text": "Admin Console"}]'::jsonb, 'D', 'Admin Console is the named internal tool for tenant-level configuration and account settings.'),
  ('Internal Platform Deep Dive', 5, 'What is Skedulo Plus, as distinguished from the core web app in this course?', '[{"label": "A", "text": "A deprecated legacy version of the web app"}, {"label": "B", "text": "Another name for the GraphQL layer"}, {"label": "C", "text": "A separate, premium tier of Skedulo functionality bundled as its own product line"}, {"label": "D", "text": "A free upgrade automatically applied to every tenant"}]'::jsonb, 'C', 'Skedulo Plus is listed as its own distinct product line, separate from the core web app internals.'),
  ('Internal Platform Deep Dive', 6, 'If a customer''s resources aren''t receiving SMS notifications and Dynamic Messaging is confirmed enabled on the tenant, which underlying communications tool from the deep dive should you check next?', '[{"label": "A", "text": "Twilio"}, {"label": "B", "text": "GraphQL"}, {"label": "C", "text": "MEX"}, {"label": "D", "text": "Admin Console"}]'::jsonb, 'A', 'Twilio is the named underlying communications provider, the logical next check once tenant-side messaging config is confirmed correct.'),
  ('Internal Platform Deep Dive', 7, 'A customer reports that auto-scheduling keeps suggesting resources with excessive travel time between jobs. Which topic should you investigate, and what kind of evidence would you look for there?', '[{"label": "A", "text": "Datadog — this is a scheduling logic issue, not a backend error/performance issue"}, {"label": "B", "text": "Admin Console — unrelated to per-job scheduling decisions"}, {"label": "C", "text": "Optimization — check the optimization recipe/objective configuration (e.g., whether a travel-time objective is weighted or enabled) rather than treating it as a random glitch"}, {"label": "D", "text": "Twilio — unrelated to scheduling logic"}]'::jsonb, 'C', 'This requires matching a described symptom to the correct internal system and reasoning about what evidence within it would explain the behavior, not just naming the tool.'),
  ('Internal Platform Deep Dive', 8, 'A ticket mentions ''MEX'' and you don''t immediately recognize what part of the platform it refers to. Given the deep dive''s own stated goal, what''s the appropriate next step?', '[{"label": "A", "text": "Close the ticket as invalid since MEX isn''t a recognized term"}, {"label": "B", "text": "Assume it''s a typo for ''GraphQL'' and proceed as if it were the same system"}, {"label": "C", "text": "Escalate immediately without attempting any internal lookup first"}, {"label": "D", "text": "Treat it as one of the platform''s core internal systems worth investigating, and check internal documentation or ask the team for its specific function — the course''s goal is being able to investigate a ticket touching any of these tools, not memorizing every detail upfront"}]'::jsonb, 'D', 'This tests whether the learner understands the course''s actual goal — working knowledge plus knowing where to look — rather than expecting rote memorization of every acronym.'),
  ('Internal Platform Deep Dive', 9, 'You need to determine whether a reported problem is a backend performance issue or a customer-facing scheduling-logic issue, and aren''t sure which tool to check first. Using two tools from this deep dive, how would you tell them apart?', '[{"label": "A", "text": "Check Twilio first regardless of the symptom, since it''s the most commonly broken tool"}, {"label": "B", "text": "Check Datadog first for error rates/latency/traces to rule out a backend performance problem; if that''s clean, look at Optimization for scheduling-logic causes instead"}, {"label": "C", "text": "There''s no way to distinguish these without engineering access"}, {"label": "D", "text": "Check Amplitude first, since it always identifies the root cause of both types of issues"}]'::jsonb, 'B', 'This requires a genuine diagnostic strategy — ruling out backend issues via Datadog before investigating scheduling logic via Optimization — not just naming each tool''s category.'),
  ('Internal Platform Deep Dive', 10, 'A single ticket touches several systems at once: automated messages aren''t sending, optimization suggestions look off, and the customer wants their team''s usage stats. Demonstrating the breadth this course builds, which three tools would you check, one per symptom?', '[{"label": "A", "text": "GraphQL for all three, since it can answer any data question"}, {"label": "B", "text": "Twilio (for the messaging/SMS delivery issue), Optimization (for the scheduling-suggestion issue), and Analytics (for the usage-stats request)"}, {"label": "C", "text": "Datadog for all three, since it covers every kind of issue"}, {"label": "D", "text": "Admin Console for all three, since it''s the general-purpose internal tool"}]'::jsonb, 'B', 'This directly tests the expectation to work across Skedulo''s core internal tools well enough to investigate a ticket touching any one of them, by mapping three distinct symptoms to three distinct tools.'),
  ('Shared Ticketing Process – Skedulo & Lumary + Customer Admin Account Recovery procedure', 1, 'Under the new Shared Ticketing Process, what happens to a ticket once it''s identified as belonging to the partner (Skedulo or Lumary)?', '[{"label": "A", "text": "It stays open with both parties until the issue is fully resolved with the customer"}, {"label": "B", "text": "The originating team closes their side immediately after sharing"}, {"label": "C", "text": "It''s automatically deleted and recreated in the partner''s system"}, {"label": "D", "text": "It''s marked Resolved on both sides right away"}]'::jsonb, 'A', 'The new approach explicitly replaces the old ''close on share'' habit: tickets remain open with both parties until fully closed with the customer.'),
  ('Shared Ticketing Process – Skedulo & Lumary + Customer Admin Account Recovery procedure', 2, 'How many independent identity-verification factors does the Account Recovery Procedure require before restoring a customer''s administrator access?', '[{"label": "A", "text": "One"}, {"label": "B", "text": "None, if the requester says it''s urgent"}, {"label": "C", "text": "Three"}, {"label": "D", "text": "Two"}]'::jsonb, 'D', 'Section 4.2 requires both live video verification and an out-of-band callback/written confirmation — two independent factors, not one.'),
  ('Shared Ticketing Process – Skedulo & Lumary + Customer Admin Account Recovery procedure', 3, 'Where must the contact details used to verify the requester''s identity come from?', '[{"label": "A", "text": "Whatever email or phone number the requester provides in their message"}, {"label": "B", "text": "Skedulo''s existing records (CRM, contract, or prior verified correspondence) — never from the inbound request itself"}, {"label": "C", "text": "The customer''s public website"}, {"label": "D", "text": "A quick search of the company online"}]'::jsonb, 'B', 'The procedure explicitly bars using contact details supplied in the inbound request, precisely to prevent an impersonator from supplying their own verification channel.'),
  ('Shared Ticketing Process – Skedulo & Lumary + Customer Admin Account Recovery procedure', 4, 'Why was the ticket workflow changed so that a customer''s reply to Lumary won''t auto-reopen the Skedulo ticket?', '[{"label": "A", "text": "Because Lumary tickets always take priority over Skedulo tickets"}, {"label": "B", "text": "Because Skedulo tickets can never be reopened once shared"}, {"label": "C", "text": "Because the ticket is deliberately kept On Hold – With Partner while Lumary handles it, and shouldn''t bounce back to active status just from partner-side activity"}, {"label": "D", "text": "Because it prevents the customer from replying at all"}]'::jsonb, 'C', 'This adjustment supports the On Hold – With Partner state, so partner-side replies don''t inappropriately reactivate the Skedulo-side ticket.'),
  ('Shared Ticketing Process – Skedulo & Lumary + Customer Admin Account Recovery procedure', 5, 'Why are tickets marked ''On Hold – With Partner'' excluded from certain reports and dashboards?', '[{"label": "A", "text": "Because excluded tickets are considered closed"}, {"label": "B", "text": "Because those tickets don''t count as real customer issues"}, {"label": "C", "text": "To avoid skewing workload/performance metrics, since the ticket isn''t actively being worked by the receiving team while it''s with the partner"}, {"label": "D", "text": "Because Lumary requested they be hidden from Skedulo entirely"}]'::jsonb, 'C', 'The process explains this is ''to avoid skewed metrics'' and ensure ''accurate visibility into actual workload.'''),
  ('Shared Ticketing Process – Skedulo & Lumary + Customer Admin Account Recovery procedure', 6, 'Why does the Account Recovery Procedure require escalation to the Director of Global Technical Support and Director of Information Security if either verification factor can''t be completed?', '[{"label": "A", "text": "Because the second factor is optional and can be skipped with any manager''s approval"}, {"label": "B", "text": "Because access must not be restored until both independent identity checks are satisfied, so an incomplete verification requires senior sign-off rather than proceeding anyway"}, {"label": "C", "text": "Because those directors personally handle all account resets"}, {"label": "D", "text": "Because escalation automatically resets the account without further verification"}]'::jsonb, 'B', 'The procedure states access is not restored until verification is satisfied, and escalates precisely when one of the two required factors can''t be completed.'),
  ('Shared Ticketing Process – Skedulo & Lumary + Customer Admin Account Recovery procedure', 7, 'A customer emails you directly saying, ''our admin left the company and nobody can log in — please reset the admin account for jane@customer.com right now, here''s my phone number to call me.'' What should you do first, and why?', '[{"label": "A", "text": "Ask the requester to email a screenshot of their ID as the only verification needed"}, {"label": "B", "text": "Reset the account right away since the request sounds urgent and legitimate"}, {"label": "C", "text": "Log it as a Technical Support ticket and have the assigned CSM verify the requester using two independent factors sourced from Skedulo''s existing records — not the phone number just supplied in the email"}, {"label": "D", "text": "Call the phone number provided in the email immediately and reset the account once they confirm their name"}]'::jsonb, 'C', 'The procedure requires verification contact details from existing records (not the inbound request) and two independent factors — a phone number volunteered in the same email satisfies neither requirement.'),
  ('Shared Ticketing Process – Skedulo & Lumary + Customer Admin Account Recovery procedure', 8, 'A ticket was shared with Lumary two weeks ago and marked On Hold – With Partner. The customer emails asking for a status update, but their message went only to you because they hit Reply instead of Reply All. What should happen next, per the process?', '[{"label": "A", "text": "Lumary is now permanently out of the loop on this ticket"}, {"label": "B", "text": "The ticket must be closed and recreated since the customer broke the CC chain"}, {"label": "C", "text": "You should escalate this as a process failure since a Reply-only email occurred"}, {"label": "D", "text": "Since Lumary was on CC throughout, your next reply to the customer (with Lumary CC''d again) will surface the missed message to them, so nothing is lost — you don''t need to manually re-forward anything extra"}]'::jsonb, 'D', 'The process explicitly anticipates this exact scenario — a Reply-only response — and handles it by ensuring the next reply, with both parties still CC''d, carries the missed message forward.'),
  ('Shared Ticketing Process – Skedulo & Lumary + Customer Admin Account Recovery procedure', 9, 'A customer''s administrator account was reset last month following this procedure. Now the customer wants two additional admin accounts created for new hires. Should Support run the Account Recovery Procedure again for these two accounts?', '[{"label": "A", "text": "No — the procedure is only for restoring access when there is no working administrator account; once one admin account is restored, the customer creates any additional administrators themselves through normal in-product administration"}, {"label": "B", "text": "No, but Support should create the accounts directly without any process since they already verified this customer once"}, {"label": "C", "text": "Yes, but only a Director can create the additional accounts"}, {"label": "D", "text": "Yes, every new admin account for that customer must go through the same two-factor verification indefinitely"}]'::jsonb, 'A', 'Section 4.4 states the customer re-creates additional administrators through normal in-product administration once the single verified account is restored — this isn''t a repeatable Support action.'),
  ('Shared Ticketing Process – Skedulo & Lumary + Customer Admin Account Recovery procedure', 10, 'A ticket needs two things handled: (a) it turns out to be a Lumary-side issue that needs routing, and (b) separately, the same customer''s last administrator has just left the company with no access left. Walking through both processes, what are the correct next actions for each?', '[{"label": "A", "text": "Handle both with a single email to Lumary CC''ing the customer''s new admin request"}, {"label": "B", "text": "Close both matters with one ticket since they involve the same customer at the same time"}, {"label": "C", "text": "For the Lumary issue: use ''Sync to Lumary'' to CC them and create a linked ticket, keeping it open and On Hold – With Partner until resolved with the customer. For the lost admin access: log a separate ticket and have the CSM complete two-factor identity verification from records on file before any account is reset"}, {"label": "D", "text": "Reset the admin account immediately since the customer is clearly in urgent need, then worry about the Lumary routing afterward"}]'::jsonb, 'C', 'This directly exercises ''routes a ticket shared with Lumary to the right queue and follows the customer admin account recovery steps'' as two distinct, correctly-sequenced procedures rather than conflating them.'),
  ('Skedulo AI Usage Policy + Information Security policies (customer data handling)', 1, 'Which of these are listed as ''Preferred and Pre-Approved'' AI tools at Skedulo?', '[{"label": "A", "text": "Any AI tool the employee personally prefers, as long as it''s free"}, {"label": "B", "text": "Only tools built internally by Skedulo''s own engineering team"}, {"label": "C", "text": "Any AI tool with a paid subscription, regardless of vendor"}, {"label": "D", "text": "Tools like Google Gemini, Google Workspace AI features, GitHub Enterprise Copilot, Claude (Team Plan), Cursor, and AWS Bedrock (with cost approval)"}]'::jsonb, 'D', 'The policy names this specific, inexhaustive list of pre-approved tools — approval isn''t just about cost or personal preference.'),
  ('Skedulo AI Usage Policy + Information Security policies (customer data handling)', 2, 'Which AI tools are explicitly listed as ''Not approved for use''?', '[{"label": "A", "text": "Any AI tool released in the last 12 months"}, {"label": "B", "text": "Desktop agents in fully autonomous mode, locally installed recreational AI tools, and non-locally-hosted Deepseek AI / other CCP-related AIs"}, {"label": "C", "text": "Only tools that require a login"}, {"label": "D", "text": "All free-tier AI tools, without exception"}]'::jsonb, 'B', 'These specific categories are named as not approved for use, regardless of cost or age of release.'),
  ('Skedulo AI Usage Policy + Information Security policies (customer data handling)', 3, 'What must be true before customer data (including de-identified data) can be used to train an external AI model?', '[{"label": "A", "text": "Training is always allowed if the AI tool is on the pre-approved list"}, {"label": "B", "text": "Only PII needs these protections — other data can be used freely"}, {"label": "C", "text": "Skedulo must operate within a dedicated, private tenant with contractual guarantees that data isn''t used for the provider''s general model training, that Skedulo retains control, and that data/model can be fully deleted on request"}, {"label": "D", "text": "Any data can be used for training as long as it''s marked ''Internal'' rather than ''Confidential''"}]'::jsonb, 'C', 'Section 4 requires all three of these contractual guarantees before any company or customer data trains an external model — pre-approval of the tool alone isn''t sufficient.'),
  ('Skedulo AI Usage Policy + Information Security policies (customer data handling)', 4, 'What''s the difference in how the policy treats ''Sensitive Data (PHI/PII, Confidential)'' versus general internal information, in terms of AI use?', '[{"label": "A", "text": "Sensitive data actually requires less oversight, since it''s more urgent to process"}, {"label": "B", "text": "Sensitive/Restricted or Confidential data requires the strictest approval tier (Tier 1), while non-sensitive internal or public data can be used under lighter-weight tiers"}, {"label": "C", "text": "PHI/PII can be used freely as long as it''s Skedulo''s own data, not a customer''s"}, {"label": "D", "text": "There''s no difference — all data types follow the same single approval process"}]'::jsonb, 'B', 'The tiered approval process scales oversight to data sensitivity, with Tier 1 reserved for sensitive/high-risk use.'),
  ('Skedulo AI Usage Policy + Information Security policies (customer data handling)', 5, 'Why does Tier 3 (external, purchased, or personal AI tools) still require ''basic vetting'' for non-pre-approved tools, even for non-sensitive data?', '[{"label": "A", "text": "Because the employee must confirm the tool''s security/privacy/licensing and that the provider excludes Skedulo data from model training, even when the data itself is low-risk"}, {"label": "B", "text": "Vetting only applies to Tier 1 tools, not Tier 3"}, {"label": "C", "text": "Vetting is only a suggestion, not a requirement, for Tier 3 tools"}, {"label": "D", "text": "Tier 3 tools never need vetting since they only handle public data"}]'::jsonb, 'A', 'Section 5''s Tier 3 conditions explicitly require recorded basic vetting even for non-pre-approved tools processing only public/internal data.'),
  ('Skedulo AI Usage Policy + Information Security policies (customer data handling)', 6, 'What is the purpose of the ''Human-in-the-Loop'' requirement for agentic AI tools (like autonomous desktop agents or MCP servers)?', '[{"label": "A", "text": "To ensure only executives can use agentic AI tools"}, {"label": "B", "text": "To limit agentic tools to read-only actions permanently, with no exceptions ever"}, {"label": "C", "text": "To require explicit human approval before a destructive or high-risk action (like data deletion or a configuration change) is carried out"}, {"label": "D", "text": "To require a human to manually perform every single action instead of using AI at all"}]'::jsonb, 'C', 'The policy names destructive or high-risk actions specifically as needing explicit human approval via workflow, not a blanket ban on agentic action.'),
  ('Skedulo AI Usage Policy + Information Security policies (customer data handling)', 7, 'You''re investigating a ticket and want to paste a customer''s error logs — which include some customer PII — into an AI tool to help summarize the issue. The tool isn''t on the pre-approved list, but it''s free and looks reputable. What should you do?', '[{"label": "A", "text": "Do not use it for this — Sensitive/Restricted or PHI/PII data requires Tier 1 approval, and non-pre-approved personal tools are barred from processing anything beyond public/non-sensitive internal information regardless of reputation"}, {"label": "B", "text": "Go ahead, since the tool is free and looks reputable, which is enough vetting"}, {"label": "C", "text": "Use it but delete your account afterward to remove the data"}, {"label": "D", "text": "Use it only for a few minutes since brief exposure doesn''t count as ''use''"}]'::jsonb, 'A', 'The policy is explicit that even a well-regarded tool outside the pre-approved list may never process PHI/PII, regardless of how brief or well-intentioned the use is.'),
  ('Skedulo AI Usage Policy + Information Security policies (customer data handling)', 8, 'You want to use Skedulo''s approved Claude (Team Plan) to help triage a ticket involving a healthcare customer''s PHI. Does being on the pre-approved list mean you can paste the PHI in without further thought?', '[{"label": "A", "text": "Yes, but only if the customer verbally agrees over the phone first"}, {"label": "B", "text": "Not necessarily — pre-approval covers the tool itself, but using it with Sensitive/Restricted data like PHI still falls under the strictest data-handling requirements, so when in doubt you should confirm with your manager or the Security Team rather than assume"}, {"label": "C", "text": "No — pre-approved tools can never be used with any ticket data at all"}, {"label": "D", "text": "Yes — once a tool is pre-approved, any data type can be used with it with no further consideration"}]'::jsonb, 'B', 'The policy separates ''is this tool approved'' from ''is this data type allowed in AI at all'' — PHI/PII carries its own strict requirements regardless of the tool, and Section 9 directs you to ask when unsure.'),
  ('Skedulo AI Usage Policy + Information Security policies (customer data handling)', 9, 'A vendor proposes an autonomous AI agent that automatically updates customer tenant configurations based on ticket resolutions, with no person reviewing each change. What''s missing from this proposal, per the policy''s requirements for agentic AI tools?', '[{"label": "A", "text": "Nothing is missing, since only data deletion (not configuration changes) requires human approval"}, {"label": "B", "text": "The proposal is fine as long as the agent runs on the vendor''s own servers"}, {"label": "C", "text": "Nothing is missing, as long as the agent logs its actions afterward"}, {"label": "D", "text": "Human-in-the-Loop approval for high-risk/destructive actions like configuration changes — the policy requires explicit human approval before such actions, so full autonomy here doesn''t meet the requirement"}]'::jsonb, 'D', 'Configuration changes are explicitly named alongside data deletion as requiring human-in-the-loop approval, so unsupervised full autonomy on this action fails the requirement.'),
  ('Skedulo AI Usage Policy + Information Security policies (customer data handling)', 10, 'You''re handling a ticket for a customer in a regulated industry and are unsure whether a particular AI tool and use case (summarizing a batch of records that might include PII) is allowed under the policy. What''s the correct process to follow, start to finish?', '[{"label": "A", "text": "Proceed using any pre-approved tool, since pre-approval overrides any data-sensitivity concern"}, {"label": "B", "text": "Use a personal AI tool instead, since personal tools aren''t covered by this policy"}, {"label": "C", "text": "Wait for the customer to explicitly grant permission by email, which alone is sufficient authorization under the policy"}, {"label": "D", "text": "Recognize this likely warrants caution around sensitive data; rather than guessing or proceeding, consult your manager or the Skedulo Security Team per the policy''s guidance before using any AI tool on that data, ensuring required approvals are completed first if it proceeds"}]'::jsonb, 'D', 'This directly tests ''knows when to ask before sharing it'' — the policy explicitly instructs consulting a manager or the Security Team when uncertain, rather than assuming either a pre-approved tool or customer consent alone clears the use.'),
  ('Atlassian ITSM & incident guides', 1, 'What is the definition of ''Incident Management'' in standard ITSM vocabulary?', '[{"label": "A", "text": "The process of handling routine requests like software access"}, {"label": "B", "text": "The process of responding to an unplanned event or service interruption and restoring the service to its operational state"}, {"label": "C", "text": "The process of reviewing planned infrastructure changes before they happen"}, {"label": "D", "text": "The process of tracking company assets from deployment through disposal"}]'::jsonb, 'B', 'Incident management is specifically about responding to unplanned interruptions and restoring service, not routine requests or planned changes.'),
  ('Atlassian ITSM & incident guides', 2, 'What does ''Service Request Management'' typically handle?', '[{"label": "A", "text": "Only infrastructure changes requiring approval"}, {"label": "B", "text": "Only root-cause investigations into recurring issues"}, {"label": "C", "text": "Only unplanned outages"}, {"label": "D", "text": "Routine customer requests, such as application access or software/hardware enhancements"}]'::jsonb, 'D', 'Service requests are routine, expected asks — distinct from unplanned incidents, root-cause problems, or planned changes.'),
  ('Atlassian ITSM & incident guides', 3, 'What is ''Change Management'' primarily concerned with?', '[{"label": "A", "text": "Restoring an interrupted service as quickly as possible"}, {"label": "B", "text": "Tracking hardware assets through their lifecycle"}, {"label": "C", "text": "Logging routine access requests"}, {"label": "D", "text": "Providing context and visibility around infrastructure/system modifications to avoid bottlenecks and minimize risk"}]'::jsonb, 'D', 'Change management governs planned modifications, giving visibility and control to reduce risk — a different concern than incident response.'),
  ('Atlassian ITSM & incident guides', 4, 'What''s the key difference between ''Incident Management'' and ''Problem Management''?', '[{"label": "A", "text": "Problem management is only used for hardware issues, while incident management is only for software"}, {"label": "B", "text": "Incident management always takes longer than problem management"}, {"label": "C", "text": "Incident management restores the service quickly after an unplanned interruption, while problem management investigates and addresses the underlying root cause so it doesn''t keep recurring"}, {"label": "D", "text": "They are the same process with two different names"}]'::jsonb, 'C', 'Incident management is about fast restoration; problem management is about root-cause elimination — genuinely different goals, not synonyms.'),
  ('Atlassian ITSM & incident guides', 5, 'How does ''Knowledge Management'' relate to the other ITSM processes (incident, service request, problem, change)?', '[{"label": "A", "text": "It only applies to change management"}, {"label": "B", "text": "It replaces the need for incident management entirely"}, {"label": "C", "text": "It''s unrelated to any ticket-handling process"}, {"label": "D", "text": "It''s the systematic creation and sharing of information that supports faster, more consistent resolution across all the other processes"}]'::jsonb, 'D', 'Knowledge management is a supporting practice that feeds into and improves how the other core processes are handled.'),
  ('Atlassian ITSM & incident guides', 6, 'Why does ITIL treat incident, service request, problem, and change as distinct categories rather than handling every ticket the same way?', '[{"label": "A", "text": "Every ticket type actually follows an identical resolution process regardless of category"}, {"label": "B", "text": "The categories are just historical naming conventions with no practical effect on handling"}, {"label": "C", "text": "The categories only matter for billing purposes"}, {"label": "D", "text": "Because each category needs a different response — restoring service quickly, fulfilling a routine ask, investigating a root cause, or controlling a planned modification — so mislabeling a ticket can lead to the wrong kind of handling"}]'::jsonb, 'D', 'The categories exist because each demands a different process and level of urgency; treating them interchangeably undermines the whole framework.'),
  ('Atlassian ITSM & incident guides', 7, 'A customer submits a ticket asking to have a new user added to their tenant with existing standard permissions — nothing is broken. Using standard ITSM vocabulary, how should you categorize this ticket?', '[{"label": "A", "text": "As an Incident, since any customer-submitted ticket counts as one"}, {"label": "B", "text": "As a Service Request, since it''s a routine ask rather than a response to an unplanned interruption"}, {"label": "C", "text": "As a Change, since it technically modifies the tenant"}, {"label": "D", "text": "As a Problem, since it involves user configuration"}]'::jsonb, 'B', 'Applying the vocabulary correctly means recognizing a routine access request as a Service Request, not defaulting to ''Incident'' just because it arrived as a ticket.'),
  ('Atlassian ITSM & incident guides', 8, 'The same type of scheduling error has been reported by three different customers over the past month, each logged and resolved as a separate incident. Using ITSM vocabulary, what should happen next, and why?', '[{"label": "A", "text": "This pattern should be escalated as a Problem, since repeated incidents with the same underlying cause call for root-cause investigation rather than continuing to resolve each occurrence as a standalone incident"}, {"label": "B", "text": "This should be treated as a Change, since it involves the scheduling system"}, {"label": "C", "text": "Nothing further is needed, since each incident was already individually resolved"}, {"label": "D", "text": "This should be logged as a Service Request, since the customers are asking for a fix"}]'::jsonb, 'A', 'Recognizing recurring incidents as a signal for problem management — rather than just repeated incident handling — is the genuinely applied distinction here.'),
  ('Atlassian ITSM & incident guides', 9, 'Support wants to modify a shared configuration setting that will affect several customer tenants at once, as a planned, deliberate update — not in response to any reported issue. Which ITSM category does this fall under, and why does that categorization matter?', '[{"label": "A", "text": "Change Management — because it''s a planned modification, and categorizing it this way ensures the visibility, review, and risk-minimization steps for changes are followed, rather than being pushed through informally"}, {"label": "B", "text": "Problem Management, since it involves infrastructure"}, {"label": "C", "text": "Service Request, since it originated from an internal team rather than a customer"}, {"label": "D", "text": "Incident Management, since any system modification is treated as an outage response"}]'::jsonb, 'A', 'This tests understanding of why the category matters practically — the level of process and review applied — not just naming the category.'),
  ('Atlassian ITSM & incident guides', 10, 'You''re reading a ticket thread: ''Our dispatch screen went down for 20 minutes this morning; separately, we''ve noticed this same outage has happened three times this quarter, and we''d also like a new custom field added when things are back to normal.'' How would you correctly label the three distinct elements here?', '[{"label": "A", "text": "All three should be logged as a single Change, since they all relate to the dispatch screen"}, {"label": "B", "text": "The 20-minute outage is an Incident; the recurring pattern across the quarter is a Problem worth root-cause investigation; the new custom field request is a Service Request"}, {"label": "C", "text": "The outage is a Problem, the recurring pattern is an Incident, and the custom field is a Change"}, {"label": "D", "text": "All three elements are the same type of ticket: an Incident"}]'::jsonb, 'B', 'This directly exercises ''uses standard ITSM vocabulary... when reading and writing tickets'' by requiring correct classification of three distinct elements within one realistic ticket.'),
  ('Shared Ticketing Process – Skedulo & Lumary', 1, 'What was the old approach to ticket sharing between Skedulo and Lumary, before this process was introduced?', '[{"label": "A", "text": "Tickets were never shared between the two companies"}, {"label": "B", "text": "Both teams would work the ticket independently with no communication"}, {"label": "C", "text": "The originating team would close their side of the ticket once it was shared with the partner"}, {"label": "D", "text": "The customer had to open two entirely separate tickets themselves"}]'::jsonb, 'C', 'The ''Overview'' section describes this exact prior behavior as the problem the new process was designed to fix.'),
  ('Shared Ticketing Process – Skedulo & Lumary', 2, 'What button does a Skedulo agent use to share a ticket with Lumary and create a linked ticket?', '[{"label": "A", "text": "''CC Lumary Support''"}, {"label": "B", "text": "''Sync to Lumary''"}, {"label": "C", "text": "''Escalate to Partner''"}, {"label": "D", "text": "''Transfer Ownership''"}]'::jsonb, 'B', 'The process names this specific button as the mechanism for CC''ing Lumary and creating the linked ticket.'),
  ('Shared Ticketing Process – Skedulo & Lumary', 3, 'What status should a ticket be marked as while it''s being handled by the partner?', '[{"label": "A", "text": "Pending Customer"}, {"label": "B", "text": "On Hold – With Partner"}, {"label": "C", "text": "Closed – Transferred"}, {"label": "D", "text": "Resolved"}]'::jsonb, 'B', 'This is the specific status the process defines for a ticket currently with the partner.'),
  ('Shared Ticketing Process – Skedulo & Lumary', 4, 'Why does the process require both Skedulo and Lumary''s support emails to stay CC''d throughout the conversation?', '[{"label": "A", "text": "So both parties can see all updates and stay informed, reducing the risk of messages being missed if the customer doesn''t reply to both"}, {"label": "B", "text": "Because it automatically closes the ticket once both are CC''d"}, {"label": "C", "text": "Because CC''ing is required for billing/invoicing purposes"}, {"label": "D", "text": "Because only one party is allowed to reply at any given time"}]'::jsonb, 'A', 'Continuous CC visibility is explicitly what lets both teams track updates and recover from a missed Reply-only message.'),
  ('Shared Ticketing Process – Skedulo & Lumary', 5, 'What triggers the eventual closing of a ticket that was shared with Lumary?', '[{"label": "A", "text": "The customer opening a brand-new ticket"}, {"label": "B", "text": "Simply reaching a certain number of days since it was shared"}, {"label": "C", "text": "Either party closing it unilaterally at any point for convenience"}, {"label": "D", "text": "The issue being fully resolved with the customer — confirmed either by an automatic email to Lumary if resolved on Skedulo''s side, or by Lumary notifying Skedulo if resolved on their side"}]'::jsonb, 'D', 'Section 3 states plainly: ''Do not close a ticket until the issue is fully resolved with the customer,'' with explicit notification steps for each resolution direction.'),
  ('Shared Ticketing Process – Skedulo & Lumary', 6, 'If Lumary resolves a shared ticket on their end, what should happen next?', '[{"label": "A", "text": "The customer must separately confirm resolution to Skedulo before anything happens"}, {"label": "B", "text": "Lumary lets Skedulo know, so Skedulo can close the ticket on their side"}, {"label": "C", "text": "Nothing — Lumary''s resolution has no bearing on the Skedulo-side ticket"}, {"label": "D", "text": "Skedulo automatically closes it with no notification needed"}]'::jsonb, 'B', 'Section 3 specifies this exact notification flow for a Lumary-side resolution.'),
  ('Shared Ticketing Process – Skedulo & Lumary', 7, 'A customer raises a ticket with Skedulo about a payroll sync error, and you determine it''s actually a Lumary-side issue. What are the correct next steps, in order?', '[{"label": "A", "text": "Close the Skedulo ticket immediately and tell the customer to contact Lumary directly"}, {"label": "B", "text": "Forward the customer''s email to Lumary personally with no formal ticket link"}, {"label": "C", "text": "Triage and confirm ownership belongs to Lumary, use ''Sync to Lumary'' to CC them and create a linked ticket, then mark the Skedulo ticket On Hold – With Partner while keeping it open rather than closing it"}, {"label": "D", "text": "Mark the ticket Resolved once you''ve identified it''s a Lumary issue, since your part is done"}]'::jsonb, 'C', 'This requires sequencing the actual steps correctly — triage, sync, then hold-open — rather than defaulting to the old ''close on share'' approach the process was specifically designed to replace.'),
  ('Shared Ticketing Process – Skedulo & Lumary', 8, 'A ticket has been sitting ''On Hold – With Partner'' for three weeks with no update from Lumary, and the customer is asking you for a status update. What should you check and do, based on this process?', '[{"label": "A", "text": "Tell the customer you have no way to check on a ticket shared with a partner"}, {"label": "B", "text": "Check the shared ticket thread (with both parties CC''d) for the latest status from Lumary, and reply to the customer with an update — the ticket should remain open and On Hold rather than being closed just because time has passed"}, {"label": "C", "text": "Close the ticket automatically since three weeks is long enough"}, {"label": "D", "text": "Re-share the ticket with Lumary as if it were brand new, discarding the existing linked ticket"}]'::jsonb, 'B', 'This applies the ''stays open until fully resolved'' principle and the ''both parties on CC'' mechanism to a realistic follow-up, rather than just restating the rule.'),
  ('Shared Ticketing Process – Skedulo & Lumary', 9, 'You notice your team''s ticket-volume dashboard looks unusually low this month, and you suspect it''s related to several tickets currently shared with Lumary. What''s the most likely explanation, based on this process''s reporting considerations?', '[{"label": "A", "text": "Lumary tickets are always deleted from Skedulo''s systems entirely"}, {"label": "B", "text": "Shared tickets always count double in reporting, which would make the number look artificially high, not low"}, {"label": "C", "text": "Tickets marked On Hold – With Partner are excluded from certain reports/dashboards to avoid skewing metrics, so a batch of shared tickets can make active workload appear lower than it actually is"}, {"label": "D", "text": "The dashboard is simply broken and needs an engineering fix"}]'::jsonb, 'C', 'This requires connecting the reporting-exclusion rule to a real observed symptom, not just reciting the rule.'),
  ('Shared Ticketing Process – Skedulo & Lumary', 10, 'You get a new ticket, quickly determine it belongs to Lumary, and need to route it correctly per this process. Walk through the correct end-to-end handling.', '[{"label": "A", "text": "Triage to confirm it''s a Lumary issue, use ''Sync to Lumary'' to CC them and create the linked ticket, mark it On Hold – With Partner, keep both support emails CC''d throughout, and only close it once resolution is confirmed with the customer — either via Lumary''s notification or your own confirmation"}, {"label": "B", "text": "Keep the ticket entirely private from Lumary and just monitor it yourself"}, {"label": "C", "text": "Immediately close your ticket and tell the customer to follow up with Lumary directly"}, {"label": "D", "text": "Mark it Resolved as soon as it''s shared, since sharing is the end of Skedulo''s involvement"}]'::jsonb, 'A', 'This directly demonstrates ''routes a ticket shared with Lumary to the right queue'' as a complete, correctly-sequenced workflow.'),
  ('How to Create a Linear Issue via DevRev — always via DevRev, never directly in Linear', 1, 'What is the correct way to raise a Linear issue for engineering investigation from a DevRev ticket?', '[{"label": "A", "text": "Always use the template workflow inside DevRev — never create the Linear issue directly in Linear"}, {"label": "B", "text": "Email engineering directly and ask them to create the Linear issue"}, {"label": "C", "text": "Either method works equally well, DevRev or Linear directly"}, {"label": "D", "text": "Create the issue directly in Linear, then link it manually to the DevRev ticket afterward"}]'::jsonb, 'A', 'The guide states directly: creating a Linear issue outside DevRev ''will break the integration and prevent proper tracking.'''),
  ('How to Create a Linear Issue via DevRev — always via DevRev, never directly in Linear', 2, 'What does the DevRev template automation append to the Linear issue''s description?', '[{"label": "A", "text": "Nothing — the description is left exactly as typed"}, {"label": "B", "text": "The full ticket conversation history, word for word"}, {"label": "C", "text": "The customer''s contract value and renewal date"}, {"label": "D", "text": "Customer Name, DevRev Ticket ID, and Reported By"}]'::jsonb, 'D', 'The guide names these three specific fields as auto-appended below the agent''s own description text.'),
  ('How to Create a Linear Issue via DevRev — always via DevRev, never directly in Linear', 3, 'Roughly how long does it take for the Linear issue to appear after submitting via the DevRev template?', '[{"label": "A", "text": "It requires a manual daily sync job to appear at all"}, {"label": "B", "text": "Up to 24 hours"}, {"label": "C", "text": "Instantly, with no delay"}, {"label": "D", "text": "Approximately 5 minutes"}]'::jsonb, 'D', 'Step 2 states the issue ''may take approximately 5 minutes to appear... the same as it was with Jira.'''),
  ('How to Create a Linear Issue via DevRev — always via DevRev, never directly in Linear', 4, 'Why does creating a Linear issue directly in Linear (instead of via the DevRev template) cause a problem?', '[{"label": "A", "text": "Directly created issues are automatically deleted after 24 hours"}, {"label": "B", "text": "There''s no way to link it back to the originating DevRev ticket, breaking the integration and preventing proper tracking"}, {"label": "C", "text": "Directly created issues are visible only to the person who made them"}, {"label": "D", "text": "It causes the DevRev ticket to auto-close"}]'::jsonb, 'B', 'The guide''s Step 1 gives this exact reason for the ''always use the template'' rule.'),
  ('How to Create a Linear Issue via DevRev — always via DevRev, never directly in Linear', 5, 'What are the two ways to confirm a Linear issue was successfully created from a DevRev ticket?', '[{"label": "A", "text": "Check the #support-engineering-tickets Slack channel for a confirmation notification, or look for the Linear icon appearing on the DevRev ticket"}, {"label": "B", "text": "Check the Jira dashboard, since Linear issues also appear there"}, {"label": "C", "text": "Wait for a confirmation email sent to the customer"}, {"label": "D", "text": "There''s no way to confirm — you simply have to trust it worked"}]'::jsonb, 'A', 'Step 3 names exactly these two confirmation methods.'),
  ('How to Create a Linear Issue via DevRev — always via DevRev, never directly in Linear', 6, 'What happens automatically once a Linear issue lands on the SUP team board?', '[{"label": "A", "text": "The issue is automatically assigned to a random engineer with no triage"}, {"label": "B", "text": "The Technical Support team member must manually triage it themselves"}, {"label": "C", "text": "The issue is automatically closed pending customer confirmation"}, {"label": "D", "text": "The ENG Triage Agent (an AI agent) automatically kicks off a triage process"}]'::jsonb, 'D', 'Step 4 describes this automated triage kickoff by name.'),
  ('How to Create a Linear Issue via DevRev — always via DevRev, never directly in Linear', 7, 'An engineer on your team, in a rush, creates a Linear issue directly in Linear for a bug found while investigating a DevRev ticket, planning to link it manually afterward. What''s wrong with this approach, and what should have been done instead?', '[{"label": "A", "text": "The issue is that Linear issues take too long to create this way, but the linking still works fine"}, {"label": "B", "text": "Nothing is wrong — manual linking works exactly as well as the template"}, {"label": "C", "text": "The problem is only that the customer name wasn''t included, which can be added later with no other consequence"}, {"label": "D", "text": "A directly-created Linear issue can''t be linked back to the originating DevRev ticket, breaking tracking — the template should have been used from the start, which auto-appends the customer name, DevRev ticket ID, and reporter"}]'::jsonb, 'D', 'This requires understanding the actual mechanism (no back-link path exists) rather than just knowing ''always use the template'' as a rule to recite.'),
  ('How to Create a Linear Issue via DevRev — always via DevRev, never directly in Linear', 8, 'You submitted a Linear issue via the DevRev template 10 minutes ago and don''t see the Linear icon on the ticket yet. What should you do?', '[{"label": "A", "text": "Immediately resubmit via the template again, since anything past 5 minutes definitely failed"}, {"label": "B", "text": "Create the issue directly in Linear instead, since the template clearly isn''t working"}, {"label": "C", "text": "Check the #support-engineering-tickets Slack channel for a creation confirmation, since ~5 minutes is the expected delay and 10 minutes without any confirmation may warrant a closer look, rather than assuming failure at the 1-minute mark"}, {"label": "D", "text": "Assume the integration is permanently broken and escalate to engineering leadership right away"}]'::jsonb, 'C', 'This requires correctly applying the expected ~5-minute timing and the two confirmation methods, rather than panicking immediately or abandoning the template approach.'),
  ('How to Create a Linear Issue via DevRev — always via DevRev, never directly in Linear', 9, 'An issue you raised gets escalated from the initial Support Engineering (SE) team to another engineering team. How would you see this reflected without leaving DevRev?', '[{"label": "A", "text": "There''s no way to track escalation beyond the SE team''s internal notes"}, {"label": "B", "text": "You would need to manually check Linear directly, since DevRev has no visibility into escalations"}, {"label": "C", "text": "The SE team member creates a Sub-Issue in Linear, which appears as a Child Issue on the original DevRev ticket, giving full visibility of the escalation chain"}, {"label": "D", "text": "The original DevRev ticket is closed and a completely new one created for the escalation"}]'::jsonb, 'C', 'Step 5 describes exactly this Sub-Issue → Child Issue mechanism for escalations, visible from within DevRev.'),
  ('How to Create a Linear Issue via DevRev — always via DevRev, never directly in Linear', 10, 'You need to raise an engineering issue for a customer-reported bug, and later confirm to your team lead that it was created correctly. Walk through the complete, correct process from start to confirmation.', '[{"label": "A", "text": "Ask the customer to confirm whether the issue was created, since they would be notified directly"}, {"label": "B", "text": "Raise the issue using the DevRev template (never directly in Linear), wait about 5 minutes, then confirm creation either via the #support-engineering-tickets Slack notification or by checking for the Linear icon on the DevRev ticket"}, {"label": "C", "text": "Create the issue directly in Linear for speed, then mention it in Slack afterward"}, {"label": "D", "text": "Raise it via the template, then confirm success purely by assuming it worked since no error appeared"}]'::jsonb, 'B', 'This directly demonstrates ''raises a Linear issue only through the DevRev template, and confirms it was created via the Linear icon or Slack'' as a complete, correctly-ordered process.'),
  ('Datadog Quick Start', 1, 'How many lessons make up the Datadog Quick Start course module?', '[{"label": "A", "text": "Four — Launching the Lab, Lab: Datadog Quick Start, Course Conclusion, and Feedback Survey"}, {"label": "B", "text": "Two — an intro video and a quiz"}, {"label": "C", "text": "Six, split across two modules"}, {"label": "D", "text": "Eight, one per Datadog product"}]'::jsonb, 'A', 'The course is structured as one module containing exactly these four lessons.'),
  ('Datadog Quick Start', 2, 'Which keyboard shortcut does the course teach for opening Datadog''s quick navigation menu?', '[{"label": "A", "text": "cmd/ctrl + /"}, {"label": "B", "text": "cmd/ctrl + P"}, {"label": "C", "text": "cmd/ctrl + F"}, {"label": "D", "text": "cmd/ctrl + K"}]'::jsonb, 'D', 'The course lists cmd/ctrl + K alongside the main navigation menu as a way to quickly locate data across the platform.'),
  ('Datadog Quick Start', 3, 'Per the course, what does the Catalog feature help you locate?', '[{"label": "A", "text": "User login history"}, {"label": "B", "text": "Service ownership and performance metrics"}, {"label": "C", "text": "Network firewall rules"}, {"label": "D", "text": "Billing invoices"}]'::jsonb, 'B', 'Catalog is taught specifically as the tool for finding which service and team owns something, plus its performance metrics.'),
  ('Datadog Quick Start', 4, 'Why does the course highlight ''cross-product links for correlated data'' as a navigation tool?', '[{"label": "A", "text": "Because it''s the only way to export data to a CSV"}, {"label": "B", "text": "Because it''s required just to log into Datadog"}, {"label": "C", "text": "Because an investigation often needs to move between dashboards, logs, and other Datadog products for the same underlying event, and these links jump directly between correlated views"}, {"label": "D", "text": "Because it disables notifications while investigating"}]'::jsonb, 'C', 'The course frames cross-product links as a way to follow one investigation across multiple views without losing context.'),
  ('Datadog Quick Start', 5, 'Why would a support engineer use Catalog during a ticket investigation rather than only searching logs?', '[{"label": "A", "text": "Catalog shows the exact code fix needed"}, {"label": "B", "text": "Catalog replaces the need to look at logs entirely"}, {"label": "C", "text": "Catalog tells you which service and which team owns it, so you know who to loop in or escalate to — not just what error occurred"}, {"label": "D", "text": "Catalog is only for billing questions"}]'::jsonb, 'C', 'Catalog''s role in the course is ownership lookup, which logs alone don''t provide.'),
  ('Datadog Quick Start', 6, 'Why does the course pair Bits (AI) Chat with manual navigation rather than presenting it as a replacement for dashboards?', '[{"label": "A", "text": "Because Bits Chat is required to save any dashboard changes"}, {"label": "B", "text": "Because it''s the only tool that shows logs"}, {"label": "C", "text": "Because manual navigation is disabled in trial accounts"}, {"label": "D", "text": "Bits Chat lets you ask natural-language questions to surface relevant data quickly, complementing manual navigation rather than replacing dashboards entirely"}]'::jsonb, 'D', 'The course lists Bits Chat as one of several navigation tools alongside menus and cross-product links, not as a dashboard replacement.'),
  ('Datadog Quick Start', 7, 'A ticket needs escalation to the team responsible for a failing service, but you don''t know which team owns it. Applying what the course teaches, what''s your first move in Datadog?', '[{"label": "A", "text": "Escalate directly to a Director without checking Datadog first"}, {"label": "B", "text": "Post in a general Slack channel asking ''does anyone own this?''"}, {"label": "C", "text": "Open Catalog and look up the service to identify its owning team before escalating"}, {"label": "D", "text": "Open Notebooks and start writing a summary before identifying the owner"}]'::jsonb, 'C', 'Catalog is exactly the tool the course teaches for this lookup, and doing it first avoids a blind escalation.'),
  ('Datadog Quick Start', 8, 'You''re investigating an error spike and want to see whether it''s tied to a metric spike shown on a different dashboard. Which navigation feature from the course lets you jump directly to that correlated view?', '[{"label": "A", "text": "The Course Conclusion lesson"}, {"label": "B", "text": "The cross-product links for correlated data"}, {"label": "C", "text": "The Feedback Survey"}, {"label": "D", "text": "Manually retyping the same search on every page"}]'::jsonb, 'B', 'Cross-product links are the course''s named tool for moving between correlated views of the same event.'),
  ('Datadog Quick Start', 9, 'A new teammate wants to find ''which dashboard shows service X''s error rate'' without browsing every menu. Which two navigation tools from the course would get them there fastest?', '[{"label": "A", "text": "The Feedback Survey and Course Conclusion"}, {"label": "B", "text": "Restarting the Launching the Lab lesson"}, {"label": "C", "text": "Only the main navigation menu, scrolled top to bottom"}, {"label": "D", "text": "The quick navigation menu (cmd/ctrl+K) or Bits Chat"}]'::jsonb, 'D', 'Both are named in the course specifically as fast ways to locate data across the platform.'),
  ('Datadog Quick Start', 10, 'A ticket requires you to (1) filter a dashboard to isolate one customer''s data, (2) inspect the related logs for errors, and (3) identify which team owns the failing service. Applying the Quick Start skills in order, how would you complete all three steps?', '[{"label": "A", "text": "Inspect logs first without ever filtering the dashboard, then guess the owning team"}, {"label": "B", "text": "Skip the dashboard and only check Catalog"}, {"label": "C", "text": "Use the Feedback Survey to report the issue instead of investigating"}, {"label": "D", "text": "Filter the dashboard to the customer''s scope, drill into logs to search and inspect the specific errors, then open Catalog to look up the failing service''s owning team"}]'::jsonb, 'D', 'This exercises the exact three skills the course expectation targets, in the order a real ticket would require them.'),
  ('Linear Basic Training', 1, 'According to the Basic Training guide, how do you sign into the Linear desktop app?', '[{"label": "A", "text": "A separate Linear-only username and password"}, {"label": "B", "text": "Single sign-on through Salesforce only"}, {"label": "C", "text": "No sign-in is required for the desktop app"}, {"label": "D", "text": "With your work email via Google sign-on"}]'::jsonb, 'D', 'The guide states you sign in with your work email (Google sign-on) and are taken straight to your workspace.'),
  ('Linear Basic Training', 2, 'What are the three main sidebar areas the guide says you need to know to navigate Linear efficiently?', '[{"label": "A", "text": "The sidebar, the inbox, and My Issues"}, {"label": "B", "text": "Inbox, Backlog, and Settings only"}, {"label": "C", "text": "Home, Search, and Notifications"}, {"label": "D", "text": "Projects, Views, and Cycles only"}]'::jsonb, 'A', 'The guide names exactly these three as the areas that unlock efficient navigation of the whole app.'),
  ('Linear Basic Training', 3, 'Which keyboard shortcut opens Linear''s command menu to ''do anything''?', '[{"label": "A", "text": "Cmd/Ctrl + K"}, {"label": "B", "text": "Cmd/Ctrl + N"}, {"label": "C", "text": "Cmd/Ctrl + Shift + K"}, {"label": "D", "text": "Cmd/Ctrl + L"}]'::jsonb, 'A', 'The Quick Reference table lists Cmd/Ctrl + K as the command menu shortcut.'),
  ('Linear Basic Training', 4, 'Why does the guide recommend treating your Inbox ''like email'' — reviewing it regularly and marking items read or snoozing them?', '[{"label": "A", "text": "Because the Inbox surfaces everything needing your attention (mentions, comments, status changes, assignments), and without regular review important updates get missed"}, {"label": "B", "text": "Because Linear cannot send email notifications otherwise"}, {"label": "C", "text": "Because the Inbox is only visible to team admins"}, {"label": "D", "text": "Because Inbox items disappear permanently after 24 hours"}]'::jsonb, 'A', 'The guide ties the Inbox''s purpose directly to catching mentions, comments, and assignments before they''re missed.'),
  ('Linear Basic Training', 5, 'Why is ''My Issues'' described as the best starting point for a developer''s day, rather than the team''s shared Backlog?', '[{"label": "A", "text": "My Issues can only be viewed once per day"}, {"label": "B", "text": "Because the Backlog only shows completed work"}, {"label": "C", "text": "Because Backlog is only visible to Admins"}, {"label": "D", "text": "My Issues shows everything currently assigned to that person, grouped by status, across every team they belong to — a personal to-do list, unlike the shared Backlog"}]'::jsonb, 'D', 'The guide contrasts My Issues as a personal, cross-team view against Backlog as a shared team queue.'),
  ('Linear Basic Training', 6, 'Why does each team have its own unique identifier (like ENG or SUP) prefixing every issue ID?', '[{"label": "A", "text": "Because Linear requires unique numbers company-wide with no other way to tell teams apart"}, {"label": "B", "text": "Because the identifier changes every time the issue''s status changes"}, {"label": "C", "text": "Because it determines the assignee''s permission level"}, {"label": "D", "text": "So an issue ID like SUP-123 immediately shows which team''s work it belongs to, and pasting that ID elsewhere turns it into a rich preview"}]'::jsonb, 'D', 'The guide explains the identifier as both a team marker and the basis for Linear''s rich-preview linking.'),
  ('Linear Basic Training', 7, 'You''re assigned a Support Engineering issue and want to move it from ''To-do'' to ''In Progress'' to signal you''ve started, without opening a full status menu. What''s the fastest way, per the shortcuts the guide teaches?', '[{"label": "A", "text": "Press L to add an ''in-progress'' label instead of changing status"}, {"label": "B", "text": "Press C to create a duplicate issue marked In Progress"}, {"label": "C", "text": "Open the issue and press S to change its status directly"}, {"label": "D", "text": "Email your manager to have them update it manually"}]'::jsonb, 'C', 'S is the guide''s documented shortcut for changing an issue''s status while viewing or hovering it.'),
  ('Linear Basic Training', 8, 'While creating a new issue, you want to assign it to a teammate and mark it Urgent without leaving the keyboard. Which inline shortcuts does the guide say let you do this?', '[{"label": "A", "text": "Type / for both assignee and priority"}, {"label": "B", "text": "Type # for the assignee and ~ for priority"}, {"label": "C", "text": "There''s no inline shortcut — you must always use the mouse"}, {"label": "D", "text": "Type @ to mention the teammate as assignee, and ! to set the priority"}]'::jsonb, 'D', 'The guide lists @ for assignee, # for label, ! for priority, and ~ for project as inline creation shortcuts.'),
  ('Linear Basic Training', 9, 'You just joined the workspace and aren''t sure which teams you were added to before creating your first issue. Using only the sidebar structure the guide describes, how would you check?', '[{"label": "A", "text": "Look at ''Your Teams'' in the sidebar — each team you belong to has its own collapsible section listing its issues, projects, and cycles"}, {"label": "B", "text": "There''s no way to see this without asking an Admin directly"}, {"label": "C", "text": "Check the Feedback Survey section"}, {"label": "D", "text": "Only the Backlog view shows team membership"}]'::jsonb, 'A', 'Your Teams is the guide''s named sidebar section for exactly this purpose.'),
  ('Linear Basic Training', 10, 'The expectation for this course is to navigate to the Support Engineering (SUP) team''s board and correctly label an issue you''re handling. Using only what this Basic Training guide teaches, how would you find SUP''s issues and tag one correctly?', '[{"label": "A", "text": "Type ''SUP'' into the Feedback Survey box, since that''s the only way to filter by team"}, {"label": "B", "text": "Open ''Your Teams'' in the sidebar to find the SUP team''s collapsible section with its issues, select the issue, and press L to add the correct label"}, {"label": "C", "text": "Press C to create a new issue and hope it gets auto-labeled"}, {"label": "D", "text": "Labels can only be added by an Admin, never by a regular Member"}]'::jsonb, 'B', 'Your Teams for locating SUP''s board and the L shortcut for labeling are both directly documented in this guide.'),
  ('GraphQL (Skedulo Pulse Platform)', 1, 'What HTTP method and endpoint does GraphiQL use to run queries and mutations?', '[{"label": "A", "text": "POST to /api/v2/graphql"}, {"label": "B", "text": "POST to /graphql/graphql"}, {"label": "C", "text": "GET to /graphql/query"}, {"label": "D", "text": "GET to /graphql/schema"}]'::jsonb, 'B', 'The deck lists queries and mutations as POST /graphql/graphql, distinct from the GET /graphql/schema endpoint.'),
  ('GraphQL (Skedulo Pulse Platform)', 2, 'What must external tools (outside the built-in GraphiQL playground) provide to authenticate?', '[{"label": "A", "text": "A Bearer API token"}, {"label": "B", "text": "No authentication is required for external tools"}, {"label": "C", "text": "A customer''s login password"}, {"label": "D", "text": "A Salesforce session cookie only"}]'::jsonb, 'A', 'The deck notes Bearer API token auth is required for external tools, unlike the built-in playground.'),
  ('GraphQL (Skedulo Pulse Platform)', 3, 'What has replaced the deprecated `first` pagination parameter?', '[{"label": "A", "text": "`top`, capped at 500 records"}, {"label": "B", "text": "`max`, capped at 1,000 records"}, {"label": "C", "text": "There is no replacement — pagination is no longer supported"}, {"label": "D", "text": "`limit`, which supports up to 10,000 top-level records with a dynamic ceiling"}]'::jsonb, 'D', 'The deck explicitly flags `first` as deprecated in favor of `limit`.'),
  ('GraphQL (Skedulo Pulse Platform)', 4, 'Why does omitting `orderBy` matter when paging through results with `limit`?', '[{"label": "A", "text": "Omitting orderBy automatically limits results to 10 records"}, {"label": "B", "text": "The query will fail to run at all without orderBy"}, {"label": "C", "text": "orderBy is required only for mutations, not queries"}, {"label": "D", "text": "Without a stable sort order, paging through large result sets can return records in an inconsistent order across requests"}]'::jsonb, 'D', 'The deck''s pagination rules call out orderBy as required specifically for stable paging.'),
  ('GraphQL (Skedulo Pulse Platform)', 5, 'Why do subqueries on HasMany relationships (like JobAllocations on a Job) cap at 2000 with no pagination, while top-level queries support paging up to 10,000?', '[{"label": "A", "text": "Because subqueries are a legacy feature scheduled for removal"}, {"label": "B", "text": "Because only Admin users can query HasMany relationships"}, {"label": "C", "text": "HasMany subqueries are nested within each top-level record, so allowing full pagination on both levels at once would make queries far too expensive to run"}, {"label": "D", "text": "Because subqueries always return exactly 20 records regardless of settings"}]'::jsonb, 'C', 'The deck distinguishes top-level pagination limits from the smaller, non-paginated subquery cap for exactly this reason.'),
  ('GraphQL (Skedulo Pulse Platform)', 6, 'Why does the deck stress documenting the exact query and affected record count in the ticket after running a bulk mutation?', '[{"label": "A", "text": "Because GraphQL automatically logs this for you, so documentation is a backup only"}, {"label": "B", "text": "Because Skedulo requires it for billing purposes"}, {"label": "C", "text": "Because it''s needed to close the ticket regardless of whether a mutation ran"}, {"label": "D", "text": "Because mutations write data with no undo, so if a rollback is ever needed, the documented query and count are what make that possible"}]'::jsonb, 'D', 'The ''before you run a mutation'' slide ties documentation directly to enabling a rollback.'),
  ('GraphQL (Skedulo Pulse Platform)', 7, 'A customer says a field is missing from their GraphQL response, but you can confirm the data exists in the record. Applying the ''Field-level permission denied'' fix, what should you check first, and how?', '[{"label": "A", "text": "Assume the field was deleted and recreate it from scratch"}, {"label": "B", "text": "Click ''More Details'' on the error to see exactly which field or object is blocked, then check the user''s permission set for read access to that field"}, {"label": "C", "text": "Tell the customer GraphQL cannot return that data type"}, {"label": "D", "text": "Immediately grant System Administrator to the user to resolve it fastest"}]'::jsonb, 'B', 'The common-issue slide names ''More Details'' as the way to identify the exact blocked field before touching permission sets.'),
  ('GraphQL (Skedulo Pulse Platform)', 8, 'A resource created via a bulk API import doesn''t show up correctly in scheduling, and GraphQL queries joining Resource to Region are failing for it. What''s the most likely cause and fix?', '[{"label": "A", "text": "GraphQL doesn''t support Resource objects at all"}, {"label": "B", "text": "The resource''s user account was deactivated, so reactivate it"}, {"label": "C", "text": "The Resource is missing its Primary Region — check the import mapping and set the Primary Region field on the affected record"}, {"label": "D", "text": "The customer has exceeded their Salesforce API quota for the day"}]'::jsonb, 'C', 'This matches the deck''s ''Resource missing primary region'' common issue exactly, including the bulk-import root cause.'),
  ('GraphQL (Skedulo Pulse Platform)', 9, 'You need to update the Description field on 40 Job records in one mutation rather than sending 40 separate requests. What technique does the deck teach for this, and what''s the key risk?', '[{"label": "A", "text": "Use the `first` parameter to batch all 40 records into one write automatically"}, {"label": "B", "text": "Bulk writes are atomic, so if one record fails, none of the 40 are written"}, {"label": "C", "text": "Use aliases (like _j0, _j1, _j2...) to call updateJobs repeatedly in one mutation; since mutations run sequentially, if one fails partway through, the earlier ones have already been written"}, {"label": "D", "text": "There''s no way to batch updates — each Job must be updated in a separate mutation call"}]'::jsonb, 'C', 'The aliasing slide explains both the technique and that mutations execute sequentially, not atomically.'),
  ('GraphQL (Skedulo Pulse Platform)', 10, 'You need to find every Job Allocation with Status ''Queued'' for a specific tenant using GraphiQL, and your first attempt returns a permission-denied error. Walking through this end to end, what should you do?', '[{"label": "A", "text": "Re-run the exact same query repeatedly until the error goes away on its own"}, {"label": "B", "text": "Give up on GraphQL and ask engineering to run the query instead"}, {"label": "C", "text": "Write the query with an EQL filter like `filter: \"JobStatus == ''Queued''\"`, run it in GraphiQL; when the error appears, click ''More Details'' to identify the exact blocked field, then update the permission set or remove the field from the query"}, {"label": "D", "text": "Grant the querying user full System Administrator access without checking which field is actually blocked"}]'::jsonb, 'C', 'This exercises the exact competency the course targets: running a filtered GraphiQL query and correctly reading back a failed query''s error.'),
  ('Technical support plans and SLAs', 1, 'How many tiers of technical support plans does Skedulo offer, and what are they?', '[{"label": "A", "text": "Four — Standard, Plus, Premier, and Enterprise"}, {"label": "B", "text": "Five — Bronze, Silver, Gold, Platinum, and Enterprise"}, {"label": "C", "text": "Three — Basic, Pro, and Enterprise"}, {"label": "D", "text": "Two — Standard and Premium"}]'::jsonb, 'A', 'The documentation names exactly these four plan tiers.'),
  ('Technical support plans and SLAs', 2, 'What is the Enterprise plan''s Initial Response Time target for a Critical P1 issue?', '[{"label": "A", "text": "4 business hours"}, {"label": "B", "text": "Same business day or 8 hours"}, {"label": "C", "text": "30 minutes"}, {"label": "D", "text": "1 business hour"}]'::jsonb, 'C', 'The target response times table lists 30 minutes as Enterprise''s Critical P1 Initial Response Time.'),
  ('Technical support plans and SLAs', 3, 'How are tickets opened via email automatically categorized, per the documentation?', '[{"label": "A", "text": "They are rejected and must be resubmitted via the portal"}, {"label": "B", "text": "As low priority tickets"}, {"label": "C", "text": "As whatever priority the sender''s email signature indicates"}, {"label": "D", "text": "As Critical P1 by default"}]'::jsonb, 'B', 'The Issue priority section states this explicitly.'),
  ('Technical support plans and SLAs', 4, 'Why might Skedulo Support re-categorize a ticket''s priority even after the requester selected one in the Support Portal?', '[{"label": "A", "text": "Support automatically downgrades every ticket by one level"}, {"label": "B", "text": "Priority can never be changed once submitted"}, {"label": "C", "text": "Because only Enterprise customers are allowed to set their own priority"}, {"label": "D", "text": "Because priority may be re-categorized based on Skedulo''s criticality definitions and the issue''s actual impact, not just the requester''s initial selection"}]'::jsonb, 'D', 'The documentation notes priority may be re-categorized based on criticality definitions and actual impact.'),
  ('Technical support plans and SLAs', 5, 'Why does the Standard plan''s Critical P1 initial response (''same business day or 8 hours'') differ so much from Enterprise''s (''30 minutes'')?', '[{"label": "A", "text": "Response times are identical across all plans and only resolution times differ"}, {"label": "B", "text": "The 8-hour figure is a typo and should also read 30 minutes"}, {"label": "C", "text": "Standard plan customers are served by a different, slower company"}, {"label": "D", "text": "Each plan tier is designed with different response-time commitments so support can be catered to what the customer''s contract level requires"}]'::jsonb, 'D', 'The docs frame each plan level as offering ''additional feature sets and response times'' catered to customer needs.'),
  ('Technical support plans and SLAs', 6, 'Why does the documentation count target response times based on ''the local time zone stamp of where and when a ticket is opened,'' rather than one fixed company time zone?', '[{"label": "A", "text": "Because customers can manually choose whichever time zone gives them the fastest apparent response time"}, {"label": "B", "text": "Because response times don''t actually depend on time zone at all"}, {"label": "C", "text": "So the response-time clock reflects the customer''s actual business hours and context, not an arbitrary company-wide time zone"}, {"label": "D", "text": "Because Skedulo has no fixed headquarters time zone to use"}]'::jsonb, 'C', 'This is stated directly in the Issue priority section.'),
  ('Technical support plans and SLAs', 7, 'A Plus-plan customer opens a P1 Critical ticket reporting the Skedulo application is fully unavailable with no workaround. What Initial Response Time target applies?', '[{"label": "A", "text": "Same business day or 8 hours"}, {"label": "B", "text": "1 business hour"}, {"label": "C", "text": "30 minutes"}, {"label": "D", "text": "4 business hours"}]'::jsonb, 'D', 'The target response times table lists 4 business hours as Plus''s Critical P1 Initial Response Time.'),
  ('Technical support plans and SLAs', 8, 'A single user at an Enterprise customer reports a cosmetic spelling mistake on one screen — no functionality is affected and no one else has noticed. How should this be categorized, and what''s the Enterprise Initial Response target?', '[{"label": "A", "text": "P2 High; 2 business hours"}, {"label": "B", "text": "P4 Low (cosmetic issue affecting a single user); Enterprise''s Initial Response Time target is 8 business hours"}, {"label": "C", "text": "It cannot be logged as a ticket since it''s cosmetic"}, {"label": "D", "text": "P1 Critical, since any visible bug must be treated as critical; 30 minutes"}]'::jsonb, 'B', 'The Incident Severity chart defines P4 as cosmetic issues affecting a single/small number of users, and the response table gives Enterprise 8 business hours for Low P4.'),
  ('Technical support plans and SLAs', 9, 'A Standard-plan customer describes ''a part of the Skedulo application is unavailable, affecting two or more users, with significant impact to business process.'' Which priority level matches this, and what''s Standard''s Initial Response target for it?', '[{"label": "A", "text": "P3 Normal; As prioritised"}, {"label": "B", "text": "P1 Critical; Same business day or 8 hours"}, {"label": "C", "text": "P2 High; Standard''s Initial Response Time target is 1 business day"}, {"label": "D", "text": "P4 Low; As prioritised"}]'::jsonb, 'C', 'This description matches the P2 High criteria exactly, and Standard''s response table lists 1 business day for High P2.'),
  ('Technical support plans and SLAs', 10, 'A Premier-plan customer submits a ticket by email describing a partially degraded feature affecting a small number of users, with a workaround available. What priority does this ticket get by default, what severity does the description actually match, and what''s the correct Initial Response Time target once correctly categorized?', '[{"label": "A", "text": "Default priority is Critical since it came by email; Enterprise''s 6 business hour target applies"}, {"label": "B", "text": "Default priority is Low (email tickets are auto-categorized low), but the description matches P3 Normal (degraded functionality, workaround available); once correctly categorized, Premier''s Initial Response Time target for Normal P3 is 8 business hours"}, {"label": "C", "text": "Email tickets cannot be assigned a plan-based response time at all"}, {"label": "D", "text": "The ticket is automatically P1 because it came from a Premier customer; 1 business hour applies"}]'::jsonb, 'B', 'This exercises identifying both the default (email = low) and the correct severity re-categorization, plus reading the right cell in the Premier/P3 response table — exactly the competency this course targets.'),
  ('Atlassian SLA & service-request management guide', 1, 'Per the Atlassian guide, what does an SLA define?', '[{"label": "A", "text": "Only the price a customer pays for support"}, {"label": "B", "text": "Only the software license terms"}, {"label": "C", "text": "Only which engineers are on-call each week"}, {"label": "D", "text": "The services you will deliver, the responsiveness customers can expect, and how you will measure performance"}]'::jsonb, 'D', 'This is the guide''s own definition of a service level agreement.'),
  ('Atlassian SLA & service-request management guide', 2, 'Which components does the guide list as part of an SLA?', '[{"label": "A", "text": "Services covered, measurable performance targets, roles and responsibilities, and remedies or penalties for breaches"}, {"label": "B", "text": "Server IP addresses and firewall rules"}, {"label": "C", "text": "Marketing copy, sales contact info, and a logo"}, {"label": "D", "text": "A list of every employee''s job title"}]'::jsonb, 'A', 'The guide names exactly these four components.'),
  ('Atlassian SLA & service-request management guide', 3, 'What example response and resolution commitment does the guide give for an IT team''s SLA?', '[{"label": "A", "text": "Resolving all issues within 15 minutes no matter the type"}, {"label": "B", "text": "Responding within two hours during business hours and resolving critical issues within four hours"}, {"label": "C", "text": "No numeric commitment is ever given in an SLA"}, {"label": "D", "text": "Responding within 24 hours regardless of severity"}]'::jsonb, 'B', 'This is the guide''s own worked example of an SLA commitment.'),
  ('Atlassian SLA & service-request management guide', 4, 'Why does the guide list ''uptime and availability'' as a metric distinct from ''response time''?', '[{"label": "A", "text": "Response time replaced uptime as a metric and is no longer used"}, {"label": "B", "text": "They''re the same metric with two different names"}, {"label": "C", "text": "Uptime is only tracked for hardware, never for software services"}, {"label": "D", "text": "Uptime measures how much of the time the service itself is operationally available, while response time measures how quickly a team acknowledges a reported issue — two different things being tracked"}]'::jsonb, 'D', 'The guide separates these as distinct common metrics with different meanings.'),
  ('Atlassian SLA & service-request management guide', 5, 'Why does the guide say SLAs require ''regular review and adjustment''?', '[{"label": "A", "text": "Because SLA metrics change format every fiscal year automatically"}, {"label": "B", "text": "To remain aligned with changing business needs over time, rather than being fixed permanently at signing"}, {"label": "C", "text": "Because customers are required to renegotiate every SLA weekly"}, {"label": "D", "text": "Because SLAs legally expire after 30 days no matter what"}]'::jsonb, 'B', 'This is the guide''s own stated reason for periodic review.'),
  ('Atlassian SLA & service-request management guide', 6, 'Why does the guide tie remedies or penalties to SLA breaches?', '[{"label": "A", "text": "Penalties apply only to customers, never to the support team"}, {"label": "B", "text": "Remedies replace the need to track any other metric"}, {"label": "C", "text": "To create accountability — a consequence when the agreed performance targets aren''t met"}, {"label": "D", "text": "Penalties are purely symbolic and never actually applied"}]'::jsonb, 'C', 'Remedies/penalties are listed as one of the four core SLA components specifically for accountability.'),
  ('Atlassian SLA & service-request management guide', 7, 'A support queue commits to responding to critical tickets within four hours and maintaining 99.95% uptime. A critical ticket is acknowledged in 3 hours, but the underlying service had 99.90% uptime that month. How does this queue''s performance measure against its SLA?', '[{"label": "A", "text": "It fully breached the SLA, since not every target was hit"}, {"label": "B", "text": "It fully met the SLA, since one of the two targets was hit"}, {"label": "C", "text": "Uptime and response time are averaged together, so this is an automatic pass"}, {"label": "D", "text": "It met the response-time target but fell short of the uptime target — two separate metrics that must each be measured"}]'::jsonb, 'D', 'The guide treats each metric as independently measured against its own target, not averaged or treated as pass/fail as a whole.'),
  ('Atlassian SLA & service-request management guide', 8, 'A customer asks how their support desk''s performance is actually monitored against the SLA day-to-day. What would you tell them, per the guide''s mention of tooling?', '[{"label": "A", "text": "A customer must submit their own report to prove a breach occurred"}, {"label": "B", "text": "There''s no way to track this — SLAs are purely aspirational"}, {"label": "C", "text": "Performance is only reviewed once a year in a single manual audit"}, {"label": "D", "text": "A tool like Jira Service Management provides automated tracking, reporting, and alerts to measure actual performance against the committed targets"}]'::jsonb, 'D', 'The guide names Jira Service Management''s automated tracking, reporting, and alerts as the measurement mechanism.'),
  ('Atlassian SLA & service-request management guide', 9, 'Two SLAs both quote ''first-call resolution rate'' as a metric, but one queue resolves 80% of tickets on first contact and the other resolves 40%. What does this comparison tell you, using the guide''s framing of quality metrics?', '[{"label": "A", "text": "The two numbers are unrelated to SLA quality and only measure ticket volume"}, {"label": "B", "text": "First-call resolution rate cannot be used to compare two different queues"}, {"label": "C", "text": "A lower percentage always means faster response times"}, {"label": "D", "text": "The 80% queue is resolving far more issues without needing follow-up contact, indicating stronger first-contact quality against that specific metric"}]'::jsonb, 'D', 'First-call resolution rate is listed as a quality metric measuring exactly this kind of first-contact effectiveness.'),
  ('Atlassian SLA & service-request management guide', 10, 'Using only what this guide explains about SLAs, how would you describe to a new teammate what an SLA is and how a support queue''s performance against it gets measured?', '[{"label": "A", "text": "An SLA is a plain-language agreement defining the services delivered, expected responsiveness, and how performance is measured; a queue''s real performance is then tracked against those targets (response time, resolution time, uptime, etc.) using tools like Jira Service Management, with remedies applying if targets are missed"}, {"label": "B", "text": "A support queue''s performance against an SLA is only checked when a customer complains"}, {"label": "C", "text": "SLAs and their metrics are only relevant to Enterprise customers, never Standard ones"}, {"label": "D", "text": "An SLA is just a marketing promise with no measurable component"}]'::jsonb, 'A', 'This combines the guide''s SLA definition with its explanation of metrics, tooling, and remedies into one accurate end-to-end description.'),
  ('Escalation Workflow — the team''s Lucidchart escalation diagram', 1, 'What are the two ways a ticket can enter this escalation workflow, per the diagram''s starting points?', '[{"label": "A", "text": "Only by a customer calling a 24/7 phone line"}, {"label": "B", "text": "Only by an internal engineer manually opening a Linear issue"}, {"label": "C", "text": "Only by emailing the support team directly"}, {"label": "D", "text": "Creating a Service Cloud Case, or raising a Product Feedback/Feature Request"}]'::jsonb, 'D', 'The diagram shows exactly these two entry points at the top of the flow.'),
  ('Escalation Workflow — the team''s Lucidchart escalation diagram', 2, 'What is the first decision point every new Service Cloud Case is routed through?', '[{"label": "A", "text": "''Is the customer Enterprise tier?''"}, {"label": "B", "text": "''Is this a duplicate ticket?''"}, {"label": "C", "text": "''Has the customer paid their invoice?''"}, {"label": "D", "text": "''Critical Incident?'' — a Yes/No branch that determines the ticket''s path"}]'::jsonb, 'D', 'This is the diagram''s first decision diamond after ticket creation.'),
  ('Escalation Workflow — the team''s Lucidchart escalation diagram', 3, 'What does the ''Identify the Priority'' step link out to for guidance?', '[{"label": "A", "text": "The Salesforce release notes"}, {"label": "B", "text": "An ''Incident Severity Categorisation'' guideline"}, {"label": "C", "text": "The company''s HR policy page"}, {"label": "D", "text": "A customer satisfaction survey"}]'::jsonb, 'B', 'The diagram attaches this specific guideline note to the Identify the Priority step.'),
  ('Escalation Workflow — the team''s Lucidchart escalation diagram', 4, 'Why does the diagram route ''Critical Incident? = Yes'' tickets directly toward ''Identify the Priority'' and ''Is it really critical?'' rather than through the normal troubleshooting/search steps first?', '[{"label": "A", "text": "Critical tickets are actually given lower priority to avoid overwhelming engineers"}, {"label": "B", "text": "Critical incidents skip escalation entirely and are auto-closed"}, {"label": "C", "text": "A potential critical incident needs its severity confirmed and, if genuine, engineering engaged immediately — waiting to search the knowledge base first would slow down a real critical incident"}, {"label": "D", "text": "The routing is identical either way — there is no separate fast path"}]'::jsonb, 'C', 'The diagram gives Critical Incident tickets a direct path that bypasses the search/troubleshoot steps used for the No branch.'),
  ('Escalation Workflow — the team''s Lucidchart escalation diagram', 5, 'Why does ''Kick off the Critical Incident Process'' link out to both ''Critical incident process'' and ''On Call Engineering'' guidelines?', '[{"label": "A", "text": "Confirming a real critical incident means both following the formal incident process and pulling in the on-call engineering team who can act on it"}, {"label": "B", "text": "Those links are unrelated reference material with no bearing on the next action"}, {"label": "C", "text": "On Call Engineering is only linked for after-hours tickets, never during business hours"}, {"label": "D", "text": "The two links are duplicates of the same document"}]'::jsonb, 'A', 'Both links are attached to this exact step, covering the process and the people to notify.'),
  ('Escalation Workflow — the team''s Lucidchart escalation diagram', 6, 'Why does the ''CC CSM/Group CSM'' step specifically call out tagging the CSM via Slack ''for premium customers''?', '[{"label": "A", "text": "Because only premium customers are allowed to have a CSM assigned at all"}, {"label": "B", "text": "Premium customers get a heightened level of account-manager visibility on their tickets, so their CSM is proactively looped in rather than only notified passively"}, {"label": "C", "text": "Because CSMs are never involved in any ticket regardless of tier"}, {"label": "D", "text": "Because Slack tagging is required for every single ticket regardless of tier"}]'::jsonb, 'B', 'The premium-customer note is attached specifically to this step in the diagram.'),
  ('Escalation Workflow — the team''s Lucidchart escalation diagram', 7, 'A ticket reports the core scheduling module is fully down for all users with no workaround. Tracing this through the diagram, what is the correct path and who ends up notified?', '[{"label": "A", "text": "Critical Incident? = Yes -> Identify the Priority (using the Incident Severity Categorisation guideline) -> Is it really critical? = Yes -> Kick off the Critical Incident Process, which brings in On Call Engineering"}, {"label": "B", "text": "Critical Incident? = No -> straight to CC CSM/Group CSM only"}, {"label": "C", "text": "Skip straight to Deploy for customer since it''s urgent"}, {"label": "D", "text": "Raise it as a Product Feedback/Feature Request since it affects the whole product"}]'::jsonb, 'A', 'This is a full-outage scenario matching the diagram''s critical path exactly.'),
  ('Escalation Workflow — the team''s Lucidchart escalation diagram', 8, 'You''ve searched the Knowledge Base, Confluence, and Jira for a related fix and found nothing (Found the answer? = No) for a premium customer''s ticket. What does the diagram say to do next, and who gets looped in?', '[{"label": "A", "text": "Immediately kick off the Critical Incident Process regardless of severity"}, {"label": "B", "text": "Escalate directly to On Call Engineering without CC''ing anyone"}, {"label": "C", "text": "Close the ticket as unresolvable since no answer was found in the KB"}, {"label": "D", "text": "CC CSM/Group CSM — for a premium customer, tag their CSM via Slack in the Support channel, including a ticket summary"}]'::jsonb, 'D', 'This is exactly the diagram''s next step when the search comes up empty.'),
  ('Escalation Workflow — the team''s Lucidchart escalation diagram', 9, 'A customer reports unexpected behavior in what you determine is a Customised Feature (not core product). Continuing down this path, what should you check and note before escalating further?', '[{"label": "A", "text": "Immediately deploy a fix straight to the customer''s production org without testing"}, {"label": "B", "text": "Route it as a Core Product Feature issue instead, since customisations aren''t supported"}, {"label": "C", "text": "Skip replication entirely since customised features can''t be tested"}, {"label": "D", "text": "Try to replicate the issue in the AUHC QA environment, and if it reproduces there, note that explicitly in the ''What have been tried'' section"}]'::jsonb, 'D', 'The diagram''s Customised Feature branch includes this exact replicate-and-document step.'),
  ('Escalation Workflow — the team''s Lucidchart escalation diagram', 10, 'Walk a new ticket end-to-end: a non-critical bug report comes in, the initial troubleshooting search finds no answer, and it turns out to affect a Core Product Feature needing a fix deployed. Trace the full path and name who is notified or involved at each step.', '[{"label": "A", "text": "Critical Incident? = No -> Update the Priority -> Verification/troubleshoot (collect screenshot/error/reproduction steps) -> Search related information (KB/Confluence/Jira/Slack/as-built docs) -> Found the answer? = No -> CC CSM/Group CSM (if premium, via Slack) -> Core Product Feature branch -> Depends on the request -> Deploy for customer, following the Guideline"}, {"label": "B", "text": "The ticket is auto-closed once Found the answer? = No, since no fix exists"}, {"label": "C", "text": "The ticket skips straight to Kick off the Critical Incident Process regardless of the Critical Incident? answer"}, {"label": "D", "text": "No one besides the original support agent is ever notified during escalation"}]'::jsonb, 'A', 'This walks the complete non-critical path end to end, naming every step and who is notified — exactly the competency this course targets.'),
  ('Incident Analysis Report (Aug 2025–Aug 2026) — severity mix, detection methods, trends', 1, 'How many total valid incidents does the report cover for the August 2025 to August 2026 period?', '[{"label": "A", "text": "53"}, {"label": "B", "text": "132"}, {"label": "C", "text": "128"}, {"label": "D", "text": "97"}]'::jsonb, 'C', 'The report states 128 total valid incidents, excluding cancelled ones.'),
  ('Incident Analysis Report (Aug 2025–Aug 2026) — severity mix, detection methods, trends', 2, 'What percentage of incidents were reported by a customer before Skedulo''s own monitoring caught them?', '[{"label": "A", "text": "100%"}, {"label": "B", "text": "41%"}, {"label": "C", "text": "25%"}, {"label": "D", "text": "75% (97 incidents)"}]'::jsonb, 'D', 'This is the report''s headline ''detection gap'' figure.'),
  ('Incident Analysis Report (Aug 2025–Aug 2026) — severity mix, detection methods, trends', 3, 'How many incidents currently have an ''Unknown'' contributing factor, per the report?', '[{"label": "A", "text": "0"}, {"label": "B", "text": "53"}, {"label": "C", "text": "33"}, {"label": "D", "text": "4"}]'::jsonb, 'D', 'The report names exactly four incidents (INC-204, INC-147, INC-138, INC-129) with an Unknown contributing factor.'),
  ('Incident Analysis Report (Aug 2025–Aug 2026) — severity mix, detection methods, trends', 4, 'Why do the report''s Detection Method and Contributing Factors percentages both sum to more than 100%?', '[{"label": "A", "text": "Both fields are multi-select — some incidents have more than one detection method or more than one contributing factor tagged, so the counts overlap"}, {"label": "B", "text": "Percentages are calculated incorrectly and should be treated as a known error"}, {"label": "C", "text": "The report contains duplicate incident entries that were never deduplicated"}, {"label": "D", "text": "Every incident is required to have exactly two contributing factors by policy"}]'::jsonb, 'A', 'The report explicitly flags both fields as multi-select, explaining why totals exceed 128.'),
  ('Incident Analysis Report (Aug 2025–Aug 2026) — severity mix, detection methods, trends', 5, 'Why does the report call the 33 Critical incidents found by a customer first the ''worst-case detection failure''?', '[{"label": "A", "text": "Because Critical incidents have the highest business impact, so finding out about them from a customer rather than internal monitoring means the biggest failures went unnoticed the longest"}, {"label": "B", "text": "Because customers are never a reliable way to detect any incident"}, {"label": "C", "text": "Because Critical incidents are actually less urgent than other severities"}, {"label": "D", "text": "Because 33 is the total number of incidents in the whole report"}]'::jsonb, 'A', 'The report singles this subset out specifically because of the severity combined with the detection failure.'),
  ('Incident Analysis Report (Aug 2025–Aug 2026) — severity mix, detection methods, trends', 6, 'Why does the report treat Code/Deployment Fault and Configuration Error as a single ''cluster'' (53 incidents, 41% of the total) rather than as two unrelated categories?', '[{"label": "A", "text": "Because the two categories are actually identical and should never have been tracked separately"}, {"label": "B", "text": "Because they''re the only categories the report tracks at all"}, {"label": "C", "text": "Because they only ever occur together in the same incident"}, {"label": "D", "text": "Combined, they represent the largest and most preventable slice of all incidents, with a shared recurring pattern of post-deploy or post-package-upgrade breakage"}]'::jsonb, 'D', 'The report groups these two causes together specifically because of their shared pattern and combined scale.'),
  ('Incident Analysis Report (Aug 2025–Aug 2026) — severity mix, detection methods, trends', 7, 'A new Critical incident with Skedulo Web App down for all users is reported first by a customer, not caught by internal monitoring. Based on the report''s Theme 1 recommendation, which action would have most directly prevented this detection gap?', '[{"label": "A", "text": "Switching the incident-tracking tool from incident.io to another vendor"}, {"label": "B", "text": "Hiring more customer support agents to answer tickets faster"}, {"label": "C", "text": "Synthetic monitoring on core user journeys, per region — giving Skedulo Web App the uptime visibility it currently lacks"}, {"label": "D", "text": "Requiring customers to sign a stricter SLA"}]'::jsonb, 'C', 'This is the report''s named action for closing the detection gap on products like Skedulo Web App.'),
  ('Incident Analysis Report (Aug 2025–Aug 2026) — severity mix, detection methods, trends', 8, 'Three incidents were all Salesforce API-limit breaches the report calls ''predictable from usage trends.'' What action does the report recommend specifically to catch this pattern before it causes an incident?', '[{"label": "A", "text": "Migrate all customers off Salesforce entirely"}, {"label": "B", "text": "Ask customers to self-report when they''re near their API limit"}, {"label": "C", "text": "Manually check Salesforce API usage once per quarter"}, {"label": "D", "text": "Add API-limit and error-rate alerting"}]'::jsonb, 'D', 'The report names this exact alerting action for predictable API-limit breaches.'),
  ('Incident Analysis Report (Aug 2025–Aug 2026) — severity mix, detection methods, trends', 9, 'A Custom Solution breaks immediately after a package upgrade is deployed, and the customer discovers and reports it — matching the report''s largest preventable cluster. Which two actions does the report recommend to prevent this pattern going forward?', '[{"label": "A", "text": "Remove Custom Solutions from the product entirely"}, {"label": "B", "text": "Immediately roll back all package upgrades company-wide going forward"}, {"label": "C", "text": "Only test in production going forward since staging didn''t catch it"}, {"label": "D", "text": "Post-deploy smoke tests with canary rollouts, and a config-change review gate for Custom Solutions (peer review plus staging validation)"}]'::jsonb, 'D', 'Both actions are named in the report specifically for the deployment/configuration cluster.'),
  ('Incident Analysis Report (Aug 2025–Aug 2026) — severity mix, detection methods, trends', 10, 'Looking at both major themes together (the detection gap and the deployment/configuration cluster), what recurring pattern connects them, and what does that suggest about where Skedulo''s incident visibility is weakest?', '[{"label": "A", "text": "The recurring pattern is that incidents only happen during business hours"}, {"label": "B", "text": "In both themes, the large majority of incidents (customer-found criticals, and 44 of 53 deployment/config incidents) were detected by the customer rather than Skedulo''s own systems — showing the visibility gap is concentrated in Skedulo Web App, Skedulo Plus, Pulse Platform, and Custom Solution, especially around deployments and core availability"}, {"label": "C", "text": "The two themes are unrelated and share no common pattern"}, {"label": "D", "text": "Both themes show Skedulo''s monitoring is already sufficient and no further investment is needed"}]'::jsonb, 'B', 'This requires synthesizing both themes into the shared recurring pattern, exactly the competency this course targets.'),
  ('Account Map & Service Catalog', 1, 'Which document is the source for the Account Map''s SE team assignments, per the page?', '[{"label": "A", "text": "The Incident Analysis Report"}, {"label": "B", "text": "The terraform-core-variables GitHub repository"}, {"label": "C", "text": "The Teams Model FAQ (Solutions Engineering)"}, {"label": "D", "text": "The Service Catalog - Functional View"}]'::jsonb, 'C', 'The Account Map section cites the Teams Model FAQ as its source.'),
  ('Account Map & Service Catalog', 2, 'Where else, besides this Confluence page, is the Service Catalog also defined and must be kept in sync?', '[{"label": "A", "text": "The terraform-core-variables GitHub repository"}, {"label": "B", "text": "The Salesforce AppExchange listing"}, {"label": "C", "text": "Jira''s project configuration screen"}, {"label": "D", "text": "A shared Google Sheet with no other copies"}]'::jsonb, 'A', 'The page explicitly notes this GitHub repo as a second source of truth that must be updated alongside the wiki.'),
  ('Account Map & Service Catalog', 3, 'According to the Engineering Manager Expectations, what should exist for every supported service?', '[{"label": "A", "text": "A public status page updated hourly"}, {"label": "B", "text": "A dedicated Slack channel with over 100 members"}, {"label": "C", "text": "An up-to-date LOOM deep dive into how the service works"}, {"label": "D", "text": "A printed runbook mailed to every customer"}]'::jsonb, 'C', 'This is listed as one of the explicit Engineering Manager expectations.'),
  ('Account Map & Service Catalog', 4, 'Why does the Account Map matter specifically before escalating an issue, rather than only the Service Catalog?', '[{"label": "A", "text": "SE teams and engineering squads are the same thing under different names"}, {"label": "B", "text": "The Account Map and Service Catalog contain identical information, so either one works"}, {"label": "C", "text": "The Account Map only matters for billing disputes, never escalations"}, {"label": "D", "text": "The Account Map tells you which SE team and region a specific customer account belongs to, which is different information from which engineering squad owns a product capability"}]'::jsonb, 'D', 'The two tables answer two different escalation questions: who owns the account vs. who owns the capability.'),
  ('Account Map & Service Catalog', 5, 'Why does the Engineering Manager Expectations section treat P1/P2 issues differently from P3-and-below issues?', '[{"label": "A", "text": "P1/P2 issues require the highest priority and an immediate resolution or workaround, while P3 and below are recorded in the squad''s backlog and the Product Manager is simply notified"}, {"label": "B", "text": "There''s no actual difference — every issue gets the same treatment regardless of priority"}, {"label": "C", "text": "P1/P2 issues are handled exclusively by the Product Manager, not engineering"}, {"label": "D", "text": "P3 issues are always resolved faster because they''re simpler by definition"}]'::jsonb, 'A', 'The Expectations section states this priority-based split explicitly.'),
  ('Account Map & Service Catalog', 6, 'Why is knowing the responsible Product Manager (not just the squad) sometimes relevant when escalating, per the catalog''s structure?', '[{"label": "A", "text": "Product Managers are the only people who can create Linear tickets"}, {"label": "B", "text": "Product Managers replace engineers when investigating technical issues"}, {"label": "C", "text": "The catalog pairs each squad''s capabilities with a named Product Manager, so both the team that would investigate and the person accountable for that area''s roadmap/priority are identifiable from one lookup"}, {"label": "D", "text": "The Product Manager field is purely decorative and has no functional use"}]'::jsonb, 'C', 'Each row of the Service Catalog table includes a named Product Manager alongside the squad and Engineering Manager.'),
  ('Account Map & Service Catalog', 7, 'A ticket comes in from MedHealth Pty Limited reporting a scheduling swimlane issue. Using the Account Map and Service Catalog together, which SE team owns this account, and which squad should be consulted for a swimlane-related capability?', '[{"label": "A", "text": "MedHealth is under Catalyst; swimlane functionality is not owned by any squad"}, {"label": "B", "text": "MedHealth is under Atlantis; swimlane functionality falls under Analytics"}, {"label": "C", "text": "MedHealth is under Sked-force; swimlane functionality falls under Infrastructure"}, {"label": "D", "text": "MedHealth Pty Limited is under the Interstellar SE team; swimlane-on-platform functionality falls under the Plan squad"}]'::jsonb, 'D', 'The Account Map lists MedHealth under Interstellar, and the Service Catalog lists ''Swimlane on Platform'' under the Plan squad.'),
  ('Account Map & Service Catalog', 8, 'A customer reports that GraphQL subscriptions for job updates have stopped delivering events in real time. Which squad''s Engineering Manager should be the escalation contact, based on the Service Catalog?', '[{"label": "A", "text": "Analytics (external-facing analytics and data pipelines)"}, {"label": "B", "text": "Core Services (which owns GraphQL core API, websockets, and GraphQL subscriptions)"}, {"label": "C", "text": "MEX (mobile extensions for V3)"}, {"label": "D", "text": "AU Healthcare (Salesforce Lumary Package)"}]'::jsonb, 'B', 'The Service Catalog lists ''Websockets and GraphQL subscriptions'' explicitly under Core Services.'),
  ('Account Map & Service Catalog', 9, 'An issue affects the public booking grid and VAX''s Salesforce package for one customer. Before escalating, you check severity: it''s a P3, with a workaround available. Per the Engineering Manager Expectations, what should happen next?', '[{"label": "A", "text": "It should be recorded in the Engage Web Experience squad''s backlog, and their Product Manager (Nga Hoang) should be notified — rather than treated with P1/P2 urgency"}, {"label": "B", "text": "It should be escalated directly to the CEO since it affects a paying customer"}, {"label": "C", "text": "It must be treated as highest priority regardless of stated severity"}, {"label": "D", "text": "No further action is needed since a workaround exists, so it can be ignored indefinitely"}]'::jsonb, 'A', 'The public booking grid and VAX are listed under Engage Web Experience, and P3 issues follow the backlog-plus-PM-notification path per the Expectations.'),
  ('Account Map & Service Catalog', 10, 'A ticket reports that Mercy Connect is seeing incorrect Optimisation route suggestions. Before escalating, walk through how you''d use the Account Map and Service Catalog to identify (a) which SE team/region owns this account and (b) which squad and Product Manager own the Optimisation capability.', '[{"label": "A", "text": "Optimisation issues are always escalated straight to Infrastructure regardless of the Service Catalog entry"}, {"label": "B", "text": "Mercy Connect maps to Atlantis (US); Optimisation is owned by the Plan squad with Paul Ciappara as PM"}, {"label": "C", "text": "Mercy Connect maps to the Sked-force SE team (APAC region) in the Account Map; Optimisation (including GeoServices) is owned by the Optimization squad, with Mark Graham as Product Manager, per the Service Catalog"}, {"label": "D", "text": "The Account Map doesn''t cover Mercy Connect, so it can''t be escalated at all"}]'::jsonb, 'C', 'This requires a correct two-table lookup — account ownership and capability ownership — exactly the competency this course targets.'),
  ('DevRev To Linear SUP tickets Workflow — how a customer ticket becomes an engineering issue', 1, 'What automatically happens to a DevRev ticket once it''s escalated for engineering investigation?', '[{"label": "A", "text": "It''s emailed directly to the assigned engineer with no Linear ticket created"}, {"label": "B", "text": "It stays in DevRev only; Linear is never involved"}, {"label": "C", "text": "It''s manually re-typed into Linear by a Support Engineering lead"}, {"label": "D", "text": "It is automatically synced into Linear as a SUP-XXX ticket in the Support Engineering team, with a Slack notification posted"}]'::jsonb, 'D', 'Step 1 describes this automatic sync and Slack notification.'),
  ('DevRev To Linear SUP tickets Workflow — how a customer ticket becomes an engineering issue', 2, 'What is the correct repo label format the triage agent needs to search the right codebase?', '[{"label": "A", "text": "<repo-name>-Skedulo"}, {"label": "B", "text": "repo:<repo-name>"}, {"label": "C", "text": "Skedulo/<repo-name> (e.g., Skedulo/phoenix)"}, {"label": "D", "text": "Skedulo_<repo-name> with underscores"}]'::jsonb, 'C', 'The guide states an incorrect format will cause the triage agent to fail, and gives this exact format.'),
  ('DevRev To Linear SUP tickets Workflow — how a customer ticket becomes an engineering issue', 3, 'Roughly how long does it typically take for a newly created SUP ticket to be reviewed, per the guide?', '[{"label": "A", "text": "Exactly 24 hours, no exceptions"}, {"label": "B", "text": "Within 30 minutes, always"}, {"label": "C", "text": "Within the hour, guaranteed"}, {"label": "D", "text": "3-5 days, though longer during high volume or reduced capacity"}]'::jsonb, 'D', 'The guide states this range explicitly, with the caveat about volume and capacity.'),
  ('DevRev To Linear SUP tickets Workflow — how a customer ticket becomes an engineering issue', 4, 'Why does the guide stress writing a ''clear, detailed description'' on the DevRev ticket before the triage agent runs?', '[{"label": "A", "text": "The triage agent ignores the description entirely and only reads the DevRev issue"}, {"label": "B", "text": "Because the triage agent''s investigation quality depends directly on the ticket description — vague descriptions lead to poor or misdirected investigations"}, {"label": "C", "text": "Because the description field is the only thing customers can ever see"}, {"label": "D", "text": "A detailed description is only needed for billing purposes"}]'::jsonb, 'B', 'Step 2 states this relationship between description quality and investigation quality directly.'),
  ('DevRev To Linear SUP tickets Workflow — how a customer ticket becomes an engineering issue', 5, 'Why must a custom solution (CX repo) issue be explicitly called out in the ticket description rather than left for the agent to infer?', '[{"label": "A", "text": "The agent automatically detects CX repos with 100% accuracy every time"}, {"label": "B", "text": "The triage agent cannot infer that an issue involves a custom, customer-specific repo on its own — it needs to be told explicitly, along with the correct repo label"}, {"label": "C", "text": "Custom solutions never need a repo label at all"}, {"label": "D", "text": "Custom solution tickets skip the triage agent step entirely"}]'::jsonb, 'B', 'The guide states the agent ''cannot infer this from vague descriptions.'''),
  ('DevRev To Linear SUP tickets Workflow — how a customer ticket becomes an engineering issue', 6, 'Why does the guide route escalations to team-specific Slack channels (like #support-tickets-mex) instead of one shared channel for every team?', '[{"label": "A", "text": "So each team can follow up, provide context, or coordinate directly on issues assigned to them, without being flooded by notifications for every other team''s tickets"}, {"label": "B", "text": "Because each team only exists in Slack, not in Linear"}, {"label": "C", "text": "Because Linear cannot post to more than one channel total"}, {"label": "D", "text": "So that customers can message engineering teams directly instead of Support"}]'::jsonb, 'A', 'The team-channel table exists specifically so each team follows its own assigned tickets.'),
  ('DevRev To Linear SUP tickets Workflow — how a customer ticket becomes an engineering issue', 7, 'You escalate a SUP ticket to the Optimisation team because it can''t be resolved within Support Engineering. Which Slack channel receives the automatic notification, and what should you do if you need a faster response?', '[{"label": "A", "text": "No channel is notified automatically — you must manually message every team member"}, {"label": "B", "text": "#squad-support-engineering, since that''s the only escalation channel that exists"}, {"label": "C", "text": "#support-tickets-mex, since all escalations funnel through MEX first"}, {"label": "D", "text": "#support-tickets-optimization gets the automatic notification; if urgent, follow up directly in that channel for prioritization"}]'::jsonb, 'D', 'The team-channel table maps Optimisation to #support-tickets-optimization specifically.'),
  ('DevRev To Linear SUP tickets Workflow — how a customer ticket becomes an engineering issue', 8, 'A ticket you raised via DevRev has sat in Linear for 6 days with the correct repo label already applied, and you''re not actively watching the board. What''s the most efficient way to be personally notified the moment there''s an update?', '[{"label": "A", "text": "Manually refresh the Linear board every hour"}, {"label": "B", "text": "Re-post the same ticket every day in #squad-support-engineering"}, {"label": "C", "text": "There''s no way to get personal updates on a specific ticket"}, {"label": "D", "text": "Subscribe to the ticket via the three-dot menu -> Subscribe in Linear, which sends personal notifications without needing to watch the whole channel"}]'::jsonb, 'D', 'The guide''s Tips section names this exact subscribe mechanism.'),
  ('DevRev To Linear SUP tickets Workflow — how a customer ticket becomes an engineering issue', 9, 'The triage agent''s comment on a SUP ticket is vague and doesn''t clearly identify the root cause, and the description you wrote was fairly brief. What should you check or fix before requesting deeper investigation?', '[{"label": "A", "text": "Close the ticket and open a new one from scratch, since agent comments can''t be improved"}, {"label": "B", "text": "Ask the customer to write the technical description instead of Support"}, {"label": "C", "text": "Check whether the repo label is present and correctly formatted (Skedulo/<repo-name>), and improve the ticket description''s detail, since the agent''s output quality depends directly on it — then request deeper investigation or a draft PR"}, {"label": "D", "text": "Immediately escalate to another engineering team without reviewing the description at all"}]'::jsonb, 'C', 'Step 3 describes the support engineer''s review-and-follow-up responsibilities exactly this way.'),
  ('DevRev To Linear SUP tickets Workflow — how a customer ticket becomes an engineering issue', 10, 'A customer''s DevRev ticket about a Skedulo Plus (Native Mobile) bug needs engineering investigation. Trace this from the moment it''s escalated in DevRev through to knowing exactly which Slack channel to check if you need to chase progress.', '[{"label": "A", "text": "The DevRev ticket auto-syncs into Linear as a SUP-XXX ticket in Support Engineering, with a Slack notification posted; the triage agent investigates and comments; if Support Engineering can''t resolve it, it''s moved to the Native Mobile team, which triggers a notification to #support-tickets-native-mobile — the channel to check or chase progress in"}, {"label": "B", "text": "The ticket goes directly to #support-tickets-mex regardless of which team picks it up"}, {"label": "C", "text": "There''s no way to know which Slack channel to check — you''d have to ask around"}, {"label": "D", "text": "Native Mobile issues never go through Linear, only through direct Slack messages"}]'::jsonb, 'A', 'This traces the complete path from DevRev escalation to the correct team Slack channel — exactly the competency this course targets.')
) as v(course_title, position, question, options, correct_answer, rationale)
join courses c on c.title = v.course_title and c.track_id = (select id from tracks where name = 'Core Competency')
on conflict (course_id, position) do nothing;
